export default [{"id":14,"question":"لي دَيْنٌ عند شخصٍ، ومضت مدةٌ ولم يدفع لي شيئًا، وكان لا يستطيع أن يُؤدي دَينه، فقمتُ بالتنازل عن هذا المبلغ؛ لأني اعتبرتُه زكاة أموالي، باعتباره فقيرًا، فهو لا يملك ما يدفع به دَينه، كما عرفتُ أنه ليس لديه إلا ما يسدّ عيشه، فهل هذا جائز؟ أفيدونا أثابكم الله.","title":"حكم إسقاط الدَّين عن الزكاة لإعسار المَدِين","answer":"الجواب: المُعْسِر يجب إمهاله وإنظاره حتى يسهل الله له الوفاء؛ لقول الله سبحانه: وَإِنْ كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَى مَيْسَرَةٍ [البقرة:280]، وفي الحديث الصَّحيح يقول ﷺ: مَن أنظر مُعْسِرًا أظلَّه الله في ظلِّه يوم لا ظلَّ إلا ظله، أما إسقاط الدَّين عن الزكاة فلا، لا يجوز عند أهل العلم؛ لأنَّ الزكاة إعطاء وإيتاء، وهذا وقاية لماله، هذا مالٌ قد يحصل وقد لا يحصل، وليس فيه إيتاءٌ، ولكنه إبراءٌ، فلا يُجزئ، وعليك أن تُزَكِّي مالك، وهذا المال يبقى.","link":"https://binbaz.org.sa/fatwas/2793/حكم-اسقاط-الدين-عن-الزكاة-لاعسار-المدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0266.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":127,"question":"يقول: عليَّ دَينٌ كبيرٌ يبلغ قُرابة مئتي ألف، وأنا وكيلٌ لأخي الصَّغير، وله مال أُزكيه، فهل يجوز لي أن آخذ من هذه الزكاة؟ أفيدونا جزاكم الله خيرًا.","title":"هل يجوز للوكيل على الزكاة الأخذ منها؟","answer":"الجواب: الولي لا يأخذ الزكاة، بل يُعطيها الفقراء، ولا يأخذ لنفسه؛ لأنه مسؤولٌ ومتَّهمٌ، فولي الأيتام يُخرج زكاتهم في غيره، لا فيه هو.","link":"https://binbaz.org.sa/fatwas/3633/هل-يجوز-للوكيل-على-الزكاة-الاخذ-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0115.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":196,"question":"هل يجوز لمَن عنده رأس مالٍ أن يضعه في قطعة أرضٍ ولم يُزكه؟","title":"هل تجب الزكاة في أرض مُعدّة للإعمار؟","answer":"الجواب: إذا كان رأسُ المال قد مضى عليه الحولُ فعليه زكاته، وإن وضعه في أرضٍ قبل أن يحول عليه الحولُ ليجعلها سكنًا أو ليبني عليها عمارةً للتأجير؛ فليس في الأرض زكاة. لكن إذا أجَّر ما عمَّر فيها زكَّى الأجور إذا حال عليها الحول. وإن أراد بالأرض البيع، أراد شراءها للتِّجارة؛ يُزكيها زكاة التِّجارة إذا حال عليها وعلى المال الذي اشترى به الحولُ؛ زكَّاها إذا كانت للتجارة، للبيع. أما إذا اشترى الأرض ليُقيم عليها سكنًا فلا زكاةَ فيها، أو ليُقيم عليها محلًّا للتأجير فلا زكاةَ فيها، لكنه يُزكِّي الأجرة إذا حال عليها الحولُ.","link":"https://binbaz.org.sa/fatwas/3792/هل-تجب-الزكاة-في-ارض-معدة-للاعمار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0203.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":197,"question":"هل على المُساهمات زكاة؟","title":"ما حكم الزكاة في المساهمات؟","answer":"الجواب: المُساهمة تختلف: إن كانت المساهمة في أرضٍ للتجارة أو البيع أو في سيارات للبيع أو في أشياء للبيع؛ ففيها الزكاة كلما حال الحولُ، يُزكِّي الأصل والربح جميعًا.\nأما إن كانت المساهمة في شيءٍ يبقى -في مصنع يبقى، في أرضٍ للزراعة تُزْرَع- فلا زكاة في الأصل، وإنما يُزكي ما حصل له من الأرباح إذا حال عليها الحولُ، أو زرعها زكَّى الحبوب، وأما الأصل فلا يُزكَّى؛ لأنه مُعدٌّ للبقاء لا للبيع، فالمصنع لا يُزكَّى، والآلات لا تُزكَّى؛ لأنها مُعدَّة للبقاء لا للبيع، أما إذا جعل المالَ في شيءٍ يُباع -أرض تُباع، سيارات تباع، أبواب تباع، كراسٍ تباع، ملابس تباع- فهذا يُزكِّي الأصل والربح جميعًا؛ لأنها عروض تجارةٍ.","link":"https://binbaz.org.sa/fatwas/3794/ما-حكم-الزكاة-في-المساهمات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0204.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":324,"question":"هل يجوز تقديم موعد الزكاة قبل أن يدور الحول ودفعه لخادمةٍ تريد السفر، وهي مُسلمة؟","title":"حكم تقديم الزكاة قبل أن يحول عليها الحول","answer":"الجواب: يجوز تقديم الزكاة قبل الحول، تقديم الزكاة لا بأس به للمصلحة. أما تسليمه للخادمة فهذا محلُّ نظرٍ: الخادمة قد يكفيها مُرتّبها، يعني: أجرها، وقد تكون غير مُستقيمة، قد تكون كاذبةً في دعواها: عندها أطفال، وعندها كذا، وعندها كذا؛ فالأولى التماس الفقيرات المعلومات المُتحقق فقرهنَّ وحاجتهنَّ، حتى يُعْطَين الزكاة، وهكذا الرجال المعروفون بالحاجة.\nأما الخادمة فلعله يكفيها راتبها الذي تأخذه، فإنها تأكل وتشرب عند سيدها، وراتبها مجموعٌ لها، فلعله يكفيها، وفي إعطائها الزكاة خطرٌ، فينبغي ألا تُعطى الزكاة، اللهم إلا امرأة معروفة بالاستقامة والحاجة، وعندها أطفال كثيرون ضعاف، وراتبها قليلٌ، إذا عرف هذا عن يقينٍ، وأنها مسلمة صحيحة الإسلام؛ تُعطى، ولكن هذا قليلٌ في الخادمات؛ لأنها لا تُعرف إلا من قولها، تأتي من بلادٍ بعيدةٍ ولا يُعرف عنها إلا قولها.\nفينبغي الاحتياط في هذا، وإذا أريد الصَّدقة عليها من غير الزكاة لا بأس، تُعطى من غير الزكاة زيادة صدقةٍ؛ لا بأس، أما الزكاة فيُحتاط لها حتى لا تُعطى إلا لمَن عُرف إسلامه واستقامته وصدقه في الحاجة.","link":"https://binbaz.org.sa/fatwas/4411/حكم-تقديم-الزكاة-قبل-ان-يحول-عليها-الحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0377.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":333,"question":"ما الحكم في الفرد يظل يدَّخر من ماله المهر اللازم للزواج، فيظل مدةً تصل إلى سنوات، فهل ما تم ادِّخاره عليه زكاة أم لا؟","title":"حكم الزكاة في المال الذي يجمع ويدَّخر","answer":"الجواب: نعم، كل ما ادَّخره الإنسان يُزَكَّى، ولو أعدَّه للزواج، أو لقضاء الدَّين، أو لبناء بيتٍ، أو ما أشبه ذلك يُزَكَّى، والزكاة تزيده، لا تنقصه: خُذْ مِنْ أَمْوَالِهِمْ صَدَقَةً تُطَهِّرُهُمْ وَتُزَكِّيهِمْ بِهَا [التوبة:103]، فالزكاة طُهرة وزكاة.","link":"https://binbaz.org.sa/fatwas/4421/حكم-الزكاة-في-المال-الذي-يجمع-ويدخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0386.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":351,"question":"شخصٌ أُطالبه بدراهم، والمذكور أحواله مستورة، هل يجوز لي أن أترك له هذا المبلغ من زكاة مالي؟وسؤال آخر تابع للسؤال الأول: وهل يجوز أن أشتري شيئًا بالدَّين وأبيعه كذلك بدينٍ إلى أجلٍ مُؤَجَّلٍ؟","title":"حكم الزكاة على مدين والشراء والبيع بالدين","answer":"الجواب: هذا له حال، وهذا له حال:\nالسؤال الأول: ليس للإنسان أن يُعطي المدين ما عليه من الدَّين من أجل الزكاة؛ ليُسقط ما عليه من الدين زكاةً لماله، لا، الزكاة أداء للمال، وإيتاء للمال، وليست براءةً من المال، فإذا كان أخوك مُعْسِرًا أو فقيرًا فعليك أن تنظره، وأن تُمهله؛ لقوله سبحانه: وَإِنْ كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَى مَيْسَرَةٍ [البقرة:280]، ويقول عليه الصلاة والسلام: مَن يسَّر على مُعْسِرٍ يسَّر الله عليه في الدنيا والآخرة، ومَن أنظر مُعْسِرًا أو وضع له أظلَّه الله في ظلِّه يوم لا ظلَّ إلا ظله.\nفالواجب عليك إنظار المعسر، وإن وضعتَ عنه بعض الشيء أو كل المال فهذه صدقةٌ، ليست من الزكاة، بل صدقة تطوع؛ لقوله تعالى: وَأَنْ تَصَدَّقُوا خَيْرٌ لَكُمْ [البقرة:280]، أما جعل الدَّين زكاةً فلا؛ لأنَّ هذا وقاية للمال، ليربح هذا المال الذي عند المعسر، فيجعله وقايةً لماله، فيُؤدي به الزكاة، وهذا المال قد يحصل، وقد لا يحصل، فلا يُجعل زكاةً، ولكن يُنْظر صاحبه، أما الزكاة فيُخرجها من المال الذي عنده.\n....................... وأما الدَّين ففيه تفصيل: إذا بعتَ السلعة التي عندك؛ قد ملكتها وحُزْتها -من سيارةٍ أو غيرها- ثم بعتها إلى أجلٍ فلا بأس، إلى أجلٍ معلومٍ فلا بأس، لكن لا تبع ما ليس عندك، لا تبع ما عند الناس حتى تشتري ذلك وتحوزه ويكون في قبضتك ثم تبيع؛ لقول النبي ﷺ: لا تبع ما ليس عندك، لا يحلّ سلف وبيع، ولا بيع ما ليس عندك، ولأنه ﷺ نهى أن تُباع السلع حيث تبتاع حتى يحوزها التّجار إلى رحالهم، فلا تبع ما ليس عندك.","link":"https://binbaz.org.sa/fatwas/4440/حكم-الزكاة-على-مدين-والشراء-والبيع-بالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0404.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":396,"question":"هل يجوز أن يُخرج المسلمُ زكاةَ ماله لأخيه المُقبل على الزواج أو أخته الفقيرة؟","title":"هل يجوز دفع الزكاة للأخ والأخت؟","answer":"الجواب: نعم، إذا كان أخوه عاجزًا عن الزواج فلا بأس أن يساعده من الزكاة، وهكذا أخته الفقيرة لا بأس أن يُواسيها من الزكاة، إلا إذا كانت في بيته وكان أخوه في بيته، وهو قائمٌ بنفقته، ويستطيع ذلك؛ فلا يُعطيه الزكاة، يُعطيها غيره؛ لأنه في عياله، في مؤنته، وهو قادرٌ على ذلك، فيُعطي الزكاة غيره. أما إذا كانوا مُستقلين ويحتاجون إلى رفقه وإعانته على الزواج أو إعانة المرأة على حاجاتها؛ فلا بأس بذلك، والأحوط له إذا كان قادرًا أن يُنفق عليهما من ماله، ولو كانا بعيدين.","link":"https://binbaz.org.sa/fatwas/4783/هل-يجوز-دفع-الزكاة-للاخ-والاخت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0453.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":459,"question":"من تحمّل حَمَالة  وعنده المبلغ الذي يتحمله يجوز له أن يسأل؟","title":"هل لمن تحمّل حَمَالة أن يسأل ولو عنده مال؟","answer":"الجواب: ولو عنده مال؛ لأن هذا ما هو من أجله، هذا أنفقها في مصالح المسلمين، أنفقها في إنهاء النزاع بين الناس والفتن؛ تشجيعًا له.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/6184/هل-لمن-تحمل-حمالة-ان-يسال-ولو-عنده-مال","audio":"https://files.zadapps.info/binbaz.org.sa/7amah019.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":707,"question":"مَن كان عنده مالٌ ليس له، إنما هو أمانة، أو ثلث لميتٍ، ثم حال عليه الحول، هل يُزكيه؟","title":"حكم الزكاة في المال المحفوظ كأمانة","answer":"الجواب: إن كان وصيةً من ثلث الميت أو وقفًا ما فيه زكاة، وإن كان أمانةً عنده لغيره لا يُزكيه، يُزكيه صاحبه الذي جعله أمانةً، هو الذي يزكيه، إلا إذا وكَّله وقال: أخرج الزكاة، إذا وكَّله لا بأس، أما هو لا يتصرف، يحفظ الأمانة، ولا مانع أن ينصح صاحبها ويقول له: زَكِّها أو ائذن لي أن أُزَكِّيها، أما هو فلا يُخرجها إلا بأمرٍ من صاحب المال وتوكيلٍ منه.\nأما الأوقاف والوصايا التي يُوصي بها الأموات يُريدون بها الخير فهذه ما فيها زكاة.","link":"https://binbaz.org.sa/fatwas/20580/حكم-الزكاة-في-المال-المحفوظ-كامانة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0533فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":1021,"question":"هل يجب على الموظف الذي يتقاضى راتبًا شهريًّا زكاة في هذا الراتب، رغم أنه لا يحول عليه الحول؟ أرجو إرشادنا جزاكم الله خيرًا.","title":"هل في الراتب زكاة إذا لم يحل الحول؟","answer":"الجواب: الراتب ليس فيه زكاةٌ إذا لم يحل عليه الحول، ومَن قال: إنَّ على مَن أتاه مالٌ زكاةً في الحال، فقد غلط، إنما الزكاة تجب إذا حال الحولُ، فإذا حال الحولُ يزكَّى، فإذا كان الراتبُ محفوظًا أو بعضه حتى حال عليه الحولُ وهو يبلغ النِّصابَ زكَّاه، في المئة اثنان ونصف، أما إذا كان لا يحول عليه الحولُ، بل يصرفه في حاجاته، فلا زكاةَ عليه.\nوهكذا مَن ورث إرثًا، أو أُعطي هديةً: نقودًا، أو مساعدةً في زواجٍ، وأنفقها في الحال، ما حال عليها الحول، أنفقها في حاجاته؛ فلا زكاةَ عليه، إنما الزكاة إذا حال الحولُ على الإرث، على المال الذي ورثه، أو الذي سُوعِد به في الزواج أو غيره، إذا حال عليه الحولُ زكَّاه، أما إذا أنفقه في حاجاته قبل تمام الحول فلا زكاةَ فيه.","link":"https://binbaz.org.sa/fatwas/21055/هل-في-الراتب-زكاة-اذا-لم-يحل-الحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0851هل راتب الموظف فيه زكاة إذا لم يحول عليه الحول؟ ابن باز فتاوى المحاضرات.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":1050,"question":"إذا ادَّخر المسلمُ مبلغًا من المال كل شهرٍ، فكيف يكون حسابُ زكاته في هذا العام؟","title":"ما كيفية حساب زكاة المال المدخر شهريَّا؟","answer":"الجواب: يُزَكِّي كل شيءٍ إذا تم حوله، فالذي يدَّخره في رمضان يُزكيه في رمضان، والذي يدَّخره في شعبان يُزكيه في شعبان، والذي يدَّخره في شوال يزُكيه في شوال، والذي في ذي الحجة في ذي الحجة، وهكذا كل شيءٍ تتم سنته يُزكيه. وإذا أحبَّ أن يُزكي الجميع في أول عام يمرّ على أول راتبٍ يُزكي الجميع، ولو عجله عن بعضها فلا بأس، يكون له أجر، أما اللزوم فلا يلزم، كل راتبٍ إلا في محلِّه، كل شيءٍ إذا تمَّ حوله.","link":"https://binbaz.org.sa/fatwas/21105/ما-كيفية-حساب-زكاة-المال-المدخر-شهريا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0901إذا أدخر المسلم مبلغ من المال كل شهر فكيف يكون حساب زكاته في نهاية العام؟ ابن باز.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":1497,"question":"الواجب في إخراج الزكاة من عين المال أو يُجزئ من القيمة، مثلًا لو وجبت على الإنسان شاة أو تبيعة أو بنت مخاض أو ما أشبه ذلك؟","title":"هل يجب إخراج الزكاة من عين المال؟","answer":"الجواب:\nالواجب إخراجها إذا تيسَّر من عين المال. ويُخرج القيمة إذا ما تيسَّر المال أو صار أنفع للفقراء.","link":"https://binbaz.org.sa/fatwas/21596/هل-يجب-اخراج-الزكاة-من-عين-المال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الواجب في إخراج الزكاة من عين المال أو القيمة.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":1523,"question":"الأصناف الثمانية الذين ذكرهم الله  يُبدأ بالأول فالأول في الزكاة والصَّدقات؟","title":"مَنْ الأوْلى بالبدء في أصناف الزكاة والصدقة؟","answer":"الجواب:\nأحقهم الفقراء، بدأ بهم الربّ جل وعلا. والمساكين تبعهم؛ لأن المسكين الذي يجد بعض الشيء، والفقير أشد حاجة. والعامل عليها: العمال الذين يبعثهم ولي الأمر ليقبضونها من الناس؛ لأنها أجرة لهم. والمؤلفة قلوبهم لهم أحوال: قد تشتد الحاجة إليهم، وقد لا تشتد الحاجة إليهم. فالمؤمن يتحرى بصدقته الأحوج فالأحوج، والأصلح فالأصلح.","link":"https://binbaz.org.sa/fatwas/21622/من-الاولى-بالبدء-في-اصناف-الزكاة-والصدقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كيفية صرف الصدقات والزكاة على الأصناف الثمانية المذكورين في القرآن.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":1571,"question":"لو أخرج الزكاةَ ليتصرف فيها للفقراء: فهل مثلًا يرى أقاربه أوْلى بهذا الأمر، فيُعطي أقاربه من هذا المال؟","title":"هل الزكاة للقريب أفضل أم للأشد حاجة؟","answer":"الجواب:\nيعمل الأصلح، إذا كان أقاربه فقراء يُعطهم؛ لأنه مُوَكَّل، فلا يحيد، لا يُعطيهم وهم ليسوا بأهلٍ، لكن إذا كان هناك فقراء أشدّ حاجة منهم يعتني بالأشد.","link":"https://binbaz.org.sa/fatwas/21674/هل-الزكاة-للقريب-افضل-ام-للاشد-حاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إخراج الزكاة وإنفاقها على مستحقيها.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":1621,"question":"صدقة المرأة على زوجها هل هي تطوع؟","title":"حكم صدقة المرأة وزكاتها لزوجها","answer":"الجواب:\nتطوع، والزكاة فيها خلاف، والأرجح جوازها في الزكاة.","link":"https://binbaz.org.sa/fatwas/21726/حكم-صدقة-المراة-وزكاتها-لزوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صدقة المرأة على زوجها.mp3","categories":["إخراج الزكاة وأهلها","صدقة التطوع"]},{"id":1628,"question":"رجل عمل حادثًا: صدم سيارةً، وكلفت السيارة تقريبًا عشرة آلاف أو ثلاثة عشر ألفًا، فهل يجوز أن ندفع له الزكاة؟","title":"حكم دفع الزكاة لمن وقع عليه حادث","answer":"الجواب:\nنعم إذا كان فقيرًا.\nس: هو يأخذ راتبًا لكن عنده عائلة؟\nج: إذا كان فقيرًا وراتبه ما يكفيه يتصدَّق عليه.\nس: لأجل أنَّ هذا ظرف طارئ؟\nج: إذا كان فقيرًا لا يستطيع؛ يُعْطَى.","link":"https://binbaz.org.sa/fatwas/21733/حكم-دفع-الزكاة-لمن-وقع-عليه-حادث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/دفع الزكاة لمن كان عليه حادث.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":2118,"question":"كيف نعرف الفقير والمسكين؟ وكيف نُفَرِّق بينهما؟","title":"ما الفرق بين الفقير والمسكين؟","answer":"الجواب:\nمَن ظاهره الفقر تُعْطِه.\nس: كُلٌّ يدَّعي اليوم الفقر؟\nج: ولو، تسأل عنه إذا كانت عندك زكاة، فتسأل الذين يعرفون حاله، وإذا لم يكن فيه شيءٌ يدل على غناه تُعطه، فالرسول ﷺ لما تقدَّم إليه شخصان قويَّان قال: إن شئتُما أعطيتُكما، ولا حظَّ فيها لغنيٍّ، ولا لقويٍّ مُكْتَسِبٍ، فعليك أن تُعلمه وأنت تعطيه الزكاة وتقول: إن كنتَ من أهلها فلا بأس، إذا كنت تشكّ.\nس: ما تعريف الفقير؟ وما تعريف المسكين؟\nج: الفقير: شديد الحاجة، والمسكين: الذي عنده بعض الشيء.\nس: عنده بعض الشيء في خلال العام أم اليوم؟\nج: لا، العام، فعنده كسبٌ ولكن لا يكفيه.\nس: قد يكون قويًّا ولكن لا يجد عملًا؟\nج: يُعْطَى من الزكاة، لا بدّ القويّ عنده كسبٌ، والذي ما عنده كسبٌ يُعْطَى.","link":"https://binbaz.org.sa/fatwas/22236/ما-الفرق-بين-الفقير-والمسكين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الفرق بين الفقير والمسكين.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":2345,"question":"رجل أُعطي صدقات كثيرة جدًّا، ومرَّت عليها سنة عنده، هل تُزَكَّى أو ما عليها زكاة؟","title":"هل على الصدقات زكاة إذا تأخر إخراجُها؟","answer":"الجواب:\nلماذا؟ ما أخرجها؟\nس: لكثرتها.\nج: الواجب عليه البدار بإخراجها ما دام وكيلًا.\nس: عنده أشغال وأمور تجارية.\nج: ولو، إما أن يُبادر أو يعتذر وينظرون غيره.\nس: لكن الآن هل تجب عليه زكاة أو ما يجب عليه شيء؟\nج: هو ما يجب عليه شيء، وإن كانت مرَّت عليها سنةٌ ما أُخرجت فعلى أهلها، وليس عليه.","link":"https://binbaz.org.sa/fatwas/22470/هل-على-الصدقات-زكاة-اذا-تاخر-اخراجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أُعطي صدقات كثيرة فهل عليها زكاة.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":2435,"question":"المتهاون من الصلاة يُعطى من الصدقة، مثلًا يصلي في البيت؟","title":"ما حكم الصدقة على المتهاون بالصلاة؟","answer":"الجواب:\nيُعطى من الصدقة لكن لغيره أطيب، الذي غيره المحافظ أولى بالإحسان إذا كان يصلي، إذا كان يصلي في البيت يكون عاصيًا، أما إذا كان ما يصلي ما يُعطى من الزكاة، يُعطى من غير الزكاة من باب التأليف إذا كان فقيرًا مع النصيحة والتوجيه.\nس: وهو محتاج مثلًا عليه ديْن مثلًا؟\nالشيخ: إذا كان يصلي لا بأس؛ يُعطى ويُنصح ويُؤدب، الهيئة تؤدبه إذا تخلف، إذا رفع الأمر  إلى الهيئة.","link":"https://binbaz.org.sa/fatwas/22564/ما-حكم-الصدقة-على-المتهاون-بالصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المتهاون من الصلاة هل يعطى من الصدقة.mp3","categories":["إخراج الزكاة وأهلها","صدقة التطوع"]},{"id":2436,"question":"نحن في جمعية خيرية ويتقدم كثير من الروافض لمساعدتهم وهم فقراء مستحقون المساعدة، فهل تُخفى خطاباتهم أو يُعطون من الصدقات؟","title":"حكم الزكاة والصدقة للفقراء من الروافض","answer":"الجواب:\nهذا يختلف، إذا كان تطوعًا من باب التأليف، النبي ﷺ كان يعطي الكفرة وغير الكفرة مثل ما قال الله جل وعلا: لَا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ وَلَمْ يُخْرِجُوكُمْ مِنْ دِيَارِكُمْ أَنْ تَبَرُّوهُمْ وَتُقْسِطُوا إِلَيْهِمْ  [الممتحنة:8] إذا كان فيه تأليف ودعوة لهم إلى السنة؛ لعل الله ينفع بالأسباب.\nس: مع أن تجارهم ما يدفعون؟\nالشيخ: المقصود: يُعْطَون من غير الزكاة، من باب التأليف إذا كان فيه دعوة مع الترغيب للسُّنة في وقت آخر، وإلا لا يعطيهم، يعطي أهل السُّنة والحمد لله، أما الزكاة فلا يُعطون الزكاة.","link":"https://binbaz.org.sa/fatwas/22565/حكم-الزكاة-والصدقة-للفقراء-من-الروافض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مساعدة الروافض المحتاجين.mp3","categories":["صدقة التطوع","إخراج الزكاة وأهلها"]},{"id":2553,"question":"المال الرِّبوي الصواب فيه الزكاة؟","title":"هل في المال الرِّبَوي زكاة؟","answer":"الجواب: الربا لا، يتصدق به كله، ما يزكيه، كله يروح للفقراء ومشاريع الخير ولا يأخذ منه شيئًا، يتصدق بالأصل اللي هو ماله. الربا كله يخرجه في وجوه الخير لا يزكيه، كله يروح بوجوه الخير، يزكي الأصل بس الذي هو السليم.\nس:غذا كان مختلطًا اختلاطًا عظيمًا؟\nالشيخ: يعرفه، المليون اللي في أصل المال يزكيه، والملايين من الربا ينفقها في وجوه الخير، نسأل الله العافية والسلامة.","link":"https://binbaz.org.sa/fatwas/22684/هل-في-المال-الربوي-زكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل في المال الربوي زكاة.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":2563,"question":"يقول مات رجل وترك ممتلكات عقارات أراضي ولم يترك مالًا وبيع هذه العقارات تحتاج إلى وقت فهل يجوز أن يعطى أولاده من الزكاة مصاريف للمعيشة حتى يبيعوا بعض ممتلكاتهم من الميراث؟","title":"حكم الزكاة لمن ورث عقارات يتأخر بيعُها","answer":"الجواب: لا، ينبغي يبيعونها ويأكلون، لا يشددون في البيع؛ يبيعون ما تيسر، الذي عنده عقارات يبيع ما تيسر، ما هو محتاج، وإلا يتسلف حتى يبيع، ما عليه خطر.","link":"https://binbaz.org.sa/fatwas/22695/حكم-الزكاة-لمن-ورث-عقارات-يتاخر-بيعها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يُعطَى الورثة من الزكاة إلى مصاريف للمعيشة حتى يبيعوا بعض ممتلكاتهم من الميراث.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":2627,"question":"بالنسبة للشخص يعطي زكاته أقاربه؟","title":"ما حكم الزكاة للأقارب وبناء المساجد؟","answer":"الجواب: إذا كانوا فقراء؛ لا بأس، لكن أصوله وفروعه لا، يعطي إخوته أعمامه أخواله إذا كانوا فقراء، أما أبوه وأمه لا، وأولاده لا.\nس: هل يعطى لمن يبنون المساجد من الزكاة؟\nالشيخ: لا، الزكاة لا يُبنى بها المساجد.\nس: إذا كانوا يحتاجون؟\nالشيخ: يُعطَون مِن أموال أخرى.","link":"https://binbaz.org.sa/fatwas/22762/ما-حكم-الزكاة-للاقارب-وبناء-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إخراج الزكاة للأقارب أو لبناء المساجد.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":2633,"question":"قوله ﷺ: تؤخذ من أغنيائهم فترد على فقرائهم ألا يدل على عدم إخراجها من تلك البلاد إلى بلدة أخرى؟","title":"ما حكم إخراج الزكاة إلى بلد آخر؟","answer":"الجواب: يعم الفقراء كلهم، لكن أهل البلد أوْلَى، فقراؤها أوْلى إذا احتاجوا، وإذا أغناهم الله يُنقل إلى بلاد أخرى، أهل البلد فقراؤها أوْلى بزكاتها.","link":"https://binbaz.org.sa/fatwas/22768/ما-حكم-اخراج-الزكاة-الى-بلد-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إخراج الزكاة إلى بلد آخر.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":2634,"question":"هل الأفضل دفع الزكاة للفقراء أو الذين عليهم دَيْن أو للمجاهدين في سبيل الله؟","title":"ما الأفضل في الزكاة للفقير والمَدِين والجهاد؟","answer":"الجواب: كلهم من أهل الزكاة، إنْ دفعها للفقراء فهم مستحقون، وإن دفعها للغرماء العاجزين فهم مستحقون، وإن دفعها في سبيل الله فهم مستحقون، كلهم على حسب الحاجة، إن كان أهل الجهاد محتاجين فأهل الجهاد أفضل، وإن كان الفقراء اشتد حاجتهم أُنقذوا بالزكاة لا يموتوا، يختلف الحال، يجتهد. س: ولو قسمها بينهم؟ الشيخ: كله جائز، مخيّر؛ إن شاء أخرجها في هؤلاء أو هؤلاء، أي جهة أخرجها فيها أجزأت، فقراء أو في سبيل الله أو في الغارمين أو في عتق الرقاب أو في المؤلف قلوبهم، مثل ما بيَّن الله سبحانه، الأمر واسع.","link":"https://binbaz.org.sa/fatwas/22769/ما-الافضل-في-الزكاة-للفقير-والمدين-والجهاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إخراج الزكاة للفقراء أو الذين عليهم دين أو للمجاهدين في سبيل الله.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":2824,"question":"إعطاء الزكاة لطالب العلم؟","title":"حكم إعطاء الزكاة لطالب العلم","answer":"الجواب: إذا كان فقيرًا، ولو ما هو طالب علم، سواء طالب وإلا ما هو بطالب.","link":"https://binbaz.org.sa/fatwas/22973/حكم-اعطاء-الزكاة-لطالب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إعطاء الزكاة لطالب العلم.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":4223,"question":"هم الرؤساء فقط {المؤلفة قلوبهم} وإلا عام؟","title":"من المقصود بـ{المؤلفة قلوبهم}؟","answer":"الجواب: المعروف أنهم الرؤساء والكبار الذين يُقتدى بهم، وإذا أعطى غيرهم لا بأس، لكن الزكاة تكون في المؤلفة قلوبهم الذين لهم شأن، الرؤساء والكبار الذين لهم شأن، أما عامة الكفار لا يعطي المسلمين، لكن الرؤساء كما ذكر جمع من أهل العلم، هم الرؤساء والسادة الذين بإعطاهم وبإسلامهم يسلم من وراءهم ويقوى إيمان من أسلم.  أما الصدقة التطوع في كل أحد، في الرئيس وغير الرئيس من الكفرة وغير المسلمين، الصدقة التطوع أوسع.\nس: الرافضة؟\nالشيخ: الرافضة فيهم تفصيل، الرافضة عُبّاد آل البيت وهم كفرة، إذا أعطاه يتألّفه على الإسلام ويدعوه إلى الإسلام ويعطيه يتألفه من هذه الطريقة لا بأس.","link":"https://binbaz.org.sa/fatwas/24490/من-المقصود-بـ-المولفة-قلوبهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما المقصود بالمؤلفة قلوبهم.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":4379,"question":"رجل من الأشراف عليه دين، فهل يجوز أن يأخذ الصدقة أو الزكاة؟","title":"حكم الزكاة لرجل من الأشراف عليه دَيْن","answer":"الجواب: يأخذ الصدقة غير الزكاة، يعطى من الصدقة غير الزكاة، إن كان من بني هاشم يُعطى من الصدقة غير الزكاة.\nس: إذا كانت ضرورة؟\nج: الضرورة: إذا حلت له الميتة حلت له الزكاة.","link":"https://binbaz.org.sa/fatwas/24656/حكم-الزكاة-لرجل-من-الاشراف-عليه-دين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز لرجل من الأشراف عليه دين أن يأخذ الصدقة أو الزكاة.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":4380,"question":"هل يشترط إخبار من تدفع إليه الزكاة أن هذا المال من الزكاة؟","title":"هل يلزم إخبار من تدفع إليه الزكاة بأنها زكاة؟","answer":"الجواب: إذا كان يخشى أنه غني، إذا كان فيه التباس، أما إن كنت تعلم أنه فقير ما يحتاج تقول له شيء.\nس: أنا أعلم أنه فقير لكنه مثلًا أخ قريب لي؟\nج: تعطيه إياها ولا تقول له شيء، أما إذا كنت تشك فيه يمكن عنده مال وأنت ما تدري تقول له: ترى هذه من الزكاة.\nس: أنا أعرف أن ما عنده مال لكن بعضهم يتورع عن أخذ الزكاة؟\nالشيخ: لا لا، اعطه إياه ولا تقل له زكاة.","link":"https://binbaz.org.sa/fatwas/24657/هل-يلزم-اخبار-من-تدفع-اليه-الزكاة-بانها-زكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يشترط إخبار من تدفع إليه الزكاة أن هذا المال مال زكاة.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":4381,"question":"هذا رجل في حالين يقول: هل يجوز لي الزكاة أم لا؟ في الحالة الأولى: يقول في زواجي، والحالة الثانية: يقول في أرض حتى أتملك بيتًا؟","title":"حكم أخذ الزكاة لمن لا يملك كلفة الزواج والمسكن","answer":"الجواب: يجوز له أن يأخذ له من الزكاة، إن كان ما يستطيع الزواج يأخذ من الزكاة، وإذا كان ما يستطيع السكن له أن يأخذ من الزكاة للسكن سواء أجرة أو ثمن.\nس: طيب الدليل عليهما؟\nج: الفقر إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ [التوبة:60] الذي ما يقدر على البيت ولا السكن فقير.\nس: الثاني: امرأة في سبالة سألت هذا السؤال وتقول: ممكن صاحب السبالة في أي وقت يخرجنا منها وليس لنا؟\nالشيخ: لا، لا، مستغنية ما دام عندها سكن مستغنية، والموت بيد الله.\nس: تقول: ما هو عشان الموت، عشان الله يسلمك، عشان إخراج صاحب السبالة؟\nج: إذا أخرجها تأخذ الزكاة.\nس: إذًا الآن لا تأخذ؟\nج: إذا أخرجها تأخذ الزكاة.","link":"https://binbaz.org.sa/fatwas/24658/حكم-اخذ-الزكاة-لمن-لا-يملك-كلفة-الزواج-والمسكن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز الأخذ من الزكاة لمن أراد مسكنًا، أو زواجًا.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":5054,"question":"هل تُنفق الزكاة في مصالح المسجد؟","title":"هل يجوز إنفاق الزكاة في مصالح المسجد؟","answer":"الجواب: لا، المسجد ما يُعمر من الزكاة، لا المساجد، ولا المدارس، الزكاة لأهلها الثمانية.","link":"https://binbaz.org.sa/fatwas/29298/هل-يجوز-انفاق-الزكاة-في-مصالح-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز إنفاق الزكاة في مصالح المسجد؟.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":5222,"question":"هنا السؤال الأول يقول: توصل بعضُ الباحثين إلى أنَّ النصاب في الوَرق النَّقدي هو خمسمئة ريال؛ بناءً على تقدير الفضَّة، فما رأيكم في ذلك؟ آمل توضيح ذلك بالأدلة.وهل التَّقدير بستة وخمسين ريالًا؛ بناءً على تقدير الوزن أم أمر آخر؟وهل يلجأ إلى الورق النَّقدي؟","title":"كم نصاب الوَرق النَّقدي حسب التقدير بالفضَّة؟","answer":"الجواب: بسم الله الرحمن الرحيم، اللهم صلِّ وسلِّم على رسول الله، وعلى آله وأصحابه ومَن اهتدى بهُداه. أما بعد: فقد نصَّ العلماءُ على أنَّ نصاب الفضَّة مئة وأربعون مثقالًا، وكان في عهد النبي ﷺ مئتا درهم، فحُررت إلى مئة وأربعين مثقالًا، وبتحرير الدرهم السّعودي الفضّي صار مثقالين ونصف، وبذلك صار النِّصاب ستة وخمسين ريالًا سعوديًّا من الفضَّة، وهي مئة وأربعون مثقالًا بالوزن، فما وافقها من العمل من الريـال السعودي والدولار والجنيه الإسترليني والمصري وغير ذلك، ما كان بهذا المقدار –يعني: ما ساوى ستة وخمسين ريـال فضَّة بالقيمة- فهو نصاب. ويحتمل أن يُقال أن ستة وخمسين من الورق الذي جعل بدل الريـال السعودي تكون نصابًا بالنسبة إلى الدرهم السعودي؛ لأنها حلَّت محله. ومعلوم أنَّ النصاب الأول أمره يسير؛ لأن الغالب على الناس أن عندهم فوق النصاب، فأهل الزكاة عندهم فوق النِّصاب، وإنما هذا أقل شيءٍ، فأقل شيء تجب فيه الزكاة ستة وخمسون ريالًا يحول عليها الحولُ، من الفضَّة أو ما قيمته كذلك من الورق وغيره من عروض التِّجارة، هذا هو الأصل في هذا والأساس، ولا يتأكد بهذا المقدار؛ لأنَّ القيمة تختلف: فقد يكون الدرهم السعودي الفضّي يومًا ما بخمسة ..... من الورق، وقد يُعادل عشرةً من الورق، وقد يُعادل أقلَّ أو أكثر، فإذا جعلنا ستة وخمسين من الدرهم الفضي أصلًا -كما هو معروف- فإنما يقام ..... من جهة القيمة من هذه العُملات الأخرى هو النِّصاب، أما إذا جعلنا ستة وخمسين من الريـال بالورق نصابًا أصليًّا كالفضة؛ لأنه قام مقامها، فليس ببعيدٍ، ولا يحتاج إلى نظرٍ في القيمة. ولكن النظر في القيمة هو الأصل الأول؛ لأن الذهب والفضَّة أصلان عظيمان في الزكاة، فالذهب عشرون مثقالًا، والفضَّة مئة وأربعون مثقالًا، فما وافق هذا المقدار من السلع المُعدة للبيع أو من العملات فإنه يكون نصابًا، ما قابل مئة وأربعين مثقالًا من الفضَّة، وما قابل عشرين مثقالًا من الذهب بالقيمة، من أي شيءٍ كان -من ورقٍ وغيره- فهو نصابٌ.","link":"https://binbaz.org.sa/fatwas/30166/كم-نصاب-الورق-النقدي-حسب-التقدير-بالفضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 216.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":5258,"question":"كم يقدر الصاع النبوي بالكيلو؟","title":"كم يبلغ مقدار الصاع النبوي بالكيلو؟","answer":"الجواب: ثلاثة كيلو إلا شيئًا قليلًا، ثلاثة كيلو تقريبًا.[1]","link":"https://binbaz.org.sa/fatwas/30863/كم-يبلغ-مقدار-الصاع-النبوي-بالكيلو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/wazayif ramadan 004.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":5294,"question":"يقول: إني من آل البيت وقيل لي لا يجوز لك أكل الصدقة والسبيل، فهل هذا صحيح؟ وهل يدخل في ذلك الماء الذي وُضع للشرب في المساجد؟","title":"حكم الزكاة والصدقة لمن كان من آل البيت؟","answer":"الجواب: لا ما يدخل، الممنوع الزكاة فقط، أما شرب الماء في المساجد أو صدقة التطوع أو غلات الأوقاف فلا بأس، الممنوع على أهل البيت الزكاة، قال النبي ﷺ: إنها لا تنبغي لآل محمد وإنما هي أوساخ الناس الزكاة فقط، نعم. وآل البيت هم بنو هاشم خاصة.[1]","link":"https://binbaz.org.sa/fatwas/30942/حكم-الزكاة-والصدقة-لمن-كان-من-ال-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 014.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":5653,"question":"إذا كان على رجلٍ دَينٌ، وهو مستحقّ للزكاة، أو من أهل الزكاة، فهل يجوز للرجل أن يدفع لهذا الرجل الزكاةَ ثم يُطالبه بالدَّين؟","title":"حكم مَن يُعطي المدين من الزكاة ثم يُطالبه بالدَّين","answer":"الجواب: دَينه هو يعني؟\nس: نعم.\nج: لا، يُعطي دَينه، يُوفي الناس، أما دَينه لا، هذا وقاية لماله، يُعطيه الزكاة ويقول: أوفِ دَينك للناس. أما أنه يقول له: أُعطيك حتى تُعطيني، لا، لكن إذا أعطاه لأجل فقره وحاجته ودَينه ثم أوفاه لا بأس، من غير شرطٍ، الله جلَّ وعلا قال: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِمِينَ [التوبة:60]، الغارمون هم أهل الدَّين، سواء كان الدَّينُ لله أو للآدميين، إذا كانوا فُقراء ما عندهم قُدرة يُعطون ما يُوفون به الدَّين، لكن إذا كان الدَّينُ لك أنت، وكنت راعي الزكاة، لا تقل: هذا الدَّين أُعطيك من الزكاة حتى تُوفيني، لا؛ لأنَّ هذا وقاية لمالك، لكن تُعطيه ويُوفي الدَّين الذي عليه، وإذا أعطاك من غير شرطٍ، أعطاك لوفاء دينك مثلما يُعطي غيره لا بأس، أما أن تشرط عليه: وإلا هذا شرطي أن تردّه عليَّ لأجل قضاء ديني؛ ما يصلح.\nالله أمر مَن له دَين على المعسر أن يُنْظِر، قال: وَإِنْ كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَى مَيْسَرَةٍ [البقرة:280]، يلزمه إنظاره، ولا يجوز إلزامه بقضاء الدَّين وهو مُعسر.[1]","link":"https://binbaz.org.sa/fatwas/31690/حكم-من-يعطي-المدين-من-الزكاة-ثم-يطالبه-بالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al'usul althlath 001.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":5654,"question":"إذا كان هناك فقيرٌ يحتاج الزكاةَ، وإذا دفع إليه الزكاةَ قبل حلول الحول ثم عدَّ ذلك من الزكاة في آخر الحول هل يجوز هذا؟","title":"هل يجوز تعجيل الزكاة قبل حلول الحول؟","answer":"الجواب: إذا عجَّلها ما في بأس، بنية الزكاة، إذا كان الحولُ مثلًا يحلّ في رمضان أو في رجب وأجَّلها، واليوم رأى فقيرًا محتاجًا فأعطاه إياها بنية الزكاة لا بأس، إخراجها قبل الحول ولو كلها، سواء كلها أو بعضها.[1]","link":"https://binbaz.org.sa/fatwas/31691/هل-يجوز-تعجيل-الزكاة-قبل-حلول-الحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al'usul althlath 002.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":5682,"question":"هل يجوز للإنسان أن يعطي من زكاة ماله لبناء مسجد يوشك على الانتهاء، وتوقف بناؤه؟","title":"هل يشرع بناء المساجد من زكاة المال؟","answer":"الجواب:\nالمعروف عند العلماء كافة، وقول الجمهور، والأكثرين وهو كالإجماع من علماء السلف الصالح الأولين: أن الزكاة لا تصرف في عمارة المساجد، وشراء الكتب، ونحو ذلك، وإنما تصرف في الأصناف الثمانية: الفقراء، والمساكين، والعاملين عليها، والمؤلفة قلوبهم، وفي الرقاب والغارمين، وفي سبيل الله، وابن السبيل، وفي سبيل الله يختص بالجهاد، هذا المعروف عند أهل العلم، وليس من ذلك صرفه في تعمير المساجد، ولا تعمير المدارس، ولا الطرق، ولا نحو ذلك، هذا هو المعروف عند أهل العلم.","link":"https://binbaz.org.sa/fatwas/982/هل-يشرع-بناء-المساجد-من-زكاة-المال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_11.mp3","categories":["المساجد ومواضع السجود","إخراج الزكاة وأهلها"]},{"id":5717,"question":"قال في الروض: يجوز دفع الزكاة للأقارب، ولو كانوا يرثون، إذا لم تجب النفقة؟","title":"مشروعية دفع الزكاة للأقارب","answer":"الجواب:  هذا قول مشهور، فإذا كان لا تجب عليه نفقتهم له أن يدفع إليهم، وإن كان يرثهم لا يدفع إليهم إنما يدفع إلى من لا يرث، وهذا القول فيه نظر. والصواب: أنه لا بأس بدفع الزكاة إلى فقراء الأقارب مطلقًا، ولو كان يرثهم لو ماتوا، الصواب: أن الحكم ليس مناطًا بالإرث، ولكن مناطًا بالفقر والحاجة، فإذا كان القريب محتاجًا، فيعطى من الزكاة، وتكون صدقة، وصلة إلا الوالد والولد الفرع والأصل. قد نقل ابن المنذر الإجماع على أنه لا يدفع للوالد والولد، فالآباء والأمهات والأجداد والجدات والأولاد وأولاد البنين والبنات هؤلاء لا يعطون الزكاة، بل على قريبهم أن يقوم عليهم، وأن ينفق عليهم حسب طاقته، أما الإخوة والأخوات والأعمام والعمات والأخوال والخالات وأولاد هؤلاء فيعطون من الزكاة مطلقًا على الأصح إذا كانوا فقراء.","link":"https://binbaz.org.sa/fatwas/1022/مشروعية-دفع-الزكاة-للاقارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_44.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":5720,"question":"هل يجوز نقل الزكاة أكثر من مسافة القصر؟ وهل حديث معاذ مانعًا لذلك عند عدم الوجود؟","title":"حكم نقل الزكاة أكثر من مسافة القصر","answer":"الجواب: نقل الزكاة للمصلحة الشرعية لا بأس به على الصحيح، وليس حديث معاذ مانعًا من ذلك؛ لأنه قال: تؤخذ من أغنيائهم فترد في فقرائهم يشمل هذا جميع المسلمين، ما يخص اليمن، تؤخذ من أغنياء المسلمين، وترد في  فقرائهم، هذا المقصود، وليس المقصود خاصًا بالفقراء في اليمن. إنما النبي أراد بهذا بيان الحكمة، وأن الزكاة تؤخذ من الأغنياء وترد في الفقراء، لكن الفقراء القريبون أولى من غيرهم إذا تساوت الأمور، فإذا ترجح البعيد لقرابة، أو طلب علم، أو جهاد، أو شدة فقر فالأولى نقل الزكاة إليهم حتى يحصل التساوي، وحتى يحصل النفع العام، هذا هو الصحيح من أقوال العلماء في هذا.","link":"https://binbaz.org.sa/fatwas/1024/حكم-نقل-الزكاة-اكثر-من-مسافة-القصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_46.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":5721,"question":"هل يجوز نقل الزكاة أكثر من مسافة القصر؟ وهل حديث معاذ مانعًا لذلك عند عدم الوجود؟","title":"حكم نقل الزكاة أكثر من مسافة القصر","answer":"الجواب: نقل الزكاة للمصلحة الشرعية لا بأس به على الصحيح، وليس حديث معاذ مانعًا من ذلك؛ لأنه قال: تؤخذ من أغنيائهم فترد في فقرائهم يشمل هذا جميع المسلمين، ما يخص اليمن، تؤخذ من أغنياء المسلمين، وترد في  فقرائهم، هذا المقصود، وليس المقصود خاصًا بالفقراء في اليمن. إنما النبي أراد بهذا بيان الحكمة، وأن الزكاة تؤخذ من الأغنياء وترد في الفقراء، لكن الفقراء القريبون أولى من غيرهم إذا تساوت الأمور، فإذا ترجح البعيد لقرابة، أو طلب علم، أو جهاد، أو شدة فقر فالأولى نقل الزكاة إليهم حتى يحصل التساوي، وحتى يحصل النفع العام، هذا هو الصحيح من أقوال العلماء في هذا.","link":"https://binbaz.org.sa/fatwas/1024/حكم-نقل-الزكاة-اكثر-من-مسافة-القصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_46.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":5732,"question":"العمال الذين يصلون إلى هنا يكون مرتبهم ضعيفًا، ومعيشتهم سدًا للرمق، ولهم ذرية ضعاف، فهل تحل الزكاة عليهم؟","title":"هل تحل الزكاة على الوافدين لضعف رواتبهم؟","answer":"الجواب: إذا عرفوا بالحاجة، وأن مرتباتهم لا تسد حاجاتهم، وكانوا مسلمين عرفوا بذلك، لا بأس أن يعطوا شيئًا من الزكاة لسد الحاجة، إذا عرفوا بأنهم مسلمون، وإذا عرفوا بالصدق، وأنهم محتاجون فقراء؛ لأن كثيرًا من الناس يدعي الفقر وهو كاذب وراتبه يكفيه.  فإذا عرف بالحاجة بالصدق بأن شهد له من يرضى بأنه فقير، وأن هذا المرتب قليل ضئيل، لا يسد حاجته؛ فلا بأس أن يعطى، وإلا فلا يعطى، ويلتمس الناس المعروفون بالحاجة والإسلام.","link":"https://binbaz.org.sa/fatwas/1061/هل-تحل-الزكاة-على-الوافدين-لضعف-رواتبهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_77.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":5736,"question":"العمال الذين يصلون إلى هنا يكون مرتبهم ضعيفًا، ومعيشتهم سدًا للرمق، ولهم ذرية ضعاف، فهل تحل الزكاة عليهم؟","title":"هل تحل الزكاة على الوافدين لضعف رواتبهم؟","answer":"الجواب: إذا عرفوا بالحاجة، وأن مرتباتهم لا تسد حاجاتهم، وكانوا مسلمين عرفوا بذلك، لا بأس أن يعطوا شيئًا من الزكاة لسد الحاجة، إذا عرفوا بأنهم مسلمون، وإذا عرفوا بالصدق، وأنهم محتاجون فقراء؛ لأن كثيرًا من الناس يدعي الفقر وهو كاذب وراتبه يكفيه.  فإذا عرف بالحاجة بالصدق بأن شهد له من يرضى بأنه فقير، وأن هذا المرتب قليل ضئيل، لا يسد حاجته؛ فلا بأس أن يعطى، وإلا فلا يعطى، ويلتمس الناس المعروفون بالحاجة والإسلام.","link":"https://binbaz.org.sa/fatwas/1061/هل-تحل-الزكاة-على-الوافدين-لضعف-رواتبهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_77.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":5739,"question":"هل تجوز الزكاة في بناء المساجد حيث يقول الله: وَفِي سَبِيلِ اللّهِ [التوبة : 60]؟","title":"هل تصرف الزكاة في بناء المساجد؟","answer":"الجواب: سبق أن المراد في سبيل الله عند أهل العلم الغزاة الذين جاهدوا في سبيل الله، فلا تصرف في المساجد، ولا في المدارس عند عامة أهل العلم.  الصواب عند أهل العلم، وهو كالإجماع منهم: أنها لا تصرف إلا في المصارف الثمانية، وأن المساجد والمدارس ليست منها، وأن المراد في سبيل الله يعني الجهاد، المجاهدون، وذهب بعض المتأخرين إلى جواز صرفها في المشاريع الخيرية، ولكنه قول مرجوح؛ لأنه يخالف ما دلت عليه الأدلة، ويخالف ما مضى عليه أهل العلم في هذا السبيل.","link":"https://binbaz.org.sa/fatwas/1063/هل-تصرف-الزكاة-في-بناء-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_78.mp3","categories":["إخراج الزكاة وأهلها","المساجد ومواضع السجود"]},{"id":5742,"question":"سمعنا بأن الجوائز التي تأتي في التلفاز والإذاعة وغيرها، والمسابقات أنها زكاة أموال التجار، وأنهم يتركونها في هذا المصرف، فما حكم ذلك؟","title":"حكم صرف الزكاة في جوائز المسابقات","answer":"الجواب: ما سمعت هذا! أنا ما أدري، لكن على كل حال إذا كانت الجوائز في مسابقة القرآن، أو نحو ذلك لا تكون من الزكاة؛ لأنه قد يعطاها من ليس فقيرًا، وإنما الزكاة تكون للفقراء. لكن تكون هذه الجوائز من رأس المال، من المال غير الزكاة، يجود بها الإخوان، والأثريا من غير الزكاة، ومن بيت المال، أما من الزكاة فلا؛ لأن حفاظ القرآن ونحوهم ليسوا كلهم فقراء، بل فيهم الفقير، وفيهم الغني، فلا يجوز أن تكون هذه المسابقات من الزكاة.","link":"https://binbaz.org.sa/fatwas/1064/حكم-صرف-الزكاة-في-جواىز-المسابقات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_79.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":5750,"question":"بالنسبة إلى المشاريع الحديثة التي خرجت للناس في هذه الأيام، وهي: مشاريع الإنتاج الحيواني، وإنتاج الألبان، ومشاريع الإنتاج الزراعي، ومشاريع العقارات الكبيرة، مثل: العمائر، فهل على هذه الأشياء زكاة؟ وكيف تخرج زكاتها؟","title":"كيف تزكى المشاريع الحديثة كالإنتاج الحيواني وغيره","answer":"الجواب: زكاتها مثل ما تقدم؛ إذا كانت هذه المشاريع للبيع والشراء وطلب الرزق يزكيها كلما حال الحول عليها، التي أعدها للبيع من: عمارة أو أرض أو دكان أو حيوانات في مزرعته، أو ما أشبه ذلك؛ يزكيها إذا حال عليها الحول بحسب القيمة.  أما الأدوات التي للصنعة فليس فيها زكاة، ومثل الأرض التي هي مزرعة ما تزكى؛ لأنه ما أعدها للبيع هي، وإنما ليربي فيها الحيوانات ويزكي أو يزرعها ونحو ذلك. فالزكاة في المتاجر، أما عين الأرض ورقبة الأرض التي أعدها ليزرع فيها، ولينمي فيها الحيوان فلا زكاة فيها، كذلك النجار والحداد الأدوات التي عنده لا زكاة فيها، الدوم المنشار غير هذه الأدوات لا زكاة فيها، إنما الزكاة في الأموال التي أعدها للبيع، الأموال والحديد الذي يباع الآلات التي تباع......","link":"https://binbaz.org.sa/fatwas/1074/كيف-تزكى-المشاريع-الحديثة-كالانتاج-الحيواني-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_86.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":5755,"question":"بالنسبة إلى المشاريع الحديثة التي خرجت للناس في هذه الأيام، وهي: مشاريع الإنتاج الحيواني، وإنتاج الألبان، ومشاريع الإنتاج الزراعي، ومشاريع العقارات الكبيرة، مثل: العمائر، فهل على هذه الأشياء زكاة؟ وكيف تخرج زكاتها؟","title":"كيف تزكى المشاريع الحديثة كالإنتاج الحيواني وغيره","answer":"الجواب: زكاتها مثل ما تقدم؛ إذا كانت هذه المشاريع للبيع والشراء وطلب الرزق يزكيها كلما حال الحول عليها، التي أعدها للبيع من: عمارة أو أرض أو دكان أو حيوانات في مزرعته، أو ما أشبه ذلك؛ يزكيها إذا حال عليها الحول بحسب القيمة.  أما الأدوات التي للصنعة فليس فيها زكاة، ومثل الأرض التي هي مزرعة ما تزكى؛ لأنه ما أعدها للبيع هي، وإنما ليربي فيها الحيوانات ويزكي أو يزرعها ونحو ذلك. فالزكاة في المتاجر، أما عين الأرض ورقبة الأرض التي أعدها ليزرع فيها، ولينمي فيها الحيوان فلا زكاة فيها، كذلك النجار والحداد الأدوات التي عنده لا زكاة فيها، الدوم المنشار غير هذه الأدوات لا زكاة فيها، إنما الزكاة في الأموال التي أعدها للبيع، الأموال والحديد الذي يباع الآلات التي تباع......","link":"https://binbaz.org.sa/fatwas/1074/كيف-تزكى-المشاريع-الحديثة-كالانتاج-الحيواني-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_86.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":5759,"question":"رجل عنده نصاب، ولكن عليه دين ينقص النصاب، فهل يزكي مثلًا عنده 45 مثقالًا من الذهب، وعليه 26 مثقالًا؟","title":"هل على المدين إخراج زكاة؟","answer":"الجواب: الصواب أن الدين لا يمنع الزكاة، فإذا كان عليه مائة ألف دين، وعنده مائتا ألف لا ينقص منها مائة ألف، لا يزكيها لا، بل يزكي ما عنده، والدين يقضيه الله  لأن الرسول ﷺ كان يبعث عماله إلى الناس، ويقبضون منهم الزكوات، ولا يسألونهم عليهم دين، أو ما عليهم دين.  الحاصل: أن الدين لا يمنع الزكاة، فإذا كان عليه مائة ألف دين، وعنده مائة ألف نقود يزكيها، ولا يمنعها الدين، لا يمنع الزكاة. السؤال: وكذلك النذر والكفارة إذا أنقصت النصاب؟ الجواب: كلها لا تمنع، الدين لا النذر ولا الكفارة، كلها لا تمنع الزكاة.","link":"https://binbaz.org.sa/fatwas/1081/هل-على-المدين-اخراج-زكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_91.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":5771,"question":"بالنسبة إلى المشاريع الحديثة التي خرجت للناس في هذه الأيام، وهي: مشاريع الإنتاج الحيواني، وإنتاج الألبان، ومشاريع الإنتاج الزراعي، ومشاريع العقارات الكبيرة، مثل: العمائر، فهل على هذه الأشياء زكاة؟ وكيف تخرج زكاتها؟","title":"كيف تزكى المشاريع الحديثة كالإنتاج الحيواني وغيره","answer":"الجواب: زكاتها مثل ما تقدم؛ إذا كانت هذه المشاريع للبيع والشراء وطلب الرزق يزكيها كلما حال الحول عليها، التي أعدها للبيع من: عمارة أو أرض أو دكان أو حيوانات في مزرعته، أو ما أشبه ذلك؛ يزكيها إذا حال عليها الحول بحسب القيمة.  أما الأدوات التي للصنعة فليس فيها زكاة، ومثل الأرض التي هي مزرعة ما تزكى؛ لأنه ما أعدها للبيع هي، وإنما ليربي فيها الحيوانات ويزكي أو يزرعها ونحو ذلك. فالزكاة في المتاجر، أما عين الأرض ورقبة الأرض التي أعدها ليزرع فيها، ولينمي فيها الحيوان فلا زكاة فيها، كذلك النجار والحداد الأدوات التي عنده لا زكاة فيها، الدوم المنشار غير هذه الأدوات لا زكاة فيها، إنما الزكاة في الأموال التي أعدها للبيع، الأموال والحديد الذي يباع الآلات التي تباع......","link":"https://binbaz.org.sa/fatwas/1074/كيف-تزكى-المشاريع-الحديثة-كالانتاج-الحيواني-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_86.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":5775,"question":"رجل عنده نصاب، ولكن عليه دين ينقص النصاب، فهل يزكي مثلًا عنده 45 مثقالًا من الذهب، وعليه 26 مثقالًا؟","title":"هل على المدين إخراج زكاة؟","answer":"الجواب: الصواب أن الدين لا يمنع الزكاة، فإذا كان عليه مائة ألف دين، وعنده مائتا ألف لا ينقص منها مائة ألف، لا يزكيها لا، بل يزكي ما عنده، والدين يقضيه الله  لأن الرسول ﷺ كان يبعث عماله إلى الناس، ويقبضون منهم الزكوات، ولا يسألونهم عليهم دين، أو ما عليهم دين.  الحاصل: أن الدين لا يمنع الزكاة، فإذا كان عليه مائة ألف دين، وعنده مائة ألف نقود يزكيها، ولا يمنعها الدين، لا يمنع الزكاة. السؤال: وكذلك النذر والكفارة إذا أنقصت النصاب؟ الجواب: كلها لا تمنع، الدين لا النذر ولا الكفارة، كلها لا تمنع الزكاة.","link":"https://binbaz.org.sa/fatwas/1081/هل-على-المدين-اخراج-زكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_91.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":5918,"question":"ما  رأي الشارع في قيامي بصرف جزء من زكاة مالي في تشييد مسجد منذ بعض سنوات، دون علمي بالحكم، وعرفت هذه السنة أن الزكاة لا تجوز على تشييد مسجد، فما الحكم فيما فعلت قبل ذلك؟ هل هو جائز؟ وماذا أفعل؟","title":"حكم تعمير المساجد من الزكاة","answer":"الجواب: المعروف عند أهل العلم: أن الزكاة لا تصرف للمساجد، هذا الذي عليه جمهور أهل العلم، وهو المعروف عن السلف الصالح، ومن بعدهم أن الزكاة ليس من مصارفها تعمير المساجد، ولا تعمير المدارس، وأشباه ذلك، بل هي لأصناف ثمانية، وليس منها تعمير المساجد، بل ما يتعلق به من قال بذلك كلمة في سبيل الله وفي سبيل الله ذكر العلماء أن المراد بها المجاهدون (الجهاد). فالذي صرف زكاته في المساجد؛ ينبغي له أن يقضيها، وأن يصرفها في جهاتها، ويكون ذلك عمل بر له أجره، وثوابه، فيقضي مثل ما صرف في المساجد، ويخرجه في جهات أخرى للفقراء، والمساكين، وفي المجاهدين، أو في المؤلفة قلوبهم. المقصود: أنه يقضي ما صرف يعني ذلك الذي صرفه يقضي بدله في مصارف الزكاة.","link":"https://binbaz.org.sa/fatwas/1278/حكم-تعمير-المساجد-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_265.mp3","categories":["إخراج الزكاة وأهلها","المساجد ومواضع السجود"]},{"id":5984,"question":"والدي يأمرني ألا أصل خالي؛ لأن معه سوء تفاهم لأجل غرض دنيوي، ويقول: إذا أنت تزور خالك أخرجتك من بيتي، وإلا أهجرك كما هجرته، فماذا أعمل؟","title":"حكم طاعة الوالد إذا أمر ولده ألا يزور أحد أقاربه","answer":"الجواب: إذا أمرك والدك بهجر خالك، أو عمك، أو نحوهم بغير حق إلا أنه سوء تفاهم بين والدك، وبين خالك، أو أخيه، أو نحو ذلك من أجل الدنيا، والخصومات؛ فليس لك أن تطيع والدك؛ لأن هذه معصية إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق.  وعلى والدك أيضًا أن يتقي الله، وأن لا يهجره أكثر من ثلاث النبي ﷺ نهى عن الهجر فوق ثلاث في أمور الدنيا لا يحل لمسلم أن يهجر أخاه فوق ثلاث يلتقيان، فيعرض هذا، ويعرض هذا، وخيرهما الذي يبدأ بالسلام وقال: لا هجرة فوق ثلاث.  المقصود: أن التهاجر من أجل الشحناء، والعداوة، والخصومات لا يجوز أبدًا، لكن يباح ثلاثة أيام، يباح التهاجر في الخصومة ثلاثة أيام، فأقل، الإنسان إذا كان بينك، وبينه خصومة، وساء خلقه عليه، وحصل شيء في النفس؛ فلا بأس أن يهجره ثلاثة أيام؛ رحمة من الله؛ لأن النفوس لها نصيبها من مراعاتها، والتلطف بها، والرفق بها، فالهجر ثلاثة أيام تكفي في تخفيف الحدة، وإزالة الشدة، فإذا مضت الثلاثة فخيرهما الذي يبدأ بالسلام.  وأنت أيها الولد إذا أبى عليك أبوك؛ فلك أن تصل خالك، وعمك، ولو من طريق السر، تصل، تحسن إليهم، وتزورهم، ولو من طريق السر؛ حتى لا تشتد الحال بينك، وبين أبيك، ولا تطعه في المعصية، ولكن تعامله بالتي هي أحسن، وتجتهد بأن تكون صلتك، وبرك لخالك، وعمك، ونحو ذلك بالطريقة التي لا يطلع عليها، إذا كنت تخشى أن يقع شر أكثر.  وأما إذا كنت تستطيع أن تهدئ الوضع، وتنصح والدك، وأن تقول له: هذا لا يجوز، وأن عليك أن ترفق بأخيك، أو بخالك، المقصود أنك تنصحه؛ لعله يهتدي؛ حتى يصالح خالك، أو عمك، وحتى تزول هذه الوحشة بينهما. أما إذا كان الهجر للدين؛ لأن الشخص يتظاهر بالمعاصي، والبدع، فهو يُهجر حتى يتوب، ولو سنة، أو سنتين، لو  أكثر يهجر يتوب، وقد هجر النبي ﷺ ثلاثة تخلفوا عن الغزو بغير عذر، هجرهم النبي خمسين ليلة حتى تاب الله عليهم، فتابوا، وأظهر توبتهم، وبين للناس أن الله تاب عليهم، فكلمهم الناس بعد ذلك.  فالحاصل: أن الهجر إذا كان لله من أجل المعاصي الظاهرة، أو البدع، فهذا ليس له حد إلا التوبة، إذا رجعوا من معاصيهم الظاهرة، وبدعهم، فإن المسلمين يسلمون عليهم، وأما إذا أصروا على البدع، والمعاصي؛ فإنه يشرع هجرهم؛ لعلهم يتوبون؛ لعلهم يرجعون، وإذا كان هجرهم قد يضر المسلمين، ويسبب مشاكل أكثر؛ فلا يهجروا، بل ينصحون، ويوجهون إذا كان هجرهم يضر المجتمع، أو يفضي إلى فساد، أو إلى منكر أكبر، فهجرهم هنا محل اجتهاد، ومحل نظر.","link":"https://binbaz.org.sa/fatwas/1363/حكم-طاعة-الوالد-اذا-امر-ولده-الا-يزور-احد-اقاربه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_321.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":5993,"question":"رأت والدتي في المنام أنها وجميع الأسرة في بيت، وجاء إليهم والدي المتوفي -يرحمه الله- وتقول: فرحت به، وقلت له: لا تذهب عنا، وفي فكرها أنه عايش في مكان ثان، وتقول: إنها لمسته، وقال لها: لا تلمسيني إني نجس؟","title":"ماذا يقول من يرى رؤيا لا تسره؟","answer":"الجواب: هذه الرؤيا، وأشباهها من الشياطين، يقول النبي ﷺ: الرؤيا الصالحة من الله، والحلم من الشيطان، فإذا رأى أحدكم ما يكره؛ فلينفث عن يساره ثلاث مرات، وليتعوذ بالله من الشيطان الرجيم، ومما رأى ثلاث مرات، ثم لينقلب على جنبه الآخر؛ فإنها لا تضره، ولا يخبر بها أحدًا الذي يرى أنه يقتل، أو أنه نجس، أو صب عليه البول، أو أحدًا يهدده بالقتل، أو يضربه، أو أنه مكشوف العورة، أو ما أشبه ذلك، كل هذا من الشياطين، فإذا استيقظ؛ فليتفل عن يساره ثلاث مرات، وليقل: أعوذ بالله من الشيطان، ومن شر ما رأيت، ثلاث مرات، ثم ينقلب على جنبه الآخر، ولا يخبر بها أحدًا، ولا تضره، إن شاء الله. السؤال: ما يقول الله أكبر كبيرًا، والحمد لله كثيرًا، وسبحانه الله، وبحمده بكرة، وأصيلًا؟ الجواب: ما سمعنا هذا، الذي قاله النبي ﷺ قال: فليتعوذ بالله، وليتفل عن يساره، ثلاث مرات، وليتعوذ بالله من الشيطان، ومن شر ما رأى، ثلاث مرات، ثم ينقلب على جنبه الآخر وإذا أحب أن يسبح بعد ذلك؛ فيكون فيه خير. السنة إذا استيقظ أن يقول: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير، سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله، الحمد لله الذي أحياني بعد ما أماتني، وإليه النشور، يستحب هذا عند الاستيقاظ من النوم مطلقًا في آخر الليل، وفي أثناء الليل، ولو ما رأى رؤيا إذا تعار من النوم يقول هذا يستحب له هذا.","link":"https://binbaz.org.sa/fatwas/1391/ماذا-يقول-من-يرى-رويا-لا-تسره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_347.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":5997,"question":"يسأل السائل فيقول: إن لي عقارًا أجرته بمقدار 18,000 سنوي، واستلمت نصف المبلغ مقدمًا، والباقي آخر السنة، وأطعم منه أولادي، فهل عليّ زكاة، أم لا؟","title":"حكم زكاة أجرة العقار وبيان وقت إخراجها","answer":"الجواب: إذا حال على الأجرة الحول؛ وجب أن يزكيها، وإذا قبضها، وأنفقها قبل أن يتم حولها، أنفقها في حاجاتها؛ فلا زكاة، أما إذا حال عليها الحول، أو حال على بعضها؛ فإنه يزكي ما حال عليه الحول.","link":"https://binbaz.org.sa/fatwas/1392/حكم-زكاة-اجرة-العقار-وبيان-وقت-اخراجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_348.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":6020,"question":"رجل يدخر مبلغًا من المال بلغ النصاب الشرعي للزكاة، لكنه غير متزوج، أعزب، فيريد الزواج بهذا المبلغ، ومرت عليه سنتان؛ فهل تجب الزكاة؟","title":"حكم زكاة المال المدخر للزواج","answer":"الجواب: يزكي، الزكاة تزيده خيرًا، إذا جمع مالاً ليتزوج، أو ليقضي دينه، أو ليبني عمارة سكنًا، فحال عليه الحول؛ فإنه يزكي، تلزمه الزكاة، ويتزوج بعد ذلك، والزكاة تزيده خيرًا، لا تزيده إلا بركة، خُذْ مِنْ أَمْوَالِهِمْ صَدَقَةً تُطَهِّرُهُمْ وَتُزَكِّيهِمْ بِهَا [التوبة:103].","link":"https://binbaz.org.sa/fatwas/1386/حكم-زكاة-المال-المدخر-للزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_342.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":6021,"question":"رجل يدخر مبلغًا من المال بلغ النصاب الشرعي للزكاة، لكنه غير متزوج، أعزب، فيريد الزواج بهذا المبلغ، ومرت عليه سنتان؛ فهل تجب الزكاة؟","title":"حكم زكاة المال المدخر للزواج","answer":"الجواب: يزكي، الزكاة تزيده خيرًا، إذا جمع مالاً ليتزوج، أو ليقضي دينه، أو ليبني عمارة سكنًا، فحال عليه الحول؛ فإنه يزكي، تلزمه الزكاة، ويتزوج بعد ذلك، والزكاة تزيده خيرًا، لا تزيده إلا بركة، خُذْ مِنْ أَمْوَالِهِمْ صَدَقَةً تُطَهِّرُهُمْ وَتُزَكِّيهِمْ بِهَا [التوبة:103].","link":"https://binbaz.org.sa/fatwas/1386/حكم-زكاة-المال-المدخر-للزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_342.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":6031,"question":"الصدقة، والزكاة هل هي تجوز على اليتامى الذين تحت إدارتي بصفتي زوج أمهم، وأنا لست ولي أمرهم؟","title":"حكم صرف الزكاة لأبناء الزوجة الذين في كفالة الزوج","answer":"الجواب: إذا كانوا فقراء يجوز أن تعطيهم من الزكاة، تشتري لهم كسوة، أما الطعام فيأكلون مع طعامك أنت، ومأجور -إن شاء الله- لكن إذا كان الحاجة لكسوة تكفيهم من الزكاة ما في بأس.","link":"https://binbaz.org.sa/fatwas/1426/حكم-صرف-الزكاة-لابناء-الزوجة-الذين-في-كفالة-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_366.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":6036,"question":"الصدقة، والزكاة هل هي تجوز على اليتامى الذين تحت إدارتي بصفتي زوج أمهم، وأنا لست ولي أمرهم؟","title":"حكم صرف الزكاة لأبناء الزوجة الذين في كفالة الزوج","answer":"الجواب: إذا كانوا فقراء يجوز أن تعطيهم من الزكاة، تشتري لهم كسوة، أما الطعام فيأكلون مع طعامك أنت، ومأجور -إن شاء الله- لكن إذا كان الحاجة لكسوة تكفيهم من الزكاة ما في بأس.","link":"https://binbaz.org.sa/fatwas/1426/حكم-صرف-الزكاة-لابناء-الزوجة-الذين-في-كفالة-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_366.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":6070,"question":"وفقكم الله، قلتم: إن الذي عليه دين مثلاً 500 ريال وعنده 500 في ملكه؛ فإنه يزكي الذي عنده، وقضاء الدين على الله، فما هو الدليل، مع العلم أن بعض العلماء يقول بخلاف ذلك؟","title":"حكم الزكاة مع وجود الدين","answer":"الجواب: نعم، إذا كان على الإنسان دين، وعنده أموال زكاة؛ فإنه يزكي ما عنده، والدين لا يمنع الزكاة، هذه مسألة خلاف بين العلماء أيضًا، من أهل العلم من قال: إن الدين يمنع الزكاة مطلقًا، ومنهم من قال: يمنعه في الباطنة، لا في الأموال الظاهرة، ومنهم من قال: لا يمنعه مطلقًا، فالأقوال ثلاثة: أنه يمنع الزكاة مطلقًا بمقداره، أو لا يمنعها مطلقًا، أو يمنعها، يمنع الزكاة في الديون الباطنة من النقود، وأشباهه، لا في الأموال الظاهرة، كالثمار، والإبل، والبقر، والغنم. والأرجح من الأقوال الثلاثة: أنه لا يمنعها مطلقًا، لا يمنع الزكاة مطلقًا، والدليل أن النبي ﷺ لم يقل لعماله: إذا أتيتم الناس، وعندهم أموال زكوية، اسألوهم هل عليهم ديون؟! فإذا كان عليهم ديون؛ فاطرحوا عليهم .. ما سألهم، ما قال لهم، ولو كان هذا حقًا، ولو كان هذا لازمًا لبينه النبي ﷺ فإن النبي -عليه الصلاة والسلام- بعثه الله مبلغًا للأمة، ومعلمًا لها دينها، ما في نبي آخر يعلمنا، هو خاتم النبيين، عليه الصلاة والسلام.  فلو كان الدين يمنع الزكاة؛ لقال لعماله الذين يذهبون ليأخذون أموال الزكاة من الإبل، أو من الغنم، أو من الأخرى، لقال لهم: أيها العمال! إذا أتيتم لأخذ زكاة؛ فاذكروا لهم، هل عليهم ديون، فإذا كان عليهم ديون، فأسقطوا مقابلها من الزكاة، لو كان هذا قاله؛ لانتهى الناس إليه، ولما سكت، ولم يقل ذلك؛ علم أن الدين لا يمنع الزكاة، فإذا كان عند إنسان مليون ريال في دكانه، أو في بيته، أو صندوقه، وعنده لبعض الناس خمسمائة ألف ريال، نصف مليون في حاجات اشتراها، وصارت دينًا عليه في عمارة بيت، أو لكذا، أو لكذا، فمقتضى أن الدين (لا) يمنع الزكاة أنه لا يزكي إلا النصف مليون التي عنده؛ لأن هذا النصف الثاني يقابله الدين؛ فلا يزكي إلا النصف الثاني.  وعلى القول الصحيح: أن الدين لا يمنع الزكاة، عليه، عليه أن يزكي من المال كله الذي عنده، وأما الدين الذي عليه، فالله يقضي عنه إذا كان صادقًا بالوفاء؛ فليبادر بالوفاء قبل أن يتم الحول، فإذا أوفى ما عليه قبل تمام الحول، ما بقي عليه عنده إلا نصف مليون؛ فيزكي نصف مليون، أما يقول: لا الدين يبقى، ولا أزكي الموجود من أجل الدين لا، الصواب: أنه يزكي الموجود، وعليه .. في أداء الدين الذي عليه، وليتق الله في ذلك، ولا يماطل الناس، ولا يضرهم، ولا يشق عليهم في ديونهم.","link":"https://binbaz.org.sa/fatwas/1481/حكم-الزكاة-مع-وجود-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_411.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":6103,"question":"نرى الناس في الأعياد يتعانقون، ولو لم يكن بعضهم قادمًا من سفر، وقد يكون الوقت الذي يفصل بينهم قصير، وقت الصلاة، ثم يتعانقون بعد صلاة العيد، نرجو بيان الحقيقة؟","title":"حكم المعانقة في الأعياد","answer":"الجواب: ما نعلم في التعانق أصلًا إلا عادة جرى عليها الناس، إنما المسنون الدعاء بالقبول إذا قابل أخاه، ودعا له بالقبول؛ فهذا من فعل السلف، أما المعانقة لأجل هذا الخصوص لا أعلم لها أصلًا، إنما هي عادة للناس. فالأفضل المصافحة، ويكتفى بها عند اللقاء، يصافح أخاه، ويقول له: هنأك الله بهذا العيد، بارك الله لك في هذا العيد، أو تقبل الله منا ومنك، وما أشبه ذلك، لا بأس به.","link":"https://binbaz.org.sa/fatwas/1533/حكم-المعانقة-في-الاعياد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_463.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6120,"question":"حلمت في المنام ورأيت أني أشرب الدخان أنا، وأخي، ونحن لم نشرب الدخان، وثلاث ليال حصلت تلك الرؤيا، وتكررت، أفيدوني، جزاكم الله؟","title":"بيان أن الرؤى المكروهة من الشيطان","answer":"الجواب: إذا رأى الإنسان ما يكره فهو من الشيطان، فرؤيا أنه يشرب الدخان، أو أنه يشرب الخمر، أو أنه يزني، أو أنه يطأ أمه، أو أنه يطأ أخته، أو أنه يلوط، أو ما أشبه ذلك، يرى هذه المرائي المكروهة، فهي من الشيطان، قال النبي ﷺ: الرؤيا الصالحة من الله، والحلم من الشيطان، فإذا رأى أحدكم ما يكره؛ فلينفث عن يساره ثلاث مرات، وليتعوذ بالله من الشيطان، ومن شر ما رأى، ثلاث مرات، ثم لينقلب على جنبه الآخر؛ فإنها لا تضره. النصيحة لك يا أخي، وأشباهك ممن يرى ما يكره: أنه إذا استيقظ ينفث عن يساره ثلاث مرات، ويتعوذ بالله من الشيطان، ومن شر ما رأى ثلاث مرات، ثم ينتقل إلى جنبه الآخر، فإنها لا تضره، ولا يخبّر بها أحدًا، هذه السنة، وفق الله الجميع.","link":"https://binbaz.org.sa/fatwas/1524/بيان-ان-الروى-المكروهة-من-الشيطان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_454.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6130,"question":"نرى الناس في الأعياد يتعانقون، ولو لم يكن بعضهم قادمًا من سفر، وقد يكون الوقت الذي يفصل بينهم قصير، وقت الصلاة، ثم يتعانقون بعد صلاة العيد، نرجو بيان الحقيقة؟","title":"حكم المعانقة في الأعياد","answer":"الجواب: ما نعلم في التعانق أصلًا إلا عادة جرى عليها الناس، إنما المسنون الدعاء بالقبول إذا قابل أخاه، ودعا له بالقبول؛ فهذا من فعل السلف، أما المعانقة لأجل هذا الخصوص لا أعلم لها أصلًا، إنما هي عادة للناس. فالأفضل المصافحة، ويكتفى بها عند اللقاء، يصافح أخاه، ويقول له: هنأك الله بهذا العيد، بارك الله لك في هذا العيد، أو تقبل الله منا ومنك، وما أشبه ذلك، لا بأس به.","link":"https://binbaz.org.sa/fatwas/1533/حكم-المعانقة-في-الاعياد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_463.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6137,"question":"شخص مقترض من بنك التنمية العقاري، وبعد الانتهاء من العمارة أجرها بمبلغ يسدد منه قسط البنك، والباقي ينتفع به، فهل عليه زكاة في الإيجار كاملًا، أم في الباقي من الإيجار بعد تسديد البنك؟ أم ليس عليه شيء لكونه عليه دين من البنك؟","title":"حكم الامتناع عن الزكاة بسبب الدين","answer":"الجواب:  إذا أجر الإنسان عمارة له، أو فلة له بناها من البنك، أو بناها من ماله، وعليه ديون؛ فعليه أن يزكي المال الذي بيده من التأجير إذا حال عليه الحول، ولا يمنعه الدين الذي عليه للبنك، أو لغير البنك، هذا هو الصواب. بعض أهل العلم يقول: إن الدين يمنع الزكاة في مقداره؛ لأنها مواساة، فلا يواسي عن مال قد قابله الدين، ولكن هذا رأي يقابل النصوص، ويصادمها في الظاهر، ولهذا الصواب أنه لا يعتبر، وقد كان النبي ﷺ يبعث عماله إلى الناس لأخذ الزكاة، وما كانوا يسألونهم هل عليهم ديون، بل كانوا يأخذون الأموال، يأخذون الزكاة من الأموال من غير سؤال لصاحب المال من غنم، أو إبل، أو زروع، أو ثمار، يأخذون منه الزكاة، وهل يسألونه هل عليه دين، أم ليس عليه دين، ولو كان الدين يمنع الزكاة؛ لسأل العامل، ولأمره النبي أن يسأله عليه الصلاة والسلام. فالصواب: أنه لا يمنع من الدين، فإذا أجر العمارة، أو الفلة التي للبنك فيها دين، إذا أجرها بمائة ألف مثلًا، ثم حال الحول على هذه الأجرة قبل أن يوفي البنك، قبل أن يصرفها؛ فإن عليه زكاة . أما إن أوفى الدين الذي عليه، أو أنفقها في حاجاته قبل أن يتم الحول؛ فلا زكاة عليه، ولهذا كان عثمان  يأمر الناس عند قرب الحول أن يبادروا بالديون التي عليهم قبل وجوب الزكاة؛ حتى يخلصوا الديون قبل الزكاة، فإذا أوفى قبل الحول، إذا كان الحول مثلًا في رمضان، وأوفى ديونه في رجب، أو شعبان حتى يصفي ما عليه الديون، فقد أحسن، ويزكي الباقي. أما إذا حلت الزكاة، والدين باق لم يوف؛ فإنه يزكي، والله يوفي عنه  يزكي المال الذي عليه، والدين يوفى من المال الباقي، وإما يستقرض من المال من إيجار، وغيره.","link":"https://binbaz.org.sa/fatwas/1609/حكم-الامتناع-عن-الزكاة-بسبب-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_503.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":6209,"question":"إذا كان للشخص عمارة يؤجرها سنويًا، هل يخرج الزكاة من دخلها، أو من ثمنها؟","title":"كيفية إخراج زكاة من له عمارة مستغلة للإيجار","answer":"الجواب: إذا كان يستغلها للإيجار لا للبيع؛ فإنه يزكي الدخل الإيجار، أما إذا نواها للتجارة، أو عدها للتجارة، وهو يؤجرها، وهي معدة للتجارة؛ فإنه يزكي الجميع، يزكي الأجرة، ويزكي القيمة كل سنة.  أما ما دامت معدة للإيجار، لم يعدها للبيع؛ فإنه يزكي الغلة إذا حال عليها الحول.","link":"https://binbaz.org.sa/fatwas/1690/كيفية-اخراج-زكاة-من-له-عمارة-مستغلة-للايجار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_559.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":6211,"question":"لو كانت لبناء المساجد؟","title":"حكم بناء المساجد من الزكاة","answer":"الجواب: لا، المساجد لا تبنى من الزكاة، المساجد، والمدارس لا تبنى من الزكاة، لكن تبنى بمساعدة أهل الخير، أما الزكوات فتصرف فيما قال الله -جل وعلا-: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِمِينَ وَفِي سَبِيلِ اللَّهِ وَابْنِ السَّبِيلِ [التوبة: 60] وفي سبيل الله: هؤلاء هم المجاهدون عند أهل العلم.","link":"https://binbaz.org.sa/fatwas/1708/حكم-بناء-المساجد-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_565.mp3","categories":["إخراج الزكاة وأهلها","المساجد ومواضع السجود"]},{"id":6212,"question":"أنا شاب أرغب في بعض الطاعات، كصيام النفل يومي الخميس والإثنين، والذهاب إلى مكة لأداء العمرة، وغير ذلك، إلا أن والدي يمنعني، فما موقفي منه؟","title":"حكم طاعة الوالد في ترك النوافل","answer":"الجواب: عليك أن تستأذن والدك، وأن تستسمحه في ذلك؛ لأن برهم واجب، وهذه نوافل، فلا تقدم النوافل على الواجب، بر أبيك واجب، وقد يكون صومك في النهار يعطل عليه مصالح، ويسبب عليه مشاكل، فينبغي لك أن تجتهد في إرضاء والدك، واستسماحه؛ حتى يسمح لك بصوم الإثنين والخميس، وحتى يسمح لك بالذهاب إلى العمرة غير الواجبة، أما العمرة الواجبة، والحج الواجب؛ فالواجب أن يسمح لك، وإذا أبى لك أن تحج الحج الواجب، إذا كنت قادرًا، وتعتمر العمرة الواجبة إن كانت قادرًا ولو لم يسمح، لكن هذا في النوافل، العمرة النافلة، والحج النافلة، ونحو ذلك. السؤال: حتى لو كان أمر الوالد لولده بحلق لحيته مثلًا؟ الجواب: هذه معصية، لا يجوز له طاعته في حلق اللحية، ولا في جر الثياب، ولا في  ترك الصلاة في جماعة، المعصية ما يجوز، إنما الطاعة في المعروف، لا طاعة للمخلوق في معصية الخالق، أما النوافل لا يجتهد مع والده حتى يكون فيه سماح؛ حتى لا يكون بينه وبين والده شر، وعقوق.","link":"https://binbaz.org.sa/fatwas/1702/حكم-طاعة-الوالد-في-ترك-النوافل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_560.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6219,"question":"إذا كان للشخص عمارة يؤجرها سنويًا، هل يخرج الزكاة من دخلها، أو من ثمنها؟","title":"كيفية إخراج زكاة من له عمارة مستغلة للإيجار","answer":"الجواب: إذا كان يستغلها للإيجار لا للبيع؛ فإنه يزكي الدخل الإيجار، أما إذا نواها للتجارة، أو عدها للتجارة، وهو يؤجرها، وهي معدة للتجارة؛ فإنه يزكي الجميع، يزكي الأجرة، ويزكي القيمة كل سنة.  أما ما دامت معدة للإيجار، لم يعدها للبيع؛ فإنه يزكي الغلة إذا حال عليها الحول.","link":"https://binbaz.org.sa/fatwas/1690/كيفية-اخراج-زكاة-من-له-عمارة-مستغلة-للايجار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_559.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":6221,"question":"لو كانت لبناء المساجد؟","title":"حكم بناء المساجد من الزكاة","answer":"الجواب: لا، المساجد لا تبنى من الزكاة، المساجد، والمدارس لا تبنى من الزكاة، لكن تبنى بمساعدة أهل الخير، أما الزكوات فتصرف فيما قال الله -جل وعلا-: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِمِينَ وَفِي سَبِيلِ اللَّهِ وَابْنِ السَّبِيلِ [التوبة: 60] وفي سبيل الله: هؤلاء هم المجاهدون عند أهل العلم.","link":"https://binbaz.org.sa/fatwas/1708/حكم-بناء-المساجد-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_565.mp3","categories":["إخراج الزكاة وأهلها","المساجد ومواضع السجود"]},{"id":6222,"question":"أنا شاب أرغب في بعض الطاعات، كصيام النفل يومي الخميس والإثنين، والذهاب إلى مكة لأداء العمرة، وغير ذلك، إلا أن والدي يمنعني، فما موقفي منه؟","title":"حكم طاعة الوالد في ترك النوافل","answer":"الجواب: عليك أن تستأذن والدك، وأن تستسمحه في ذلك؛ لأن برهم واجب، وهذه نوافل، فلا تقدم النوافل على الواجب، بر أبيك واجب، وقد يكون صومك في النهار يعطل عليه مصالح، ويسبب عليه مشاكل، فينبغي لك أن تجتهد في إرضاء والدك، واستسماحه؛ حتى يسمح لك بصوم الإثنين والخميس، وحتى يسمح لك بالذهاب إلى العمرة غير الواجبة، أما العمرة الواجبة، والحج الواجب؛ فالواجب أن يسمح لك، وإذا أبى لك أن تحج الحج الواجب، إذا كنت قادرًا، وتعتمر العمرة الواجبة إن كانت قادرًا ولو لم يسمح، لكن هذا في النوافل، العمرة النافلة، والحج النافلة، ونحو ذلك. السؤال: حتى لو كان أمر الوالد لولده بحلق لحيته مثلًا؟ الجواب: هذه معصية، لا يجوز له طاعته في حلق اللحية، ولا في جر الثياب، ولا في  ترك الصلاة في جماعة، المعصية ما يجوز، إنما الطاعة في المعروف، لا طاعة للمخلوق في معصية الخالق، أما النوافل لا يجتهد مع والده حتى يكون فيه سماح؛ حتى لا يكون بينه وبين والده شر، وعقوق.","link":"https://binbaz.org.sa/fatwas/1702/حكم-طاعة-الوالد-في-ترك-النوافل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_560.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6231,"question":"........؟","title":"الفرق بين القيام للقادم والقيام إلى القادم","answer":"الجواب:  قال النبي: قوموا إلى سيدكم قال للصحابة: قوموا إلى سيدكم فقاموا إليه، وقابلوه، وسلموا عليه، فالقيام إلى الشخص غير القيام للشخص، المكروه، والمنكر أن تقوم له وهو جالس من غير مصافحة، ولا كلام، بل  تقوم له هكذا، إعظامًا، هذا مكروه،... من باب التعظيم أيضًا، لا يجوز؛ لأنه من فعل الأعاجم.  أما القيام إليه لمقابلته، ومصافحته، والأخذ بيده، أو إجلاسه في مكانك، أو في مكان آخر؛ فهذا مشروع، وقد فعله النبي -عليه الصلاة والسلام - وفعله الصحابة، فعله النبي مع بنته إذا دخلت، وقام إليها، وأخذ بيدها، وإذا دخل عليها؛ قامت إليه، عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/1749/الفرق-بين-القيام-للقادم-والقيام-الى-القادم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_588.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6237,"question":"إذا سافرت إلى أحد البلاد المسلمة لغرض معلوم من دراسة، وغيرها، فعندما أسكن في أي مكان تأتيني المرأة تعرض نفسها عليّ، وتتعرى أمامي، وتفتني؛ وذلك لأنها تعلم أن هذه الدولة لا تقيم الحدود، فما هو موقفي، وهل عليّ إثم؟","title":"كيفية التخلص من فتنة المرأة التي تعرض نفسها للزنا","answer":"الجواب: عليك أن تحذر، وعليك أن تدفعها، وتنكر عليها وتحاربها في ذلك وتغلق الباب دونها، وعليك أن تتقي الله -جل وعلا- هذا ابتلاء، وامتحان، فعليك أن تتقي الله، وأن تتكلم عليها، وأن تخبرها أن هذا لا يجوز، وأني مسلم لا يحل لي هذا الأمر، الزنا محرم في شريعة الله، وتحارب ذلك، وتخرجها من المحل، وتغلق الباب دونها، أو تخرج عنها بالكلية، وتبتعد، نسأل الله العافية.  ثم هذه من فوائد السفر إلى الخارج، هذا من فوائده -نعوذ بالله- يجب الحذر من السفر إلى الخارج، ولا يجوز الابتعاث إلى الخارج؛ لأنه شر عظيم في الدين، والأخلاق جميعًا، فيجب على المؤمن أن يحذر سفر الخارج، ولو للتعلم، يتعلم في بلاده، ويكفي، النبي -عليه الصلاة والسلام- يقول: أنا بريء من كل مسلم يقيم بين المشركين ففيه الخطر العظيم، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1734/كيفية-التخلص-من-فتنة-المراة-التي-تعرض-نفسها-للزنا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_577.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6248,"question":"إذا سافرت إلى أحد البلاد المسلمة لغرض معلوم من دراسة، وغيرها، فعندما أسكن في أي مكان تأتيني المرأة تعرض نفسها عليّ، وتتعرى أمامي، وتفتني؛ وذلك لأنها تعلم أن هذه الدولة لا تقيم الحدود، فما هو موقفي، وهل عليّ إثم؟","title":"كيفية التخلص من فتنة المرأة التي تعرض نفسها للزنا","answer":"الجواب: عليك أن تحذر، وعليك أن تدفعها، وتنكر عليها وتحاربها في ذلك وتغلق الباب دونها، وعليك أن تتقي الله -جل وعلا- هذا ابتلاء، وامتحان، فعليك أن تتقي الله، وأن تتكلم عليها، وأن تخبرها أن هذا لا يجوز، وأني مسلم لا يحل لي هذا الأمر، الزنا محرم في شريعة الله، وتحارب ذلك، وتخرجها من المحل، وتغلق الباب دونها، أو تخرج عنها بالكلية، وتبتعد، نسأل الله العافية.  ثم هذه من فوائد السفر إلى الخارج، هذا من فوائده -نعوذ بالله- يجب الحذر من السفر إلى الخارج، ولا يجوز الابتعاث إلى الخارج؛ لأنه شر عظيم في الدين، والأخلاق جميعًا، فيجب على المؤمن أن يحذر سفر الخارج، ولو للتعلم، يتعلم في بلاده، ويكفي، النبي -عليه الصلاة والسلام- يقول: أنا بريء من كل مسلم يقيم بين المشركين ففيه الخطر العظيم، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1734/كيفية-التخلص-من-فتنة-المراة-التي-تعرض-نفسها-للزنا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_577.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6343,"question":"مبلغ يستثمر في بنك فيصل الإسلامي، كيف بالنسبة لزكاته؟","title":"كيفية إخراج زكاة الأموال المستثمرة التي في البنوك الإسلامية","answer":"الجواب: الأموال تستثمر في أي مكان، إذا حال حولها؛ تزكى، سواء في بنك فيصل، أو أي بنك، كلها إذا حال حولها؛ تزكى، وأرباحها، ولكن ليس له أن يضعها بالفائدة الربوية، بل بالأرباح الشرعية، يجعلها في السيارات، يجعلها في البيوت، يجعلها في المزارع، كل يزكي أصل المال، ويزكي الربح. أما جعلها في البنوك الربوية للفائدة الربوية، كل سنة كذا، كل سنة 5%، 10% هذا يمنع، هذا من الربا المحرم، ولكن  عليه أن يزكي أصل المال، والزائد ليس له، بل هو ربا، وعليه أن يتخلى عن البنوك الربوية، فالبنوك الربوية لا يجوز التعاون معها، فإن الله يقول: ولا تعاونوا على الإثم والعدوان [المائدة:2]، والرسول ﷺ لعن آكل الربا، وموكله، وكاتبه، وشاهديه، وقال: هم سواء، إنما لعنهم؛ لأنهم يتعاونون على الإثم، والعدوان، لعن هؤلاء لما عندهم من التعاون على الإثم، والعدوان، نعوذ بالله.","link":"https://binbaz.org.sa/fatwas/1908/كيفية-اخراج-زكاة-الاموال-المستثمرة-التي-في-البنوك-الاسلامية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_692.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":6360,"question":"مبلغ يستثمر في بنك فيصل الإسلامي، كيف بالنسبة لزكاته؟","title":"كيفية إخراج زكاة الأموال المستثمرة التي في البنوك الإسلامية","answer":"الجواب: الأموال تستثمر في أي مكان، إذا حال حولها؛ تزكى، سواء في بنك فيصل، أو أي بنك، كلها إذا حال حولها؛ تزكى، وأرباحها، ولكن ليس له أن يضعها بالفائدة الربوية، بل بالأرباح الشرعية، يجعلها في السيارات، يجعلها في البيوت، يجعلها في المزارع، كل يزكي أصل المال، ويزكي الربح. أما جعلها في البنوك الربوية للفائدة الربوية، كل سنة كذا، كل سنة 5%، 10% هذا يمنع، هذا من الربا المحرم، ولكن  عليه أن يزكي أصل المال، والزائد ليس له، بل هو ربا، وعليه أن يتخلى عن البنوك الربوية، فالبنوك الربوية لا يجوز التعاون معها، فإن الله يقول: ولا تعاونوا على الإثم والعدوان [المائدة:2]، والرسول ﷺ لعن آكل الربا، وموكله، وكاتبه، وشاهديه، وقال: هم سواء، إنما لعنهم؛ لأنهم يتعاونون على الإثم، والعدوان، لعن هؤلاء لما عندهم من التعاون على الإثم، والعدوان، نعوذ بالله.","link":"https://binbaz.org.sa/fatwas/1908/كيفية-اخراج-زكاة-الاموال-المستثمرة-التي-في-البنوك-الاسلامية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_692.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":6472,"question":"موضوع الأخلاق موضوع يهم كل مسلم، فما هي الوسائل التي تعين على كسب هذه الأخلاق؟ وكذلك الصبر على القيام بها إذا كانت موجودة لدى المسلم، أفيدونا جزاكم الله خيرًا؟","title":"الوسائل المعينة على اكتساب الأخلاق الحميدة","answer":"الجواب: أعظم الأسباب: دعاء الله، والضراعة إليه أن يوفق لها، كما قال النبي ﷺ: اللهم اهدني لأحسن الأخلاق، لا يهدني لأحسنها إلا أنت، واصرف عني سيئها، لا يصرف عني سيئها إلا أنت يسأل ربه أن يعينه على مكارم الأخلاق، ومحاسن الأعمال، هذا أول الأسباب، وأعظمها. السبب الثاني: طلب العلم، والتبصر، معرفة الأخلاق الكريمة، ومعرفة الأخلاق السيئة الذميمة، حتى يعتاد الأخلاق الكريمة، وحتى يبتعد عن الأخلاق الذميمة. السبب الثالث: المحافظة على الأخيار، وصحبة الأخيار، والبعد عن الأشرار، فهذا من أعظم الأسباب للتخلق بالأخلاق الكريمة، والبعد عن الأخلاق الذميمة. السبب الرابع: العناية، وجهاد النفس، لا بد من جهاد، وصبر، لا بد أن يجاهد نفسه على الخلق الكريم، ويحذر بكل قوته، وبكل نشاطه، وبكل ما أعطاه الله من قوة الخلق الذميم، هكذا المؤمن، وهذا السبب الرابع يحتاج إلى صبر، ومصابرة .. النفس ما تحصل الأمور ... ولا بالشيء السهل، لا بد من صبر، ولا بد من جهاد لهذه النفس؛ حتى تعتاد الأخلاق الكريمة، وحتى تستقيم عليها، وحتى تبتعد عن الأخلاق الذميمة.","link":"https://binbaz.org.sa/fatwas/2217/الوساىل-المعينة-على-اكتساب-الاخلاق-الحميدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_836.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6510,"question":"شخص دفع مبلغًا من المال إلى دار المال الإسلامي قبل سنتين يقدر بأربعة آلاف ريال، ودار عليه الحول، فلا شك أن عليه الزكاة، ولكنه يدخر هذا المال؟الشيخ: أعد.الطالب: شخص دفع مبلغًا من المال إلى دار المال الإسلامي قبل سنتين يقدر بأربعة آلاف ريال، وحال عليه الحول، فلا شك أن عليه زكاة في هذه الحالة، ولكن إذا كان هذا الشخص سيتزوج قريبًا، وبحاجة ماسة إلى المال ليدفعه مهرًا في زواجه، فهل عليه في هذه الحالة دفع الزكاة؟","title":"حكم الزكاة في المال المجموع للزواج أو غيره","answer":"الجواب:  نعم ... ويتزوج هذا من أسباب البركة، والتوفيق في الزواج -إن شاء الله- الذي يجمع مالًا ليتزوج، أو يشتري بيتًا، أو يكون فيه دين، ثم يحول عليه الحول، وهو ما بعد شرى، ولا بعد تزوج، يخرج الزكاة، والزكاة كلها بركة، كلها طهرة، كلها خير.","link":"https://binbaz.org.sa/fatwas/2257/حكم-الزكاة-في-المال-المجموع-للزواج-او-غيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_880.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":6559,"question":"رجل يدخر بالبنك وديعة تساوي نصاب الزكاة كل شهر، وهكذا، فكيف يزكي عنها؟","title":"كيفية زكاة وديعة البنك الشهرية إذا بلغت النصاب","answer":"الجواب: ينظر، ويكتب ما يضع، ويجعل علامة بينة كتابة، أو غيرها، فإذا دار الحول على هذا الشيء الذي عينه، وعلم عليه؛ يزكي، أما إذا كان ما دار عليه الحول؛ ينفق هذا، ثم يحط هذا، ثم ينفقه ما يحول الحول، ما عليه شيء إذا كان المال المودع المحفوظ لا يدور عليه الحول، بل كلما أودع شيئًا؛ أكله، ثم جعله مكانه، ما عليه شيء. السؤال: لا، هو يقصد كلما يضع النصاب؛ يزود فيه بالشهر الذي بعده، والذي بعده، وهكذا القسط الأخير لن يمر عليه الحول؟ الشيخ: إذا حفظ ذلك؛ يزكي كل شيء، حتى إذا حال عليه الحول. السؤال: إذًا كل شهر يزكي على هذا؟ الشيخ: نعم، كلما حال عليه الحول؛ يزكي، ما دام حفظ هذا، وإن زكى الجميع؛ صار معجلًا للزكاة على الأخير، ولا بأس عليه.","link":"https://binbaz.org.sa/fatwas/2408/كيفية-زكاة-وديعة-البنك-الشهرية-اذا-بلغت-النصاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_935.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":6589,"question":"رجل يدخر بالبنك وديعة تساوي نصاب الزكاة كل شهر، وهكذا، فكيف يزكي عنها؟","title":"كيفية زكاة وديعة البنك الشهرية إذا بلغت النصاب","answer":"الجواب: ينظر، ويكتب ما يضع، ويجعل علامة بينة كتابة، أو غيرها، فإذا دار الحول على هذا الشيء الذي عينه، وعلم عليه؛ يزكي، أما إذا كان ما دار عليه الحول؛ ينفق هذا، ثم يحط هذا، ثم ينفقه ما يحول الحول، ما عليه شيء إذا كان المال المودع المحفوظ لا يدور عليه الحول، بل كلما أودع شيئًا؛ أكله، ثم جعله مكانه، ما عليه شيء. السؤال: لا، هو يقصد كلما يضع النصاب؛ يزود فيه بالشهر الذي بعده، والذي بعده، وهكذا القسط الأخير لن يمر عليه الحول؟ الشيخ: إذا حفظ ذلك؛ يزكي كل شيء، حتى إذا حال عليه الحول. السؤال: إذًا كل شهر يزكي على هذا؟ الشيخ: نعم، كلما حال عليه الحول؛ يزكي، ما دام حفظ هذا، وإن زكى الجميع؛ صار معجلًا للزكاة على الأخير، ولا بأس عليه.","link":"https://binbaz.org.sa/fatwas/2408/كيفية-زكاة-وديعة-البنك-الشهرية-اذا-بلغت-النصاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_935.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":6634,"question":"بعض الإخوان في غير هذه البلدان يقومون بعقد النكاح في المسجد، ما حكم هذا، ويقولون إن هذا بركة؟","title":"مشروعية عقد النكاح في المسجد","answer":"الجواب: قد استحب هذا بعض أهل العلم عقد النكاح في المسجد، فإذا فعلوه في المسجد؛ فلا حرج، وإذا فعلوه في أي مكان في البيت، أو في الدكان، أو في السوق؛ فلا بأس، ولكن بعض أهل العلم استحبه في المسجد، ولست أعلم دليلًا واضحًا على ذلك، إلا أن المسجد يفضل، ولا  أذكر الآن شيئًا ما يدل على شرعية ذلك إلا أنه من كلام بعض أهل العلم، وإذا عقد في غير المسجد في بيت الزوج، أو بيت الزوجة، أو في بيت أحد الجيران، أو الأقارب، كل هذا لا بأس به، والحمد لله، الأمر واسع. السؤال: طيب بالنسبة لأهل مكة خاصة أغلبهم لا يعقدون إلا في الحرمين؟  الجواب: ما هو بلازم في أي مكان، والحمد لله. السؤال: يشترط هذا؟ الجواب: ما هو بشرط ما هو بلازم. السؤال: ما رأيكم بحديث أعلنوا هذا النكاح، واضربوا عليه بالدفوف، واجعلوه في المساجد؟ الجواب: هذا إن صح ما في....","link":"https://binbaz.org.sa/fatwas/2489/مشروعية-عقد-النكاح-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_1016.mp3","categories":["إخراج الزكاة وأهلها","المساجد ومواضع السجود"]},{"id":6649,"question":"بعض الإخوان في غير هذه البلدان يقومون بعقد النكاح في المسجد، ما حكم هذا، ويقولون إن هذا بركة؟","title":"مشروعية عقد النكاح في المسجد","answer":"الجواب: قد استحب هذا بعض أهل العلم عقد النكاح في المسجد، فإذا فعلوه في المسجد؛ فلا حرج، وإذا فعلوه في أي مكان في البيت، أو في الدكان، أو في السوق؛ فلا بأس، ولكن بعض أهل العلم استحبه في المسجد، ولست أعلم دليلًا واضحًا على ذلك، إلا أن المسجد يفضل، ولا  أذكر الآن شيئًا ما يدل على شرعية ذلك إلا أنه من كلام بعض أهل العلم، وإذا عقد في غير المسجد في بيت الزوج، أو بيت الزوجة، أو في بيت أحد الجيران، أو الأقارب، كل هذا لا بأس به، والحمد لله، الأمر واسع. السؤال: طيب بالنسبة لأهل مكة خاصة أغلبهم لا يعقدون إلا في الحرمين؟  الجواب: ما هو بلازم في أي مكان، والحمد لله. السؤال: يشترط هذا؟ الجواب: ما هو بشرط ما هو بلازم. السؤال: ما رأيكم بحديث أعلنوا هذا النكاح، واضربوا عليه بالدفوف، واجعلوه في المساجد؟ الجواب: هذا إن صح ما في....","link":"https://binbaz.org.sa/fatwas/2489/مشروعية-عقد-النكاح-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_1016.mp3","categories":["إخراج الزكاة وأهلها","المساجد ومواضع السجود"]},{"id":6680,"question":"في رجل إذا نام يحتلم بنفسه أنه يطير في الهواء، فإذا أصبح يصبح متشائمًا، وخائفًا أنه يصيبه مصيبة من مصائب الدنيا؟","title":"ماذا يفعل من يرى رؤى مكروهة؟","answer":"الجواب: لا، لا، إذا رأى مثل هذا، وأصبح، النبي ﷺ علمنا ما نقوله، يقول النبي ﷺ: الرؤيا الصالحة من الله، والحلم من الشيطان، فإذا رأى أحدكم ما يكره؛ فلينفث عن يساره ثلاث مرات، وليتعوذ بالله من الشيطان، من شر ما رأى ثلاث مرات، ثم ينقلب على جنبه الآخر؛ فإنها لا تضره، ولا يخبر بها أحدًا هذا دواء المرائي المكروهة. إذا رأى مرائي مكروهة تسيئ إليه، وتحزنه، إذا استيقظ يتفل عن يساره ثلاث مرات، ويقول: أعوذ بالله من الشيطان، ومن شر ما رأى، ثلاث مرات، ثم ينتقل على جنبه الآخر؛ فإنها لا تضره، ولا يخبر بها أحدًا، هذه السنة، أما إن رأى ما يحب؛ فإنه يحمد الله، ويخبر به من شاء.","link":"https://binbaz.org.sa/fatwas/2564/ماذا-يفعل-من-يرى-روى-مكروهة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1059.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6722,"question":"رأيت فيما يرى النائم، قد شفت والدي المتوفي في الرؤيا أنه قادم علينا من جهة الشمال، ومتوجه إلى الجنوب، ونحن عند ركن المسجد -مسجد القرية- وأن أطرافه كلها محترقة .. من الثوب، ووجهه محترق، وأن عليه أثر الحريق بلد في جسمه، وتوجه إلى الجنوب، ولم يدخل معنا المسجد، نرجو الإجابة؟","title":"ما يفعله الإنسان إذا رأى رؤيا مكروهة","answer":"الجواب:  مثل هذه الرؤيا لا تخبر بها أيها السائل، يقول النبي ﷺ: الرؤيا الصالحة من الله، والحلم من الشيطان، فإذا رأى أحدكم ما يكره؛ فلينفث عن يساره ثلاث مرات، وليتعوذ بالله من الشيطان، ومن شر ما رأى ثلاث مرات، ثم لينقلب على جنبه الآخر، ولا يخبر بها أحدًا، فإنها لا تضره هذا هو الشرع.  إذا رأيت أن أباك محترق، أو أنك محترق، أو أمك، أو بنتك، أو ما أشبه ذلك، فلا ينبغي لك أن تخبر الناس بذلك، بل ينبغي لك إذا استيقظت أن تنفث عن يسارك، تتفل عن يسارك ثلاث مرات، وتقول: أعوذ بالله من الشيطان، ومن شر ما رأيت، ثلاث مرات، ثم تنقلب على جنبك الآخر، فإنها لا تضرك -إن شاء الله- ولا تخبر بها أحدًا، هكذا قال المصطفى عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/2595/ما-يفعله-الانسان-اذا-راى-رويا-مكروهة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1091.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6810,"question":"هل يجوز دفع الزكاة إلى المتضررين من الجفاف في أفريقيا؟ وهل لمن وجبت عليه الزكاة أن يشتري بها عروضًا، ويرسل بها إليهم؟","title":"حكم دفع الزكاة للمتضررين من الجفاف في أفريقيا","answer":"الجواب: المتضررون في أفريقيا من أحق الناس .. والمساعدة، والمواساة لما أصابهم من الفاقة، والحاجة، والجفاف، والجوع، فهم في أشد الحاجة إلى دعم إخوانهم المسلمين، ومواساتهم من الزكاة، وغيرها، فالزكاة تدفع للمسلمين، وغير الزكاة تدفع للمسلمين، وغير المسلمين ممن يعرف عنهم الفاقة، والجوع.  والصدقة على الكفار جائزة، صدقة التطوع، والمواساة جائزة، وهكذا تأليف الكفار من الزكاة جائز، جعل الله لهم حقًا للمؤلفة قلوبهم من الكفار جائزة، ومن صدقة التطوع لعمومهم جائزة، كما قال -جل وعلا- في كتابه العظيم: لَا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ وَلَمْ يُخْرِجُوكُمْ مِنْ دِيَارِكُمْ أَنْ تَبَرُّوهُمْ وَتُقْسِطُوا إِلَيْهِمْ إِنَّ اللَّهَ يُحِبُّ الْمُقْسِطِينَ [الممتحنة:8].  وفي الصحيحين عن أسماء بنت أبي بكر الصديق -رضي الله تعالى عنهما- أن أمها زارتها في المدينة، وهي كافرة في الهدنة، فقالت أسماء: يا رسول الله، إن أمي جاءتني في المدينة، وهي كافرة، وهي راغبة في أن أصلها، فقال النبي: صليها فأمرها أن تصلها بالمال -وهي كافرة- لأنها غير حربية. فيعطى الكافر غير الحربي المستأمن، والمعاهد، يعطى شيئًا من المال، ويواسى، ويحسن إليه، لا بأس بذلك غير الزكاة، أما الزكاة، فتعطى للمؤلفة قلوبهم من الرؤساء، والكبار، ولما يجرى بالإحسان إليهم قوة إيمانهم، أو إسلام نظرائهم، أو كف شرهم.","link":"https://binbaz.org.sa/fatwas/2678/حكم-دفع-الزكاة-للمتضررين-من-الجفاف-في-افريقيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1175.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":6829,"question":"هل يجوز دفع الزكاة إلى المتضررين من الجفاف في أفريقيا؟ وهل لمن وجبت عليه الزكاة أن يشتري بها عروضًا، ويرسل بها إليهم؟","title":"حكم دفع الزكاة للمتضررين من الجفاف في أفريقيا","answer":"الجواب: المتضررون في أفريقيا من أحق الناس .. والمساعدة، والمواساة لما أصابهم من الفاقة، والحاجة، والجفاف، والجوع، فهم في أشد الحاجة إلى دعم إخوانهم المسلمين، ومواساتهم من الزكاة، وغيرها، فالزكاة تدفع للمسلمين، وغير الزكاة تدفع للمسلمين، وغير المسلمين ممن يعرف عنهم الفاقة، والجوع.  والصدقة على الكفار جائزة، صدقة التطوع، والمواساة جائزة، وهكذا تأليف الكفار من الزكاة جائز، جعل الله لهم حقًا للمؤلفة قلوبهم من الكفار جائزة، ومن صدقة التطوع لعمومهم جائزة، كما قال -جل وعلا- في كتابه العظيم: لَا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ وَلَمْ يُخْرِجُوكُمْ مِنْ دِيَارِكُمْ أَنْ تَبَرُّوهُمْ وَتُقْسِطُوا إِلَيْهِمْ إِنَّ اللَّهَ يُحِبُّ الْمُقْسِطِينَ [الممتحنة:8].  وفي الصحيحين عن أسماء بنت أبي بكر الصديق -رضي الله تعالى عنهما- أن أمها زارتها في المدينة، وهي كافرة في الهدنة، فقالت أسماء: يا رسول الله، إن أمي جاءتني في المدينة، وهي كافرة، وهي راغبة في أن أصلها، فقال النبي: صليها فأمرها أن تصلها بالمال -وهي كافرة- لأنها غير حربية. فيعطى الكافر غير الحربي المستأمن، والمعاهد، يعطى شيئًا من المال، ويواسى، ويحسن إليه، لا بأس بذلك غير الزكاة، أما الزكاة، فتعطى للمؤلفة قلوبهم من الرؤساء، والكبار، ولما يجرى بالإحسان إليهم قوة إيمانهم، أو إسلام نظرائهم، أو كف شرهم.","link":"https://binbaz.org.sa/fatwas/2678/حكم-دفع-الزكاة-للمتضررين-من-الجفاف-في-افريقيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1175.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":6909,"question":"شاب هداه الله والحمد لله، ولكنه يعاني من مضايقة والديه له، بأن يمنعانه من الخروج مع الشباب الصالح، ويعاني في المنزل من الملاهي، والغناء، وهو يتضايق من ذلك كثيرًا، فبماذا تصلونه جزاكم الله خيرًا؟","title":"طاعة الوالدين تكون في المعروف","answer":"الجواب:  إنما الطاعة في المعروف إذا كان والداه منحرفين، ويأمرانه بالانحراف؛ فليس له طاعتهما، إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق فلا بأس أن يصحب الأخيار، ويخرج في بيت وحده مع أهله؛ لسوء الحال في بيت والديه من المعاصي، ومع ذلك يصلهما، ويحسن إليهما بالكلام الطيب، والفعل الطيب، ويزورهما، ويقدم المعونة لهما، والصلة لهما ما لم يطرداه، ويأبيا قبول صلته.","link":"https://binbaz.org.sa/fatwas/2846/طاعة-الوالدين-تكون-في-المعروف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1294.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6916,"question":"هل يدخل في صلة الأرحام أقارب زوجتي، ووالديها، وإخوتها، وأخواتها، وأزواج أخواتها؟","title":"أقارب الزوجة ليسوا من الأرحام","answer":"الجواب: أقارب الزوجة ليسوا بأرحام، ولكنهم أصهار، وإنما أرحام لها، هم أرحام لزوجتك، وأما أنت فليسوا أرحامًا لك، أبوها، وإخوانها، وأخواتها، وأخوالها، وخالاتها، وأعمامها، وعماتها، وسائر قراباتها هم أقارب لها، وأرحام لها هي، عليها أن تصلهم حسب طاقتها، وأما أنت فليسوا أرحامًا لك ولكنهم أصهار لك، لكن إذا أحسنت إليهم بالكلام الطيب، والفعل الطيب؛ هذا طيب، ولكن ليسوا من الأرحام الذين قطيعتهم قطيعة رحم، وإنما الإحسان إليهم من باب مكارم الأخلاق.","link":"https://binbaz.org.sa/fatwas/2840/اقارب-الزوجة-ليسوا-من-الارحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1288.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6922,"question":"أنا والحمد لله كثير الاستغفار، والدعاء لوالدي في الصلاة، وغيرها، ولكن بعض الأحيان أمزح معهما بكلام لا سخط فيه، وأحاول بهذا إسعادهما، ولأكمل السعادة، وكسب رضاهما عني، وهما -والحمد لله- راضيان عني، فهل المزاح معهما يجوز، أم لا يجوز؟ وما حكم إذا ناديت أبي يا فلان، دون أن أقول: أبي، وأمي كذلك؟","title":"حكم المزاح مع الوالدين","answer":"الجواب: المزاح بالحق إذا كان قليلُا ما يضر، إذا كان مزاحًا، يعني يسرهما، ويوسع خاطرهما بحق ليس بكذب، ولا إيذاء؛ لا بأس به، لكن الممازح لا يقول إلا حقًا، ولا يكثر حتى لا يفضي إلى شر.  والسنة أن يدعوه بأحب أسمائه إليه، كأبي فلان، أو يا والدي، يا أبت، أو يا أبا فلان إذا كان يحب ذلك، يا أبا عبدالله، يا أبا عبدالرحمن، يا أبا إبراهيم.","link":"https://binbaz.org.sa/fatwas/2851/حكم-المزاح-مع-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1299.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6965,"question":"أفيدكم بأن فيه بعض من قبائل البادية، وغيرهم من الناس يتفقون على جمع بعض من المال خاصة للحوادث، ويكون هذا المبلغ لدى إنسان، وعندما يكون على أحد أفراد هذا الفخذ التابع للقبيلة، أو دية؛ يتقدم إلى الذي لديه النقود، ويعطيه المبلغ، وبعدما يسدد الدية المطلوبة؛ يقوم بتسديد .. حتى يرد المبلغ الأول إلى أمين الجمعية الخاصة بالفخذ، علمًا أن الأغلبية من هذا الفخذ بحاجة ماسة عندما تقع هذه الحوادث، ويكون في يوم محرج، وبعضهم غير محتاج إليها، لذا نأمل أن توضحوا لنا هذه الطريقة، هل هي جائزة، أم تتنافى مع الدين؟","title":"حكم جمع مال وتخصيصه للحوادث بين أفراد القبيلة","answer":"الجواب:\n\nلا حرج في ذلك، إذا اجتمعت القبيلة، أو بعض القبيلة على مساعدة معينة يجمعونها عند شخص منهم للحوادث، طابت بها نفوسهم؛ فلا بأس بذلك؛ إذا طابت بها نفوسهم، من أجل حوادث تحصل عليهم من قتل، أو غير قتل، من جراحات، أو فقر، أو من كارثة من سيل، أو حريق، أو ما أشبه ذلك، فلا حرج.\n\nهذا من باب التعاون على الخير، ومن باب الإحسان، وجبر المصاب، وسد حاجة الضعيف؛ فلا بأس بهذا -إن طابت بها نفوسهم- تجمع، وليس عليها زكاة، ويعطاها المحتاج على قدر ما أصابه، وليس لهم الرجوع فيها إذا بذلوها، ليس لهم الرجوع فيها؛ لأنهم أخرجوها لله، فتصرف في الجهات التي عينوها، وكلما قل ما بيد الأمين؛ طلب منهم، وأخبرهم أن يعطوه شيئًا آخر؛ ليعدوا ذلك للكوارث، والحوادث التي تصيبهم. \n\nالسؤال: وليس فيها زكاة؟\n\nالجواب: وليس فيها زكاة.\n\nالسؤال: وتخرج من مال الزكاة؟\n\nالجواب: لا ما هو -على كل حال- ينبغي أن تكون من غير الزكاة؛ لأن الزكاة لها مصارف مخصوصة، فإذا جعلها من الزكاة؛ لابد تعين كونها لا يعطاها إلا من هو من أهل الزكاة.\n\nالسؤال: بعضهم يا شيخ يجمع أكثر من ثلاثمائة، أربعمائة ..\n\nالجواب: ولو مليون، لكن ليس من الزكاة، الزكاة تخرج في الحال لأهلها.","link":"https://binbaz.org.sa/fatwas/2929/حكم-جمع-مال-وتخصيصه-للحوادث-بين-افراد-القبيلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1377.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":6984,"question":"أفيدكم بأن فيه بعض من قبائل البادية، وغيرهم من الناس يتفقون على جمع بعض من المال خاصة للحوادث، ويكون هذا المبلغ لدى إنسان، وعندما يكون على أحد أفراد هذا الفخذ التابع للقبيلة، أو دية؛ يتقدم إلى الذي لديه النقود، ويعطيه المبلغ، وبعدما يسدد الدية المطلوبة؛ يقوم بتسديد .. حتى يرد المبلغ الأول إلى أمين الجمعية الخاصة بالفخذ، علمًا أن الأغلبية من هذا الفخذ بحاجة ماسة عندما تقع هذه الحوادث، ويكون في يوم محرج، وبعضهم غير محتاج إليها، لذا نأمل أن توضحوا لنا هذه الطريقة، هل هي جائزة، أم تتنافى مع الدين؟","title":"حكم جمع مال وتخصيصه للحوادث بين أفراد القبيلة","answer":"الجواب:\n\nلا حرج في ذلك، إذا اجتمعت القبيلة، أو بعض القبيلة على مساعدة معينة يجمعونها عند شخص منهم للحوادث، طابت بها نفوسهم؛ فلا بأس بذلك؛ إذا طابت بها نفوسهم، من أجل حوادث تحصل عليهم من قتل، أو غير قتل، من جراحات، أو فقر، أو من كارثة من سيل، أو حريق، أو ما أشبه ذلك، فلا حرج.\n\nهذا من باب التعاون على الخير، ومن باب الإحسان، وجبر المصاب، وسد حاجة الضعيف؛ فلا بأس بهذا -إن طابت بها نفوسهم- تجمع، وليس عليها زكاة، ويعطاها المحتاج على قدر ما أصابه، وليس لهم الرجوع فيها إذا بذلوها، ليس لهم الرجوع فيها؛ لأنهم أخرجوها لله، فتصرف في الجهات التي عينوها، وكلما قل ما بيد الأمين؛ طلب منهم، وأخبرهم أن يعطوه شيئًا آخر؛ ليعدوا ذلك للكوارث، والحوادث التي تصيبهم. \n\nالسؤال: وليس فيها زكاة؟\n\nالجواب: وليس فيها زكاة.\n\nالسؤال: وتخرج من مال الزكاة؟\n\nالجواب: لا ما هو -على كل حال- ينبغي أن تكون من غير الزكاة؛ لأن الزكاة لها مصارف مخصوصة، فإذا جعلها من الزكاة؛ لابد تعين كونها لا يعطاها إلا من هو من أهل الزكاة.\n\nالسؤال: بعضهم يا شيخ يجمع أكثر من ثلاثمائة، أربعمائة ..\n\nالجواب: ولو مليون، لكن ليس من الزكاة، الزكاة تخرج في الحال لأهلها.","link":"https://binbaz.org.sa/fatwas/2929/حكم-جمع-مال-وتخصيصه-للحوادث-بين-افراد-القبيلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1377.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":7019,"question":"عندي مبلغ أمانة، هل يجب أن أزكيه علمًا أن صاحب المبلغ لم يوافق على إخراج الزكاة لجهله بالأحكام الشرعية؟","title":"حكم إخراج الزكاة من الأمانة وحكم التصرف فيها","answer":"الجواب:\n\nليس لك أن تزكيه أنت، ولكن تنصح صاحبه، تقول له: الزكاة واجبة، أو تقول له .. أو يزكه بنفسه، أو يأذن لك، تشير عليه أنه يأذن لك .. حتى تؤدي الزكاة عن هذه الأمانة، أما أن تؤديها بدون إذنه وبدون وكالته لا، لكن تنصحه، وتبين له الحكم الشرعي، وأنه تجب الزكاة فيما حال عليه الحول، حتى يأذن لك، حتى يوكلك.\n\nالسؤال: هل يجوز التصرف في مال الأمانة بغير إذن صاحبه؟\n\nالجواب: لا، ليس له التصرف إلا بإذن صاحبها.\n\nالسؤال: حتى ولو كانت معدودة معروفة؟\n\nالجواب: ولو لا يتصرف إلا بإذنه.","link":"https://binbaz.org.sa/fatwas/2933/حكم-اخراج-الزكاة-من-الامانة-وحكم-التصرف-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1381.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":7050,"question":"أنا موظف أتقاضى راتبًا طيبًا والحمد لله، إلا أنني لا أعرف كيف أدفع زكاته، هل أخرجها عن كل شهر، أم أضع لنفسي حولًا معينًا لكل ما تحت يدي مما حصلت عليه عن طريق الوظيفة، أو غيرها؟ وإذا نفد المبلغ، وتحصلت على مبلغ جديد يصل للنصاب، فهل أبدأ باحتساب الحول من تاريخ المبلغ الأول الذي نفد، أم من تاريخ حصولي على المبلغ الجديد؟","title":"كيفية حساب الحول في زكاة المال المتجدد","answer":"الجواب:\n\nكلما حصلت على مبلغ يكون مبدأ الحول من المبلغ الجديد، كلما جاءك مال ترسم لك خطة تضبطها في الكتابة، فإذا دار الحول على هذا المال الجديد فزكه، فالذي جاء في محرم؛ زكه في محرم، والذي جاءك في صفر؛ زكه في صفر، والذي جاءك في ربيع آخر؛ زكه في ربيع آخر، وهكذا. \n\nلكن لو قدمت الأخير مع الأول، وعجلت زكاة الأخير مع الأول؛ فأنت مشكور ولا بأس، لو كان عندك راتب شهر محرم وصفر وربيع أول إلى آخره، كل شهر مكتوب عندك، ثم أخرجت زكاة الشهور هذه مع محرم، وقدمتها مع محرم؛ فلا بأس عليك، فتخرج الزكاة للجميع شيئًا معجلًا؛ فلا بأس عليك، لكن الواجب عليك أنك تخرج كل زكاة في وقتها، كلما تم الحول أخرجت الواجب حسب ما كتبت عندك، ووقت عندك، وإن عجلت بعض ذلك مع زكاة ما قبله؛ فلا بأس عليك.","link":"https://binbaz.org.sa/fatwas/3067/كيفية-حساب-الحول-في-زكاة-المال-المتجدد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1454.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":7060,"question":"أنا إنسان لم أخرج الزكاة منذ أن ملكت النصاب قبل حوالي ثلاث سنوات، وقدرت ما أملكه بيدي، أو في ذمة غيري لي هو مبلغ معين، فهل أدفع زكاة الثلاث سنوات التي مضت إذا حال الحول الثالث في هذا العام، علمًا بأني قادر، ومستطيع على ذلك، أم ما هو العمل؟","title":"ماذا يعمل من أخر الزكاة حولين؟","answer":"الجواب:\n\nعجل الزكاة عن الحولين الماضيين، عجلها واستغفر ربك، وتب إليه عما أخرت، وإذا تم الحول الثالث؛ فأخرج زكاته، لا تأخر هذه، عجل زكاة الحولين مع التوبة والاستغفار، وإذا تم الحول الثالث؛ فزك.","link":"https://binbaz.org.sa/fatwas/3071/ماذا-يعمل-من-اخر-الزكاة-حولين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1457.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":7168,"question":"لي مال وفرته عن طريق راتبي الشهري في العمل خلال سنة، هل فيه زكاة، علمًا بأنني لا أحدد متى أصرف منه؟","title":"زكاة الراتب الشهري","answer":"الجواب:\n\nإذا وفر الموظف من راتبه شيئًا؛ فعليه أن يضبط ذلك بالكتاب؛ حتى يعلم ابتداء ذلك وانتهائه، فكلما تمت عليه السنة زكاه بربع العشر، فإذا كان يوفر كل شهر ألفًا، أو ألفين، يقيد الشهر الذي وفر فيه إذا تمت السنة؛ زكى هذا الموفر.\n\nوهكذا الشهر الثاني، وهكذا الشهر الثالث، كل شهر يزكيه إذا حال عليه حوله، وإن زكى الجميع عندما يحول الحول على الشهر الأول؛ جاز ذلك، وصارت الزكاة عن الشهر الثاني، والذي بعده مزكاة معجلة، ولا يضره ذلك.\n\nالسؤال: يعني نسبة كل شهر يدفع زكاتها؟\n\nالجواب: كل شهر إذا تمت السنة وجب إخراج الزكاة، ثم هكذا الشهر الثاني، وهكذا الشهر الثالث، وهكذا الشهر الرابع.\n\nالطالب: يعني وكأنه يدفع زكاة كل شهر؟\n\nالجواب: نعم.\n\nالطالب: على أساس أنه كل شهر مر عليه اثنا عشر شهرًا؟\n\nالجواب: هذا هو، وإن زكى عن الجميع في أول السنة؛ حصل المقصود، وصارت الشهور المتأخرة زكاتها.","link":"https://binbaz.org.sa/fatwas/3205/زكاة-الراتب-الشهري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1555.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":7174,"question":"هل يجوز إذا دخل رجل إلى المجلس أن نقف للسلام عليه؟","title":"حكم وقوف الجالس للسلام على القادم","answer":"الجواب:\n\nأما إذا كان للمقابلة ومصافحته فلا بأس، أما ما يفعله الناس وقوف فقط فهذا ما ينبغي، أقل أحواله الكراهة، كان النبي يكره ذلك -عليه الصلاة والسلام- ولا يحب أن يقوموا له -عليه الصلاة والسلام- ولما قاموا على رأسه وهو يصلي جالسًا؛ أمرهم بالجلوس -عليه الصلاة والسلام- قال: كدتم أن تعظموني كما تعظم فارس والروم رؤساءها، أما إذا قام إليه يصافحه، قام للضيف يصافحه، ويجلسه في المحل المناسب؛ فهذا لا بأس به.\n\nالسؤال: طيب يعني منزلة في ناس تختلف، يعني في حكام رؤساء قضاة علماء يعني؟ \n\nالجواب: ولو، هو الملك لا يقوم، حتى الملك لا يقوم وهو بعيد .. يصافحه، يتقدم له ويصافحه، أما يقوم وهو في مكانه، لا.","link":"https://binbaz.org.sa/fatwas/3213/حكم-وقوف-الجالس-للسلام-على-القادم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1561.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":7199,"question":"والدتي طلبت مني تسمية ابنتي باسم ترغبه هي، وهو اسم والدتها، وأنا أرغب أن أسميها باسم إحدى أمهات المؤمنين، أو الصحابيات، أفتونا مأجورين، هل أنفذ رغبة والدتي؟","title":"طاعة الأم في تسميتها المولود","answer":"الجواب:\n\nنعم نعم، رغبة والدتك أولى من رغبتك أنت، إذا كان الاسم الذي قالت والدتك ما فيه محظور، إذا كان اسمًا سائغًا، لا محذور فيه، هي قالت: تريدها مريم، وأنت تقول: أريدها فاطمة، أو عائشة؛ قدم الأم، كلها أسماء جائزة، وفي تقديم ما قالت أمك خير كثير، ورضاء لها، والأمر في هذا واسع والحمد لله، فلا حاجة إلى أن تعصيها.","link":"https://binbaz.org.sa/fatwas/3277/طاعة-الام-في-تسميتها-المولود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1602.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":7210,"question":"أنا رجل هداني الله إلى الحق والحمد لله، ولكن أجد صعوبة في البيت، وأن أهلي يأمرونني على ترك إخواني في الله، ويقولون: هؤلاء مثل الفئة الضالة، ويمنعوني من فعل الخير، ومنعي من الصلاة التي يكون بعدها أحيانًا جلسة للقراءة في كتاب، أو نحوه، وأنهم لا يستمعون لي؛ لأني حريص، ويعاملونني معاملة الطفل، وعدم الاستماع إلى الأشرطة الدينية، ويقولون: هذه ضالة إلى آخره؟","title":"حكم منع الآباء أبناءهم من مصاحبة الأخيار","answer":"الجواب:\n\nعلى كل حال، عليك يا ولدي تعمل ما تستطع من إرضاء والديك، ومراعاة خاطرهما، وأهلك بالكلام الطيب، والأسلوب الحسن، لكن ليس عليك أن تطيعهما فيما يضرك، أو في معصية ربك مثل ما تقدم.\n\nتخرج لطلب العلم، وتخرج للصلاة في الجماعة، ولكن بالأسلوب الحسن، والكلام الطيب، وتسمع الأشرطة الطيبة، وتحثهم -تحث والديك وإخوتك وقراباتك- تحثهم على سماع الشيء الذي ينفعهم بالكلام الطيب، والأسلوب الحسن، لا بالعنف، والشدة، والتعاظم عليهم، ولكن بالكلام الطيب، والأسلوب الحسن؛ حتى تخرج من غضب والديك، وحتى يحصل لك أداء ما أوجب الله عليك.","link":"https://binbaz.org.sa/fatwas/3279/حكم-منع-الاباء-ابناءهم-من-مصاحبة-الاخيار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1604.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":7221,"question":"أريد أن أخرج عن أهلي لأسكن أنا وأولادي ببيت خاص بنا، ووالدي لا يرضى بذلك، هل لو خرجت وهم لا يرضون بذلك يكون هذا عقوقًا؟","title":"حكم مفارقة الوالدين في سكن مستقل بدون رضاهم","answer":"الجواب:\n\nينبغي لك أنك تلاحظ رضاهم، وتحرص على رضاهم حتى -إن شاء الله- تخرج برضاهم، وإذا كان جلوسك معهم فيه معصية لله؛ لأنك تؤذى من إخوانك، أو من غير إخوانك؛ فلا بأس أن تخرج.\n\nلكن خروجك بالرضا، ومسامحة الوالدين، والحرص على إرضائهما؛ يكون أولى لك، وإذا كان ما هناك داع للخروج، ووالداك في حاجة إليك؛ لا تخرج.","link":"https://binbaz.org.sa/fatwas/3290/حكم-مفارقة-الوالدين-في-سكن-مستقل-بدون-رضاهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1615.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":7227,"question":"ما حكم إعطاء الشخص غير القادر على الزواج الزكاة، أو بعض منها؟ مثلًا أن يعطي الأب قريبًا له الزكاة؛ لكي يتزوج؛ لأنه غير قادر على الزواج؟","title":"صرف الزكاة لغير القادر على الزواج","answer":"الجواب:\n\nنعم لا بأس أن يعطى العاجز عن الزواج من الزكاة ما يعينه على الزواج، لا بأس بذلك؛ لأنه فقير والحال ما ذكر، فالعاجز عن الزواج يعتبر فقيرًا؛ تصرف له الزكاة حتى يتزوج نعم.","link":"https://binbaz.org.sa/fatwas/3288/صرف-الزكاة-لغير-القادر-على-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1613.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":7263,"question":"أنا رجل كثير المزاح، وتصدر مني بعض الأحيان كلمات فيها جرح لبعض الإخوان دون قصد مني، أو بقصد، فما تنصحونني؟","title":"الاعتدال في المزاح","answer":"الجواب:\n\nننصحك أولًا بقلة المزاح، عليك بالتقليل من المزاح، والنبي ﷺ كان يمزح لكنه قليل -عليه الصلاة والسلام- مزحه قليل، وكان يمزح، ولكن لا يقول إلا حقًا -عليه الصلاة والسلام- فعليك أن تحذر الإكثار من المزاح، فإنه ربما يفضي إلى شر، وإذا مزحت فاحذر أن تقول إلا حقًا، إياك أن تجرح أخاك، أو تؤذي أخاك بكلام يضره، أو تقول فيه خلاف الصواب.\n\nالمقصود: أولًا: قلة المزاح، وهو الذي ينبغي.\n\nثانيًا: إذا مزحت لا تقل إلا حقًا، واحذر أن تقول الباطل.","link":"https://binbaz.org.sa/fatwas/3340/الاعتدال-في-المزاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1661.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":7273,"question":"أنا رجل كثير المزاح، وتصدر مني بعض الأحيان كلمات فيها جرح لبعض الإخوان دون قصد مني، أو بقصد، فما تنصحونني؟","title":"الاعتدال في المزاح","answer":"الجواب:\n\nننصحك أولًا بقلة المزاح، عليك بالتقليل من المزاح، والنبي ﷺ كان يمزح لكنه قليل -عليه الصلاة والسلام- مزحه قليل، وكان يمزح، ولكن لا يقول إلا حقًا -عليه الصلاة والسلام- فعليك أن تحذر الإكثار من المزاح، فإنه ربما يفضي إلى شر، وإذا مزحت فاحذر أن تقول إلا حقًا، إياك أن تجرح أخاك، أو تؤذي أخاك بكلام يضره، أو تقول فيه خلاف الصواب.\n\nالمقصود: أولًا: قلة المزاح، وهو الذي ينبغي.\n\nثانيًا: إذا مزحت لا تقل إلا حقًا، واحذر أن تقول الباطل.","link":"https://binbaz.org.sa/fatwas/3340/الاعتدال-في-المزاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1661.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":7284,"question":"هل تجوز غيبة الكافر؟","title":"حكم غيبة الكافر","answer":"الجواب:\n\nفيما أظهر، غيبته فيما أظهر من كفره، يقال: فلان فعل كذا، وفعل كذا نعم، بل قد تجب عند الحاجة إلى ذلك؛ حتى يقام عليه الحد الشرعي من استتابته، أو قتله، وهكذا الفاسق فيما أظهر من فسقه، ليس له غيبة فيما أظهر.","link":"https://binbaz.org.sa/fatwas/3354/حكم-غيبة-الكافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1675.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":7287,"question":"هل تغيير المسميات يقصد الأخ التورية..؟","title":"حكم التورية","answer":"الجواب:\n\nفي التأويل مندوحة عن الكذب، إذا تأول للحاجة من دون أن يجحد حقًا، أو يدعو إلى باطل، ففي التأويل، وفي التعريض مندوحة عليه أن يتحرى في كلامه الحق. \n\nوإذا كان يخشى من التصريح شيئًا يأتي بالمعاريض التي يحصل بها  المقصود من دون أن يكذب على أحد، أو يظلم أحدًا أو يتكلم بما حرم الله.","link":"https://binbaz.org.sa/fatwas/3350/حكم-التورية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1671.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":7323,"question":"هل يجوز صرف مال الزكاة في شراء بطانيات وإرسالها للمجاهدين؟","title":"صرف مال الزكاة للمجاهدين","answer":"الجواب: لا مانع، الصواب لا بأس، إذا جعل الزكاة في ملابس للفقراء، أو حبوب للفقراء، إذا كان الفقراء قد لا ينفذون الدراهم فيما ينبغي، مثل الصغار، ومثل السفهاء، ومثل العاجزين إذا جعل الزكاة في طعام لهم، أو في ملابس لهم؛ فالصحيح أنه لا حرج.","link":"https://binbaz.org.sa/fatwas/3389/صرف-مال-الزكاة-للمجاهدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1705.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":7364,"question":"دكتور إنجليزي يدين بالديانة المسيحية، قد أجرى عملية لوالدة بعض الأسر، فقاموا بشكره في بعض الصحف على نجاح العملية، فهل يجوز أن يشكر مثل ذلك الدكتور، أو أي دكتور، ولو كان مسلمًا؟","title":"حكم شكر طبيب مسيحي نجح في إجراء عملية","answer":"الجواب: الشكر لمن فعل معروفًا طيب لا يشكر الله من لا يشكر الناس الرسول ﷺ يقول: من فعل إليكم معروفًا؛ فكافئوه، فإن لم تجدوا ما تكافئوه به؛ فادعوا له المقصود: إذا شكر على نجاح العملية، وأن العملية انتهت ما يضر، سواء كان كافرًا أو مسلمًا.","link":"https://binbaz.org.sa/fatwas/3449/حكم-شكر-طبيب-مسيحي-نجح-في-اجراء-عملية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1755.mp3","categories":["إخراج الزكاة وأهلها","الآداب والأخلاق المحمودة"]},{"id":7464,"question":"سماحة الشيخ! في أول هذه الرسائل رسالة وردت يقول فيها صاحبها: أقرضت شخصًا عشرة آلاف ريال، وحال عليها الحول عنده وأخرج هو زكاتها برضا منه ومن جيبه الخاص، من غير شرط بيني وبينه، وأخبرني بذلك ورضيته، فهل تبرئ ذمتي بهذا الإخراج؟","title":"حكم إخراج المقترض للزكاة من مال المقرض بغير إذنه","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفإخراج الزكاة عبادة وقربة تحتاج إلى نية من المخرج، فإذا أخرج الإنسان عن آخر زكاة ماله، سواء كان ذلك المال قرضاً أو أمانة أو غير ذلك، فإن في صحة الإخراج خلافاً بين العلماء مبنياً على التصرف الفضولي؛ وهو تصرف الإنسان في مال غيره بغير إذنه. فمن أهل العلم من قال: إن ذلك يجزي إذا أجازه المالك والمسئول. ومنهم من قال: لا يجزئ، بل لابد من نية مصاحبة للإخراج في مثل هذا، فالأظهر عند جمع من أهل العلم أنه لا يجزئ؛ لأنه أخرجه من دون أن يشاور صاحب الزكاة ومن دون أن يأخذ إذنه في ذلك، بل أخرجه تبرعاً من دون إذن، فالأحوط لهذا المخرج عنه أن يزكي وأن لا يكتفي بهذه الزكاة، وإن اكتفى بها أجزأت عند جمع من أهل العلم؛ لأنه أجازها.\nالمقدم: وهو هنا يقول: وأخرج الزكاة برضًا مني، هذا يعني: برضا منه هو من المخرج؛ ولكنه رضي فيما بعد.\nالشيخ: كأنه رضاً يعني: جديد، ما هو  سابق، يكون رضًا جديد وإذن جديد.\nأما ذاك فقد أخرج مال من دون استئذان، كأنه قد رأى أنه يمن عليه في هذا الشيء، وأن هذا إحسان سوف يوافق عليه، فلهذا لم يستأذنه، أو لعله خاف أن يمنعه من ذلك، وهو يحب أن يجازيه على إقراضه بالإحسان؛ لأن النبي عليه السلام قال: إن خيار الناس أحسنهم قضاء، فالحاصل: أن الإجزاء قال به جمع من أهل العلم بالإمضاء والإجازة.\nوالقول الثاني: أنه لا يجزي؛ لأن النية لم تصاحبه في ذاك الوقت، حين أخرج ليس عنده نية، يعني: ليس عنده إذن سابق بنى عليه حتى يكون وكيله. نعم.","link":"https://binbaz.org.sa/fatwas/4182/حكم-اخراج-المقترض-للزكاة-من-مال-المقرض-بغير-اذنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_002/00201.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":7485,"question":"هذه رسالة من المرسلة (م. ح) تسأل عن الزكاة في السؤال الأول تقول: أنا فتاة متوفى عني والدي وترك لي ورث كثير من المال، وهذا المال قد سلفته إخواني، جميع المبلغ الذي تركه لي والدي يقارب سبعمائة ألف ريال، تقول: وأسأل هل علي زكاة في هذا المبلغ، وهذا ليس عندي ولا أنتفع به، وقد قال لي الأخ الكبير: أنا أعطيك مبلغ من المال لتزكي عن أموالك، نظراً وأن هذا الأخ متسلف مبلغ كبير من مالي هذا، فهل يصح أن آخذ منه لأزكي أم لا زكاة علي؟","title":"حكم زكاة الدين","answer":"الجواب:  إذا كان المال عند الإخوة وهم أملياء ليس في خطر فإن عليك الزكاة، عليك أيها السائلة الزكاة، تزكين هذا المال، سواء كان من المال الذي قال أخوك الكبير أنه يعطيك إياه، أو من المال الذي عندك إن كان عندك شيء.\nفالحاصل: أن الإخوة الذين اقترضوا المال ينظر فيهم، فإن كانوا أملياء والمال ليس عليه خطر عندهم فإن عليك الزكاة تزكين هذا المال كل سنة، وإن أجلت الزكاة حتى تقبضي وتزكي هذا المال عن كل سنة ماضية فلا بأس. ولكن الأولى والأحوط أن تزكيه كل حول حذراً من الموت، حذراً من النسيان، ما داموا أملياء فإن عليك أن تزكيه كل حول، هذا المال الذي عند إخوتك بالقرض، أما إن كانوا معسرين فقراء يخشى على المال الذي عندهم أن لا يرجع؛ لأنهم ليسوا بأغنياء فليس عليك زكاة حتى تقبضي، فإذا قبضت المال استقبلت به حولاً جديداً؛ لأنهم معسرون، هذا هو التفصيل في هذه المسألة. نعم.","link":"https://binbaz.org.sa/fatwas/4330/حكم-زكاة-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_005/00504.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":7486,"question":"أيضاً السؤال الثاني للمرسلة (م. ح) يتعلق في الزكاة لكن زكاة الحلي، تقول: أسأل كذلك عن زكاة الحلي الذي اختلف فيه العلماء، والسؤال هو: إذا كانت المرأة تريد أن تزكي عن حليها كيف تزكي عنه، هل تجمع حليها وتزنه وتظهر على حسب وزنه؟ وهل يكون إذا حال عليه الحول؟ وإذا كان كذلك فإن كل شيء من حليها اشترته في زمن قد نسيت في أي شهر من السنة؟ أرشدوني كيف أزكي عن حليي؛ لأنني أريد ذلك رغم اختلاف العلماء في وجوب زكاة الحلي، وهل يصح ذلك في شهر رمضان، نظراً لأن كل نوع من هذه الحلي قد اشتري في شهر من شهور السنة؟","title":"كيفية إخراج زكاة الحلي","answer":"الجواب:  الحلي من الذهب والفضة في وجوب الزكاة عليه اختلاف بين أهل العلم كما قالت السائلة، ولكن الصواب أن فيه الزكاة، الصواب والأرجح من قولي العلماء أن في الحلي من الذهب والفضة الزكاة؛ لأنه ورد في الأحاديث الصحيحة عن رسول الله عليه الصلاة والسلام تدل على وجوب الزكاة في الحلي، من الذهب والفضة، ولو كانت تلبسه ولو كانت تعيره، هذا هو الصواب. ومن ذلك ما روى أبو داود و النسائي عن عبد الله بن عمرو بن العاص رضي الله تعالى عنهما: أن امرأة أتت النبي ﷺ وعليها سواران من ذهب، فقال: أتعطين زكاة هذا؟ قالت: لا. قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار؟ فألقتهما وقالت: هما لله ولرسوله فيه أحاديث أخرى تدل على ذلك.\nوالواجب أن تنظر في النصاب، فإذا كان يبلغ النصاب زكته كل سنة، على حسب قيمة الذهب، فإذا كان الذهب يبلغ أحد عشر جنيهاً وثلاثة أسباع جنيه يعني: حول النصف، يعني نصف جنيه تقريباً، إذا بلغ ذلك ففيه الزكاة، وما زاد فبحساب ذلك، فإذا كان عندها ذهب، يعني يقدر: بأربعين جنيه يكون فيه جنيه واحد أو قيمته، وهكذا ما زاد على ذلك، ويمكن سؤال الصاغة عن زنته؛ لأن النصاب عشرون مثقالاً، ومقدار ذلك بالجنيهات إحدى عشر جنيه وثلاثة أسباع جنيه، هذا مقدار العشرين مثقال من الذهب، فالزكاة تكون ربع العشر. أما الفضة فنصابها مائة وأربعون مثقالاً، مقداره من الذهب الفضي السعودي ستة وخمسون ريالاً فضياً، فإذا بلغ النصاب هذه الفضة أو هذا الورق بلغ ما قيمته ستة وخمسون ريال فضياً وجبت فيه الزكاة، وهكذا الذهب إذا كان عندها ذهب يبلغ أحد عشر جنيهاً وثلاثة أسباع جنيه وجبت فيه الزكاة كل سنة، ولو بلغ آلاف الجنيهات عليها أن تزكي ربع العشر من هذه الحلي؛ مثل القلائد من الذهب، أسورة أخراص.. غير ذلك، تجمع الجميع وتزكي عن الجميع ربع العشر، إذا كان يبلغ مثلاً مائة ألف ريال تزكي هذا المبلغ ألفين ونصف ربع العشر عن هذا الذهب الذي عندها.\nأما الماس واللؤلؤ والعقيق هذا لا زكاة فيه، إذا كان في حليها ماس أو عقيق أو شبه ذلك من اللآلي، هذا لا زكاة فيه، إنما الزكاة في الذهب خاصة، إذا كانت هذه الأمور لم تعد للتجارة، كاللؤلؤ ونحوه والماس إنما أعد للبس، هذا ليس فيه زكاة، وإنما الزكاة في الذهب خاصة والفضة عند أهل العلم، كما جاءت به الأخبار عن النبي عليه الصلاة والسلام.\nوالواجب ربع العشير في الذهب الموجود عندها كل سنة، ولا عبرة بأثمانها السابقة، العبرة بالقيمة وقت الزكاة ما يساوي هذا الذهب وقت الزكاة، في رمضان أو في غير رمضان. نعم.\nالمقدم: لكن سماحة الشيخ! الزكاة على الذهب والفضة إذا كانت حلياً هل يلزم أن تبلغ الذهب مثلاً إحدى عشر جنيه وثلاثة أسباع؟\nالشيخ: اللي أقل ما فيه شيء، نعم.\nالمقدم: اللي أقل ما فيه شيء، والفضة خمس أواق؟\nالشيخ: مائة وأربعين مثقالاً.\nالمقدم: إذا نقص وهو حلي فليس عليه شيء؟\nالشيخ: لا، ما كان أقل من هذا فليس فيه زكاة. نعم.","link":"https://binbaz.org.sa/fatwas/4331/كيفية-اخراج-زكاة-الحلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_005/00505.mp3","categories":["إخراج الزكاة وأهلها","زكاة النقدين"]},{"id":7578,"question":"يقول أيضاً عيسى بن علي بن المعتوق من الكويت: لي خمسة دنانير في البنك، وقد مر عليها الحول ولم أستفد منها، فهل عليها زكاة، علماً أن خمسة دنانير حوالي أربعين ريال سعودي؟","title":"لا زكاة فيما دون النصاب","answer":"الجواب: إذا كان عندك دراهم تكمل النصاب فعليك الزكاة إذا تم الحول، أما إذا كان ما عندك إلا هذه الدنانير فإنها ليس فيها زكاة؛ لأنها لا تبلغ النصاب، فإذا كان عندك دنانير تم عليها الحول تضم إلى هذه فلا بأس، إذا كان الجميع نصاباً وتم على الجميع الحول فإنك تزكي الجميع، أما إذا كان الذي عندك هذه الدنانير فقط الأربعة فإنها لا تبلغ النصاب فلا زكاة فيها. نعم.","link":"https://binbaz.org.sa/fatwas/4584/لا-زكاة-فيما-دون-النصاب ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_018/01802.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":7579,"question":"سؤاله الأخير يقول: كم مقدار المال الذي يجب عليه الزكاة وفقكم الله؟","title":"مقدار النصاب الذي تجب فيه زكاة المال","answer":"الجواب: النصاب الذي تجب فيه الزكاة من الذهب عشرون مثقالاً، أو ما يقوم مقامه من الدنانير الكويتية وغيرها، ومن الفضة مائة وأربعون مثقالا، ومقدار ذلك بالجنيه السعودي والفرنجي أحد عشر جنيه وثلاثة أسباع جنيه؛ لأن الجنيه مثقالان إلا ربع، والنصاب عشرون مثقالاً، فإذا كان عند الإنسان أحد عشر جنيهاً وثلاثة أسباع جنيه من الذهب فإنه تجب فيه الزكاة إذا حال عليه الحول، سواءً كان جنيهات بنفسها، أو كانت حلياً، أو كانت قطعاً غير مسبوكة، أو كان عنده ما يقابلها من العمل الورقية فإنه يزكي ذلك إذا حال عليها الحول، وهكذا الفضة إذا كان عنده منها ما يقابل مائة وأربعين مثقالاً، ومقدار ذلك ستة وخمسون ريال فضة من الدرهم السعودي، أو ما يقابل ذلك من العملة الورقية بحسب القيمة في الأسواق، فهذا هو الذي تجب فيه الزكاة، وما كان أقل من ذلك فإنه لا زكاة فيه.","link":"https://binbaz.org.sa/fatwas/4585/مقدار-النصاب-الذي-تجب-فيه-زكاة-المال ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_018/01803.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":7600,"question":"الرسالة هذه من سوريا من بلدة حمص وأرسلتها المستمعة فاطمة قرة يوسف تقول في رسالتها فاطمة: توفيت جدتي وكان عندها خمسة آلاف ليرة من المال وقد جمعتهم من الناس الذين يأتون عليها قبل وفاتها ويقدمون لها الزكاة؛ لأنهم كانوا يحسبون أنها محتاجة، وأنا أعلم بأن من ملك نصاب الزكاة لا يجوز أن يأخذ زكاة نهائياً، ولكن كان الذي معها أكثر من النصاب بكثير وكانت تأخذ الزكاة من الناس وبعدها توفيت، وأرادوا أولادها الوراثة، فهل يجوز أن يأخذوا هذا المال وهي كانت تأخذه حرام؛ لأنها مالكة النصاب، أفيدونا جزاكم الله خيراً؟","title":"حكم أخذ من يملك نصاب الزكاة زكاة غيره","answer":"الجواب: مثل هذه المرأة التي عندها خمسة آلاف ليرة هذه لا تعد غنية بل هذا قد لا يكفيها لسنتها يعني لو استمرت تنفق منه، وليس من ملك نصاباً من الزكاة يكون غنياً على الصحيح يكون غناه غنى وجوب الزكاة عليه، إذا ملك النصاب صار غنياً بالنسبة إلى وجوب الزكاة عليه، ولكن ليس غنياً بالنسبة إلى منعه من الزكاة، فالغنى قسمان: \n- عنى يوجب الزكاة ولكنه لا يحصل به الغنى عن الحاجة ولا يسد باب الحاجة. \n- والغنى الثاني: غنى يسد الحاجة ويغني عن الحاجة إلى الناس ويحصل به المقصود. \nفالذي يمنع الزكاة هو الثاني هو الغنى الذي لا يحتاج معه صاحبه إلى الدين ولا إلى سؤال الناس بل يكفيه ويكفي عائلته إذا كان له عائلة، هذا الغنى يمنع الزكاة ولا يعطى صاحبه، أما إذا كان عنده مال قليل يزكيه ولو أنفقه لأكله بسرعة فهو يزكيه لوجوده عنده كرأس مال يحفظه ويزكيه ولكنه لو أكله لذهب بسرعة، فلا بأس أن يعطى من الزكاة ما يسد حاجته ويغنيه عن الطواف على الناس، هذا هو الصواب: أن الغنى الذي يمنع الزكاة هو الغنى الذي تحصل به الكفاية لا الغنى الذي يحصل به الزكاة، فينبغي الفرق، يعني فهم الفرق بينهما، هذا هو الصواب، وقول بعض العلماء: من ملك النصاب تجب فيه الزكاة فهو غني لا يعطى. قول ضعيف مرجوح. نعم.","link":"https://binbaz.org.sa/fatwas/4653/حكم-اخذ-من-يملك-نصاب-الزكاة-زكاة-غيره ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_020/02008.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":7720,"question":"هذه الرسالة أو هذا المؤلف وردنا من المستمع مصلح بن عبد المعين الخرماني الحربي من وادي قديد البريكة، وقد جمع فيه ما يزيد على سبعين سؤال في ثمانية وعشرين صفحة.ونقول للأخ مصلح نحن نعتذر عن الإجابة على جميع هذه الأسئلة؛ لأنها تريد وقتاً طويلاً، وهي سوف تأتي من المستمعين، فعليك يا أخ بمتابعة البرنامج وستحصل على الإجابة عنها إن شاء الله تعالى، خصوصاً والمستمع يرجو إرسالها في البريد أيضاً.ومن أسئلة المستمع مصلح ، يقول: هل يجوز لشخص لا تحل له الزكاة أن يأخذها؟","title":"حكم أخذ الزكاة لمن لا تحل له","answer":"الجواب: إذا كان الرجل لا تحل له الزكاة يحرم عليه أخذها، ولو أراد أن يعطيها غيره، ليس له أخذها إلا بإذن صاحبها، إذا قال: أنا أريد أن أعطيها ناس فقراء، يوكله في ذلك، هذا من باب التوكيل، أما أنه يأخذها على أنه فقير ولكن في نيته أن يعطيها غيره فلا، الواجب عليه أنه لا يأخذها إلا إذا كان أهلاً لها، إلا إذا كان من باب الوكالة ليدفعها إلى أناس فقراء فليصرح لصاحب الزكاة بذلك وليخبره بذلك؛ حتى يوكله أو لا يوكله. نعم.","link":"https://binbaz.org.sa/fatwas/4919/حكم-اخذ-الزكاة-لمن-لا-تحل-له ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_031/03106.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":7977,"question":"نبدأ أولاً: برسالة محمد جاسم محمد ، من العراق بغداد حيث يقول فيها: أنا موظف وعندي راتب شهري، فهل علي زكاة، أي: هل على الراتب الشهري زكاة، وما مقدارها مع العلم أن راتبي حوالي مائة دينار عراقي، وفقكم الله؟","title":"حكم زكاة المال الموفر من الراتب الشهري","answer":"الشيخ: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: لا شك أن في الرواتب زكاة إذا حال عليها الحول، راتب الإنسان من الدنانير أو الدولارات أو الدراهم أو الجنيهات كل أنواع العمل فيها الزكاة إذا حال عليها الحول، فإذا حال على راتبك -أيها السائل- إذا جمعت منه مالاً وحال عليه الحول فإنه تجب فيه الزكاة ربع العشر، من كل أربعين دينار دينار واحد ربع العشر، أما إذا كنت تنفق راتبك في وقته ولا يبقى عندك شيء منه فليس عليك زكاة، إنما الزكاة فيما حال عليه الحول، إذا اجتمع من راتبك شيء يبلغ النصاب وحال عليه الحول فإنه يجب عليك الزكاة، أما إذا كنت لا تبقي شيئاً منه بل تنفقه في وقته فلا زكاة في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/5525/حكم-زكاة-المال-الموفر-من-الراتب-الشهري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_072/07201.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":7985,"question":"نبدأ أولاً: برسالة محمد جاسم محمد ، من العراق بغداد حيث يقول فيها: أنا موظف وعندي راتب شهري، فهل علي زكاة، أي: هل على الراتب الشهري زكاة، وما مقدارها مع العلم أن راتبي حوالي مائة دينار عراقي، وفقكم الله؟","title":"حكم زكاة المال الموفر من الراتب الشهري","answer":"الشيخ: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: لا شك أن في الرواتب زكاة إذا حال عليها الحول، راتب الإنسان من الدنانير أو الدولارات أو الدراهم أو الجنيهات كل أنواع العمل فيها الزكاة إذا حال عليها الحول، فإذا حال على راتبك -أيها السائل- إذا جمعت منه مالاً وحال عليه الحول فإنه تجب فيه الزكاة ربع العشر، من كل أربعين دينار دينار واحد ربع العشر، أما إذا كنت تنفق راتبك في وقته ولا يبقى عندك شيء منه فليس عليك زكاة، إنما الزكاة فيما حال عليه الحول، إذا اجتمع من راتبك شيء يبلغ النصاب وحال عليه الحول فإنه يجب عليك الزكاة، أما إذا كنت لا تبقي شيئاً منه بل تنفقه في وقته فلا زكاة في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/5525/حكم-زكاة-المال-الموفر-من-الراتب-الشهري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_072/07201.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8041,"question":"السؤال أيضاً يقول: بالنسبة لزكاة المال، إذا توفر معي بعض مصاريفي ومصاريف الأولاد خمسة آلاف ريال لمدة سنة، فهل علي زكاة علماً بأنني مقيم في الأحساء للعمل؟","title":"حكم الزكاة في المال الذي بلغ النصاب وحال عليه الحول","answer":"الجواب: نعم إذا توفر لديك ما يبلغ النصاب، وحال عليه الحول وجبت عليه الزكاة، والخمسة الآلاف لا شك أنها نصاب بل أنصب، فعليك أن تخرج زكاتها إذا حال عليها الحول، وهي ربع العشر. نعم.","link":"https://binbaz.org.sa/fatwas/5668/حكم-الزكاة-في-المال-الذي-بلغ-النصاب-وحال-عليه-الحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_081/08104.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8054,"question":"سؤالها الثاني تقول: هل يجوز استعمال شيء من أموال الزكاة في شراء ذهب وغيره أم لا؟","title":"حكم شراء المرأة الفقيرة للذهب من أموال الزكاة","answer":"الجواب: إذا كانت المرأة فقيرة، وأعطيت من الزكاة شيئاً من المال، وأحبت أن تشتري منه سلعةً تلبسها من الذهب والفضة، فلا حرج في ذلك؛ لأن هذا من الأمور العادية، مثل ما تلبس الملابس الجميلة في المناسبات، وإن كانت من أهل الزكاة، فلا حرج عليها أن تشتري من مال الزكاة الذي دفع إليها، حاجتها من الملابس الذهبية وغيرها. نعم.","link":"https://binbaz.org.sa/fatwas/5849/حكم-شراء-المراة-الفقيرة-للذهب-من-اموال-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_082/08202.mp3","categories":["إخراج الزكاة وأهلها","البيوع","قضايا المرأة"]},{"id":8135,"question":"هذه رسالة وردتنا من الرياض من المستمع (ن. ن. ش) يقول في رسالته: هل يجوز إعطاء وكالة من شخص لآخر؛ ليدير أعماله في فترة غيابه، والذي عرفنا أنه لا يجوز التوكل إلا على الله وحده؟","title":"الفرق بين التوكل والوكالة","answer":"الجواب: الوكالة غير التوكل أيها السائل. الوكالة كونه يستنيب إنسان يقوم مقامه في إدارة عمله، في بناء بيته، في إصلاح سيارته، في غير ذلك، هذا لا بأس به، وكالة تفويض منه إذن له، يأذن له يفعل كذا وكذا، أما التوكل هو الاعتماد على الغير بأنه يتصرف في الأمور بقدرته، فالله هو الذي يعتمد عليه ويتوكل عليه سبحانه وتعالى، فالتوكل يكون على الله، وأعظم التوكل أن يعتمد عليه بأنه قادر على كل شيء. لأنه مسبب الأسباب، فالاعتماد على الله والتوكل عليه سبحانه وتعالى، ثم الإنسان مع ذلك يفعل الأسباب، يعتمد على الله يعلم أنه مصرف الأمور، ومسبب الأسباب، وأنه ما شاء الله كان وما لم يشأ لم يكن، ولا يعتمد على المخلوق ولا على نفسه، بل يعتمد على الله وحده، ويتوكل عليه، ومع هذا يأخذ بالأسباب، ويتعاطى الأسباب، فيزرع الأرض، يغرس الغرس، يبني ما يحتاج إليه، يوكل من يحتاج إليه حتى ينوب عنه في الغراس، في الزراعة، في البناء ليس في هذا بأس، فالوكالة شيء، والتوكل شيئاً آخر، أما كونه يتوكل على إنسان، يعني: يعتقد فيه أنه يتصرف في الكون، وأنه يدبر الأمور، وأنه له القدرة على التصرفات بدون مشيئة الله أو ما أشبه ذلك هذا لا يجوز مع المخلوق أبداً، التوكل على الله وحده سبحانه وتعالى.","link":"https://binbaz.org.sa/fatwas/5929/الفرق-بين-التوكل-والوكالة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_088/08802.mp3","categories":["إخراج الزكاة وأهلها","الوكالة"]},{"id":8138,"question":"أخونا يقول: ما هو نصاب الزكاة بالنسبة للعملة العراقية الدينار؟ وهل تجب الزكاة على الشخص الذي تدفع له الزكاة في نفس الوقت؟","title":"نصاب زكاة المال وحكم أخذ الزكاة ممن تدفع له","answer":"الجواب: أما النصاب فقد وضحه النبي ﷺ، فالذهب نصابه عشرون مثقالاً، ومقدار ذلك بالغرام اثنان وتسعون غرام، وبالجنيه السعودي والفرنجي إحدى عشر جنيه وثلاثة أسباع الجنيه، يعني: إحدى عشر ونصف، الكسر اليسير لا يضر، إحدى عشر جنيه وثلاثة أسباع هي إحدى عشر جنيه ونصف؛ لأنه أوضح للحاسب، فهذا هو النصاب بالنسبة إلى الذهب، وبالفضة نصابها مائة وأربعون مثقالاً من الفضة، فما يقوم مقام ذلك من الدولار الأمريكي أو الدينار العراقي أو غير ذلك ما يقوم مقام هذا ويساوي هذا هو النصاب، ما يساوي مثلاً مائة وأربعين مثقال من الفضة أو يساوي إحدى عشر جنيه من الذهب إحدى عشر ونصف من الذهب هذا يسمى نصاباً، ويجب فيه ربع العشر في المائة اثنان ونصف، في المائتين خمسة، في الألف خمسة وعشرون ربع العشر، وإذا أحب أن يزكي ما عنده ولا ينظر إلى النصاب فالأمر في هذا واسع؛ لأن النصاب قليل، يعني: أقل نصاب هو شيء قليل، فإذا كان عند الإنسان أموال زكاها؛ لأن النصاب قليل جداً مقدار عشرين مثقال من الذهب أو مائة وأربعين مثقال من الفضة مقدارها ستة وخمسين ريال من السعودي، ستة وخمسون ريالاً من الفضة من العملة السعودية وهذا شيء قليل فلا يحتاج الإنسان إلى التكلف من جهة النصاب يزكي ما عنده والحمد لله؛ لأنه في الغالب قد بلغ النصاب، ويا أهل المئات والألوف قد بلغ النصاب عندكم، إنما قد يشتبه على أهل الدنانير القليلة، إذا كان عندهم شيء قليل فهؤلاء ينظرون في قيمتها بالنسبة إلى الجنيه الفرنجي والسعودي المعروف بالنسبة إلى عشرين مثقال من الذهب ماذا تساوي، فإذا كان ما عنده يساوي عشرين مثقال من الذهب وجب فيه الزكاة.\nأو يساوي مائة وأربعين مثقال من الفضة وجب فيه الزكاة، ويعرفون هذا بالنظر إلى أهل الذهب والفضة إذا راجعوهم أهل الذهب والفضة -الصيارفة- إذا راجعوه وسألوه عن قيمة عشرين مثقال من الذهب عن قيمة مائة وأربعين مثقال من الفضة عرفوا ذلك، ولا حاجة إلى التكلف إذا زكى ما عنده فالحمد لله. نعم.\nالمقدم: بارك الله فيكم، إذاً: لو قيل أيضاً لأخينا هذا عليه أن يزكي ربع العشر دائماً؟\nالشيخ: يكفي ولا يحتاج تكلف يسأل. نعم.\nالمقدم: بارك الله فيكم، الرسالة التالية باعثها أحد الإخوة يقول سعيد يوسف محمود .. ؟\nالشيخ: بقي في سؤاله هل يعطى له الزكاة؟\nالمقدم: أيوه عفواً نعم.\nالشيخ: نعم، إذا كان عليه زكاة وهو فقير يعطى إذا كان مثلاً إنسان عنده ألف دينار قلنا: عليك خمسة وعشرون زكاة، ربع العشر، ولكن هذا الألف الذي يتسبب فيه، يعمل فيه ما يكفيه عنده عائلة ما يكفيه هذا لو صرف هذا المال ما بقي عنده شيء، فهو يعمل في هذا المال في حاجات في بيع وشراء في سلع، فهو يعطى من الزكاة ما يقوم بحاله وتبقى هذه الجنيهات التي عنده أو الدولارات التي عنده يتسبب فيها حتى يستعين بها على حاجات البيت، فيعطى لأنه فقير ويزكي ما عنده من هذا المال الذي بلغ النصاب، فعنده ألف دينار مثلاً يزكيه خمسة وعشرين كل سنة إذا كان في حاجات يبيعها في الدكان أو في مبسط بقالة أو شيء يزكي هذا الشيء ويعطى من الزكاة ما يكمل حاجته؛ لأنها ربح الألف الدينار أو ألف الدولار أو ألف جنيه إسترليني أو نحوه ربحها وما يحصل فيها قد لا يقوم بحاله ولا يكفيه في حاجات البيت فيعطى من الزكاة ما يسد حاجته ولا يقال: عليك أن تنفق هذا وتبقى معطلاً، لا، يتجر في هذا ويتسبب في هذا المال الذي بيديه حتى يستعين بربحه في حاجات البيت ويعطى من الزكاة ما يقوم بحاله، وهكذا لو كان عنده قلنا: مثلاً مائة دينار وزكى منها اثنين ونص، المائة الباقية ما تساوي شيء بالنسبة إلى حاجته فيعطى ما يسد حاجته من إخوانه من زكاة إخوانه المسلمين ولا بأس هذا، هو الذي عليه جمهور أهل العلم.\nنعم، ذهب بعض أهل العلم إلى أن من زكى لا يعطى، وهذا قول ضعيف، الصواب: أنه يعطى إذا كان فقيراً ولو وجبت عليه الزكاة في مال عنده. نعم.\nالمقدم: بارك الله فيكم، نؤجل رسالة أخينا سعيد يوسف محمود من بيشة سبت العلايا إلى الحلقة القادمة إن شاء الله تعالى.\nسماحة الشيخ في ختام هذا اللقاء أتوجه لكم بالشكر الجزيل بعد الله سبحانه على تفضلكم بإجابة السادة المستمعين وآمل أن يتجدد اللقاء وأنتم على خير وعافية.\nالشيخ: إن شاء الله.","link":"https://binbaz.org.sa/fatwas/5933/نصاب-زكاة-المال-وحكم-اخذ-الزكاة-ممن-تدفع-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_103/10307.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8210,"question":"أخذت من شخص قطعة أرض لكي أزرعها، واشترط علي أن أعطيه الزكاة، سواء كان فقيراً أم غنياً، فقد أعطيته، فهل أديت الواجب علي وهذه الحالة أم لا؟","title":"حكم اشتراط دفع زكاة العين المؤجرة للمؤجر","answer":"الجواب: هذا العقد باطل، لا يجوز أن تستأجر الأرض بشرط أنك تعطيه الزكاة، هذا لا يجوز، تتفق معه على الأجرة التي ترضاها ويرضاها ويكفي، أما شرط الزكاة فلا، ولو كان فقيراً ما يصير شرط الزكاة له ؛ لأن الفقراء كثيرون، وهذه إجارة، معاملة ما تكون بالزكاة تقوم بأجور أخرى، وإذا كان فقيراً فلك أن تعطيه بغير شرط، لك أن تعطيه من الزكاة إذا أردت ذلك من دون شرط ولا يلزم، بل لك أن تعطي غيره من الفقراء، المقصود: لا يجوز شرطها في الأجرة أبداً لا قليلاً ولا كثيراً، بل يجب أن تكون الأجرة من غير الزكاة متفقاً عليها بينكما، أما كونك تعطيه من الزكاة أم لا هذا شيء آخر، لك أن تعطيه إذا كان من أهلها، ولك أن تحرمه وتعطي غيره، ليس عليك جناح في هذا، ولا يجوز أن تربط بالإجارة من كل الوجوه. نعم.","link":"https://binbaz.org.sa/fatwas/6024/حكم-اشتراط-دفع-زكاة-العين-الموجرة-للموجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_095/09510.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8231,"question":"أموال الناس التي في ذمتي ومضى عليها أكثر من سنتين، وهل تجب الزكاة فيها علي أو على أهلها؟","title":"حكم زكاة المال المقترض","answer":"الجواب: أموال الناس التي عليك ليس عليك زكاتها، إلا إذا كانت عندك موجودة في قبضتك وفي حوزتك، فهذه أموالك ليست أموالهم، أموالهم في الذمة، أما ما كان في حوزتك من النقود أو عروض التجارة ولو أنها جاءتك بالسلف أو بالاستدانة عليك أن تزكيها إذا حال عليها الحول.\nأما الديون التي في ذمتك للناس فهذه زكاتها عليهم إن كنت موسراً وباذلاً، وإن كنت معسراً أو مماطلاً فلا زكاة عليهم كما تقدم.","link":"https://binbaz.org.sa/fatwas/6053/حكم-زكاة-المال-المقترض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_097/09713.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8235,"question":"أموالي الموضوعة في البنوك؟","title":"حكم الزكاة عن الأموال التي في البنوك","answer":"الجواب: فيها الزكاة، المال الذي في البنك فيه الزكاة، وليس لك أن تعامل بالربا، لكن مالك الذي وضعته في البنك كالأمانة عليك أن تزكيه؛ لأنك متى طلبته أخذته. نعم.","link":"https://binbaz.org.sa/fatwas/6054/حكم-الزكاة-عن-الاموال-التي-في-البنوك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_097/09714.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8237,"question":"زكاة الأموال المتفرقة كالعمائر والأراضي والدكاكين ونحوها؟","title":"كيفية إخراج زكاة الأموال المتفرقة كالعمائر وغيرها","answer":"الجواب: هذه فيها تفصيل: إن كانت معدة للتجارة فعليك زكاتها، كل حول حسب القيمة غلاء ورخصاً، إن غلت تزكها غالية، وإن رخصت زكها رخيصة على حسب قيمتها عند تمام الحول إذا كانت للبيع.. للتجارة، أما إن كانت للسكن أو للتأجير لا للتجارة والبيع بل للسكن أو للتأجير أو عندك تردد لم تجزم بشيء فلا زكاة فيها، ولكن إذا كانت للتأجير تزكي الأجرة إذا حال عليها الحول. نعم.","link":"https://binbaz.org.sa/fatwas/6055/كيفية-اخراج-زكاة-الاموال-المتفرقة-كالعماىر-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_097/09715.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8239,"question":"أموالي الموضوعة في البنوك؟","title":"حكم الزكاة عن الأموال التي في البنوك","answer":"الجواب: فيها الزكاة، المال الذي في البنك فيه الزكاة، وليس لك أن تعامل بالربا، لكن مالك الذي وضعته في البنك كالأمانة عليك أن تزكيه؛ لأنك متى طلبته أخذته. نعم.","link":"https://binbaz.org.sa/fatwas/6054/حكم-الزكاة-عن-الاموال-التي-في-البنوك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_097/09714.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8241,"question":"زكاة الأموال المتفرقة كالعمائر والأراضي والدكاكين ونحوها؟","title":"كيفية إخراج زكاة الأموال المتفرقة كالعمائر وغيرها","answer":"الجواب: هذه فيها تفصيل: إن كانت معدة للتجارة فعليك زكاتها، كل حول حسب القيمة غلاء ورخصاً، إن غلت تزكها غالية، وإن رخصت زكها رخيصة على حسب قيمتها عند تمام الحول إذا كانت للبيع.. للتجارة، أما إن كانت للسكن أو للتأجير لا للتجارة والبيع بل للسكن أو للتأجير أو عندك تردد لم تجزم بشيء فلا زكاة فيها، ولكن إذا كانت للتأجير تزكي الأجرة إذا حال عليها الحول. نعم.","link":"https://binbaz.org.sa/fatwas/6055/كيفية-اخراج-زكاة-الاموال-المتفرقة-كالعماىر-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_097/09715.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8257,"question":"أخ مصري اسمه أحمد عبد الشكور يقول: أرسلت زكاة الفطر الخاصة بي إلى أهلي لكي يخرجوها في البلد، فهل هذا العمل صحيح؟","title":"حكم إخراج الزكاة في غير بلد المزكي","answer":"الجواب: لا بأس، تجزئ إن شاء الله، ولكن إخراجها في محلك أفضل، كونك تخرجها في محلك يعني الذي أنت مقيم فيه لبعض الفقراء يكون أولى، وإذا بعثتها إلى أهلك ليخرجوها على الفقراء فلا بأس. نعم.","link":"https://binbaz.org.sa/fatwas/6068/حكم-اخراج-الزكاة-في-غير-بلد-المزكي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_098/09808.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8384,"question":"الرسالة التالية رسالة وصلت من جمهورية مصر العربية، السويس، وباعثها أخونا أحمد عبد الله، أخونا يقول: أنا موظف أعمل في إحدى الشركات، والشركة التي أعمل بها بعثت بي إلى الخارج للدراسة، وفي أثناء تواجدي في الخارج للدراسة، كانت الشركة تضع لي مرتبي الشهري وعلاواتي في البنك، وقد مضى عليها سنتان، وهي تتجمع في البنك، ولم آخذ منها إلا مبالغ قليلة أثناء تواجدي في بلدي، ثم أسافر لأكمل دراستي، والسؤال هنا: هل علي زكاة في هذا المال؟ علماً بأنني لا أدخره للتجارة، أو نحو ذلك، بل إنني أجمعه حتى تنتهي دراستي وأعود إلى بلادي نهائياً لكي أتزوج منه، وأبني أسرتي؟ وإن كانت هناك زكاة، فما هو المقدار فيها؟","title":"حكم زكاة الأموال التي تجمع للزواج وغيرها","answer":"الجواب: لا ريب أن الأموال التي يجمعها المؤمن إما لزواج، وإما لتعمير سكن، وإما لغير هذا، تجب فيها الزكاة؛ لأن الله جل وعلا أوجب الزكاة في النقدين، وما يقوم مقامهما من العمل، وهكذا أوجب الزكاة في بهيمة الأنعام السائمة، من الإبل والبقر والغنم، وأوجب الزكاة أيضاً في عروض التجارة المعدة للبيع، وأوجب الزكاة في الحبوب والثمار إذا بلغت النصاب.\nفهذه الأموال التي تحفظ في البنك وتودع في البنوك، ليستنفع بها صاحبها في قضاء دين، أو ليستنفع بها في زواج، أو في تعمير سكن، أو في غير ذلك، كلها تجب فيها الزكاة، ولا نعلم خلافاً بين أهل العلم في ذلك، إذا بلغت النصاب وحال عليها الحول، والواجب ربع العشر، في كل مائة اثنان ونصف، في الألف خمسة وعشرون، هذا هو الواجب عند جميع أهل العلم، ربع العشر، كما بينه النبي عليه الصلاة والسلام، قال: في كل مائتين خمسة دراهم هكذا قال عليه الصلاة والسلام. نعم.","link":"https://binbaz.org.sa/fatwas/6235/حكم-زكاة-الاموال-التي-تجمع-للزواج-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_116/11603.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8398,"question":"رسالة من أحد الإخوة المستمعين يقول: لي دين عند أحد الإخوة، هل تلزمني زكاته أو أن هناك وقتاً محدداً؟","title":"تفصيل أحوال زكاة الدين","answer":"الجواب: إذا كان الدين الذي لك على موسرين باذلين، متى طلبته أعطوك حقك فعليك أن تزكيه كلما حال الحول، كأنه عندك، كأنه عندهم أمانة، أو كأنه في صندوق عليك أن تزكيه.\nأما إن كان من عليه الدين معسراً، لا يستطيع أداءه لك، أو كان غير معسر لكنه يماطلك ولا تستطيع أخذه منه، فالصحيح من أقوال العلماء: أنه لا يلزمك أداء الزكاة حتى تقبضه منه، من هذا المماطل أو من هذا المعسر، فإذا قبضته استقبلت به حولاً وأديت الزكاة بعد تمام الحول من قبضك له، وإن أديت الزكاة عن سنة واحدة من السنوات السابقة التي عند المعسر أو المماطل فلا بأس، قال هذا بعض أهل العلم، ولكن لا يلزمك إلا في المستقبل، متى قبضت المال من المعسر أو المماطل واستقبلت به حولاً ودار عليه الحول تلزمك الزكاة، هذا هو المختار. نعم.","link":"https://binbaz.org.sa/fatwas/6264/تفصيل-احوال-زكاة-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_117/11703.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8399,"question":"أنا بعت ذهباً قديماً ولم أزكه من قبل، فأرجو أن توضحوا لنا كيف تكون زكاته؟ وإذا بعت بأربعة آلاف ريال فهل أدفع الزكاة من هذا المبلغ؟","title":"حكم من باع ذهباً ولم يزكه","answer":"الجواب: إذا كنت لم تعلمي وجوب الزكاة إلا بعد ذلك فلا شيء عليك، وإن كنت تعلمين ذلك فزكي هذه الأربعة، من كل ألف خمسة وعشرون عن السنة الواحدة، عن كل ألف خمسة وعشرون ربع العشر، وهكذا السنوات التي قبلها بحسب قيمة الذهب في السوق، الواجب ربع العشر تؤدي هذه الزكاة من العملة المعروفة.\nأما إذا كنت لا تعلمين ذلك إلا في السنة الأخيرة، فعليك الزكاة عن السنة الأخيرة من كل ألف خمسة وعشرون. نعم.","link":"https://binbaz.org.sa/fatwas/6269/حكم-من-باع-ذهبا-ولم-يزكه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_117/11704.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8407,"question":"هل يصح أن يحتفظ بالزكاة من أجل إعطائها لأحد الفقراء الذين لم أتصل بهم بعد؟","title":"حكم تأجيل زكاة الأموال والأبدان لفقراء معينين","answer":"الجواب: إذا كانت المدة يسيرة غير طويلة فلا بأس، سيحتفظ بالزكاة حتى يعطيها بعض الفقراء من أقاربه، أو من هو أشد فقراً وحاجة، لكن لا تكون مدة طويلة، ...... أيام غير كثيرة. نعم.\nالمقدم: طيب وسواء في ذلك زكاة الأموال أو الأبدان سماحة الشيخ؟\nالشيخ: نعم نعم، لكن زكاة البدن لا، تقدم على العيد، زكاة البدن يجب تقديمها على صلاة العيد كما أمر النبي صلى الله عليه وسلم، وتخرج قبل العيد بيومين أو ثلاث لا بأس. نعم.\nالمقدم: لكن إذاً هي لا تؤجل؟\nالشيخ: لا تؤجل بعد العيد لا.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6291/حكم-تاجيل-زكاة-الاموال-والابدان-لفقراء-معينين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_117/11713.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8408,"question":"هل يصح إعطاء الزكاة لذمي؟","title":"حكم إعطاء الذميين من الزكاة","answer":"الجواب: الزكاة على قول الجمهور: لا تعطى للذميين الكفرة، وهو الصواب، الزكاة مواساة للمسلمين، وعناية بسد حاجتهم وفقرهم، فيجب أن توزع على المسلمين؛ لسد حاجتهم وفقرهم. نعم.","link":"https://binbaz.org.sa/fatwas/6292/حكم-اعطاء-الذميين-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_117/11714.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8749,"question":"هذه رسالة وردتنا من السائل (أ. م. س) من الرياض يقول في رسالته: أنا شاب موظف لي دخل شهري محدود آخذ منه ما أحتاجه والباقي أضعه في البنك حتى يتكون لدي مبلغ أشتري به أرض أقيم عليها مسكناً أسكنه عندما أتزوج، وفعلاً تكون لدي مبلغ خمسة وخمسون ألف ريال وكانت قيمة الأرض مائة وخمسة آلاف فاستلفت المبلغ الباقي، وبعد سنة من شراء الأرض كنت قد سددت المبلغ المطلوب، ولكن بعد أيام فكرت في بيع الأرض لأشتري في موقع أقرب من الأول وفعلاً بعتها ووضعت المبلغ في البنك، وصرت أجمع على ثمن هذه الأرض التي بعتها من رواتبي إلى أن يظهر اسمي من صندوق التنمية العقاري والآن لي سنة ف هل علي زكاة في هذه السنوات الثلاث؛ لأنني سمعت أن من يجمع المال حتى يتزوج أو يبني مسكناً يسكنه لا زكاة عليه؟","title":"حكم زكاة المال المجموع لغرض زواج أو بناء بيت","answer":"الجواب: هذا غلط الصواب أن عليه زكاة، إذا جمع مالاًَ ليتزوج أو ليبني مسكناً أو ليوفي ديناً فالزكاة عليه إذا حال الحول على المال المجموع، فإذا جمعت من رواتبك أو ثمن الأرض التي بعتها ورصدتها في البنك أو في غير البنك تنتظر التعمير أو تنتظر شراء أرض أخرى أو تنتظر الزواج أو ما أشبه ذلك؛ فإن عليك الزكاة إذا حال الحول، كل مال حال عليه الحول من النقود فإنه يجب عليك زكاته سواء كان من الرواتب أو ثمن أرض أو ثمن بيت أو غير ذلك، ولو كنت أعددت هذا المال لشراء أرض أو لعمارة أرض أو للزواج أو لغير ذلك، عليك الزكاة إذا حال الحول عن كل مال حال عليه الحول. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6909/حكم-زكاة-المال-المجموع-لغرض-زواج-او-بناء-بيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_217/21706.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8755,"question":"الأخ (ع. ش) من الرياض يسأل أيضاً ويقول: هل الزكاة على قيمة الأسهم بتمام الحول، أم على الخمسة عشر بالمائة التي توزع من الأرباح، في مثل: شركات الغاز والكهرباء، أم أن الزكاة فقط على الخمسة عشر بالمائة إذا حال عليها الحول؟ وإذا كان هناك بيت يؤجر فهل الزكاة على قيمة البيت وإيجاره أم على الإيجار فقط أفيدونا أفادكم الله؟","title":"حكم زكاة أسهم الشركات وإيجار البيوت","answer":"الجواب: الشركات التي يقصد منها الاستثمار لا البيع مثل: شركات الكهرباء وأشباه ذلك، هذه الزكاة فيما يحصل من المال ما يقسم من المال والأرباح التي يعطاها المساهمون هي التي فيها الزكاة إذا حال عليها الحول بعد حصولها وملك رجل لها، فإذا ملكها وحال عليها الحول يزكيها.\nأما الأصل وهو السهام التي في الشركة فليس عليها زكاة؛ لأنها شركة استثمارية يراد منها الربح لا يراد بيع أصولها، بخلاف الأراضي التي يشترك فيها للبيع، فإن المراد منها بيع أصولها والفائدة من أرباحها، فهذا يزكي الأصل والربح جميعاً في الأرض التي يراد بيعها والسيارة التي يراد بيعها وهكذا العمارة وما أشبه ذلك.\nأما الشركات التي يقصد منها الاستثمار والأصول باقية، فهذه الزكاة فيما يحصل من الثمرة من الفلوس التي تحصل أرباحاً، فتزكى من حين اجتمعت وحصلت لأهلها تزكى إذا حال عليها الحول. نعم.\nالمقدم: وبالنسبة للبيت؟\nالشيخ: والبيت كذلك يزكى الأجرة أما الأصل فلا يزكى إذا كان للاستئجار لا للبيع وإنما هو معد للإيجار ليؤجره وينتفع بالأجرة فالزكاة في الأجرة إذا حال عليها الحول، أما لو أنفقها ولم يحل عليها الحول فلا زكاة فيها أو قضى بها ديناً أو نحو ذلك لا زكاة فيها إلا إذا حال عليها الحول بعد عقد الإجارة تم عليها سنة بعد تمام العقد. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6906/حكم-زكاة-اسهم-الشركات-وايجار-البيوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_217/21704.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":8938,"question":"أخونا عبدالعزيز السديس يقول: ساهمت بمبلغ في مساهمة عقارية ربحت في بداية الأمر فتركت المبلغ وتركت ربحه لعله يكسب مرة أخرى، لكن خسرت المساهمة الثانية، والمبلغ الآن مشكوك في سلامته وفي عودته، فهل عليه زكاة وعلى ربحه أم كيف أتصرف؟","title":"حكم زكاة المال المساهم به والمشكوك في أرباحه وعودته","answer":"الجواب: ما دامت المساهمة للتجارة والفائدة والربح فإن على المساهم الزكاة كل سنة بحسابها، عليه أن يزكي السنة التي فيها الربح حسب قيمة العقار، والسنة التي خسرت وضعف فيها الربح لها زكاتها أيضاً، فإذا كانت في السنة الأولى تساوي الأرض مائة ألف عليه زكاة مائة ألف؛ ألفين ونص، ربع العشر، فإذا كانت في السنة الثانية نزلت صار ما تساوي إلا خمسين عليه زكاة الخمسين، والمعلوم أن عشرها خمسة آلاف، ربع العشر ألف ومائتان وخمسون، وهكذا.. لو كانت في السنة الثانية أربعين ألف زكى أربعين فيها ألف واحد.\nفالمقصود أن الزكاة تدور مع القيمة، فإذا غلت القيمة ارتفعت الزكاة وإذا نزلت القيمة نزلت الزكاة على حسبها ربع العشر، وهذا في العقار وغير العقار مما يعد للتجارة، قد يشتري سيارات للتجارة مثلاً تبقى عنده سنة وهي للتجارة قيمتها مثلاً مائة ألف أو أكثر ثم تنزل قيمتها لوجود موديل جديد فتنزل قيمتها فيزكيها في السنة الثانية على حسب قيمتها الجديدة الأخيرة التي نزلت وهكذا غيرها، فالأرض والسيارة وسائر السلع دربها واحد، تدور الزكاة مع القيمة، إن ارتفعت ارتفعت الزكاة، وإن نزلت نزلت الزكاة. نعم.\nالمقدم: أخونا يقول: إن رأس المال والربح مشكوك في عودته؟\nالشيخ: هذا يختلف، إن كانت مبيعته صارت عند إنسان مماطل ما يدرى أن يعطيه أو ما يعطيه لا ما عليه زكاة حتى يسلم له المال أو عند إنسان فقير معسر ما عليه زكاة على الصحيح حتى يستلف المال ويستقبل به حولاً من المعسر أو المماطل، فإذا قبضه يستقبل به حولاً مستقبلاً يعني.\nالمقدم: حول جديد؟\nالشيخ: إيه جديد. قال بعض أهل العلم: إنه يؤدي عن زكاة سنة واحدة، إن أدى عن سنة واحدة فهذا حسن، إذا زكى عن سنة واحدة من السنوات الماضية التي بقي له المال عند هذا المماطل أو عند المعسر، إذا زكى عن عام واحد هذا حسن، قاله جماعة من أهل العلم، وإلا فالصواب أنه لا يلزمه شيء، يستقبل حولاً جديداً، إذا يسر الله له المال من هذا المعسر أو من هذا المماطل فإنه يزكيه من جديد إذا حال عليه الحول.\nأما إن كانت الأرض موجودة ولكن رخص سعرها، وهو يشك في حصول رأس المال يزكي الموجود، اشتراها بمائة ألف ولكن ما تساوي الآن إلا خمسين ألف، كسدت الأراضي يزكي خمسين ألف، يزكي الخمسين التي تساوي في الأرض، حتى ولو ما تساوي إلا عشرة وهي بمائة ألف، يزكي العشرة التي حال عليها الحول وهي بهذه القيمة. نعم.","link":"https://binbaz.org.sa/fatwas/7096/حكم-زكاة-المال-المساهم-به-والمشكوك-في-ارباحه-وعودته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_144/14404.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":9140,"question":"السؤال الثاني يقول فيه: هل يجوز دفع الزكاة للأخ حين لا يرث، أفيدونا أفادكم الله؟","title":"حكم دفع الزكاة للأخ الفقير","answer":"الجواب: الأخ الفقير يعطى الزكاة حتى ولو كان وارثاً على الأصح، إذا كان فقيراً يعطى من الزكاة كالعم والخال وابن الأخ والأخت ونحوهم، أما الآباء والأمهات والأجداد والجدات والأولاد وأولاد البنين وأولاد البنات هؤلاء لا يعطون؛ لأنهم من أهل البيت فلا يعطون من زكاة الولد، لا يعطي أصله من زكاته ولا فرعه من زكاته، هذا هو المعروف عند أهل العلم وقد حكى عليه الحافظ ابن المنذر رحمه الله الإجماع في الجملة. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7305/حكم-دفع-الزكاة-للاخ-الفقير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_230/23008.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":9206,"question":"هل تجوز الزكاة لفتاة عمرها عشرون سنة، وكم يكون مقدارها وما هو وقتها؟","title":"عدم ورود سن محددة لمستحقي الزكاة","answer":"الجواب: نعم. الزكاة لها ولغيرها من الفقراء ليس للزكاة سن مشروط، فالفقير يعطى وإن كان صغيرًا وإن كان طفلًا، إذا كان عند أهله الفقراء يعطى.\nفالمقصود: أنه ليس هناك سن معينة للفقير، فالفتاة التي لها عشرون أو خمسة عشر أو عشر أو أقل أو أكثر إذا كانت فقيرة تعطى من الزكاة، يعطى القائم عليها المتوليها، إلا إذا كان القائم عليها غنيًا كأبيها أو أخيها فالنفقة عليهم، لكن لو كانت المرأة فقيرة عند أناس قد أحسنوا إليها وحضنوها يرجون ما عند الله وهم ليسوا أقارب لها، فإنها تعطى من الزكاة ولو كانت كبيرة، وهكذا لو كانت وحدها تعطى من الزكاة صغيرة أو كبيرة إذا كانت فقيرة قد توافرت فيها شروط أهل الزكاة. نعم.","link":"https://binbaz.org.sa/fatwas/7366/عدم-ورود-سن-محددة-لمستحقي-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_181/18113.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":9577,"question":"يسأل أخيراً ويقول: شخص مات وفي ذمته دين ولا يوجد له تركة لقضاء دينه، هل يقضى دينه من الزكاة؟","title":"حكم قضاء الدين عن المدين من الزكاة","answer":"الجواب: في هذا خلاف بين العلماء، والصواب: أنه لا حرج أن يقضى من الزكاة؛ لأنه من الغارمين، والغارمون: صنف من أصناف الزكاة بنص الآية الكريمة إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ [التوبة:60] الآية، فإذا صرفت الزكاة في قضاء دينه فلا حرج إن شاء الله في أصح قولي العلماء.\nالمقدم: بارك الله فيكم، وجزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7738/حكم-قضاء-الدين-عن-المدين-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_247/24710.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":9629,"question":"له سؤال ثالث يقول فيه: كم عدد النقود التي تخرج منها الزكاة؟ وكم يمر عليها من الزمن لذلك؟","title":"نصاب المال","answer":"الجواب: نصاب الذهب عشرون مثقالاً، ومقداره بالجنيه السعودي إحدى عشر جنيه وثلاثة أسباع جنيه، يعني: قرب النصف إحدى عشر جنيه ونصف، فإذا بلغ هذا المقدار وجبت فيه الزكاة كلما حال الحول، ربع العشر في كل أربعين جنيه جنيه واحد، أو قيمته من الفضة أو الورق، ومقداره بالجرام اثنان وتسعون جرام هذا هو النصاب، والواجب ربع العشر في القليل والكثير إذا بلغ النصاب وحال عليه الحول، ففي أربعين جنيه واحد جنيه، وفي مائة جنيهان ونصف ونص وهكذا، وإن أخرج الذهب فهو أفضل وإن أخرج قيمته من الفضة أو من الورق المستعمل فلا بأس في ذلك ويجزئه ذلك.\nأما الفضة فنصابها مائة وأربعون مثقالاً، ومقداره بالريال السعودي ستة وخمسون ريالاً، فإذا كان عند الإنسان ستة وخمسون أو أكثر وحال عليها الحول وجب فيها الزكاة ربع العشر، في كل مائة اثنان ونص، في الألف خمسة وعشرون، وهكذا في العشرة آلاف مائتان وخمسون، في مائة الألف ألفان وخمسمائة وهكذا.\nوالواجب على المسلم أن يتقي الله وأن يخرج الزكاة عن طيب نفس وإخلاص، وأن يدفعها إلى مستحقيها من الفقراء والمساكين والغارمين وأبناء السبيل، ونحوهم من أهل الزكاة. نعم.\nالمقدم: بارك الله فيكم، ذكرتم سماحة الشيخ أن نصاب الفضة يعادل بالريال السعودي ستة وخمسين، فهل يقصد بهذا الريال الفضة.\nالشيخ: الفضي وما يقوم مقامه.\nالمقدم: يقوم مقامه الورقي؟\nالشيخ: نعم.\nالمقدم: يعني بقيمته ....\nالشيخ: لأنها عملته؛ لأنها عملة مستقيمة بدل الذهب والفضة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7795/نصاب-المال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_250/25006.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":9634,"question":"له سؤال ثالث يقول فيه: كم عدد النقود التي تخرج منها الزكاة؟ وكم يمر عليها من الزمن لذلك؟","title":"نصاب المال","answer":"الجواب: نصاب الذهب عشرون مثقالاً، ومقداره بالجنيه السعودي إحدى عشر جنيه وثلاثة أسباع جنيه، يعني: قرب النصف إحدى عشر جنيه ونصف، فإذا بلغ هذا المقدار وجبت فيه الزكاة كلما حال الحول، ربع العشر في كل أربعين جنيه جنيه واحد، أو قيمته من الفضة أو الورق، ومقداره بالجرام اثنان وتسعون جرام هذا هو النصاب، والواجب ربع العشر في القليل والكثير إذا بلغ النصاب وحال عليه الحول، ففي أربعين جنيه واحد جنيه، وفي مائة جنيهان ونصف ونص وهكذا، وإن أخرج الذهب فهو أفضل وإن أخرج قيمته من الفضة أو من الورق المستعمل فلا بأس في ذلك ويجزئه ذلك.\nأما الفضة فنصابها مائة وأربعون مثقالاً، ومقداره بالريال السعودي ستة وخمسون ريالاً، فإذا كان عند الإنسان ستة وخمسون أو أكثر وحال عليها الحول وجب فيها الزكاة ربع العشر، في كل مائة اثنان ونص، في الألف خمسة وعشرون، وهكذا في العشرة آلاف مائتان وخمسون، في مائة الألف ألفان وخمسمائة وهكذا.\nوالواجب على المسلم أن يتقي الله وأن يخرج الزكاة عن طيب نفس وإخلاص، وأن يدفعها إلى مستحقيها من الفقراء والمساكين والغارمين وأبناء السبيل، ونحوهم من أهل الزكاة. نعم.\nالمقدم: بارك الله فيكم، ذكرتم سماحة الشيخ أن نصاب الفضة يعادل بالريال السعودي ستة وخمسين، فهل يقصد بهذا الريال الفضة.\nالشيخ: الفضي وما يقوم مقامه.\nالمقدم: يقوم مقامه الورقي؟\nالشيخ: نعم.\nالمقدم: يعني بقيمته ....\nالشيخ: لأنها عملته؛ لأنها عملة مستقيمة بدل الذهب والفضة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7795/نصاب-المال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_250/25006.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":9705,"question":"الرسالة التالية وصلت إلى البرنامج من المستمع عبدالمحسن أحمد من مدينة جدة، يقول الأخ عبدالمحسن في رسالته: أنا مدير محلات تجارية وصاحب هذه المحلات يطرح الزكاة عندي سنويًا وله ناس مخصصين يأتونه في كل سنة يعطيهم الزكاة وأسماؤهم مسجلة عندي في كشف وصاحب المحلات يسافر في شهر رمضان إلى الخارج ويقول: لا تعطي الزكاة إلا من كان اسمه مسجل في الكشف، وفي هذه السنة لم يأت البعض لأخذ الزكاة والزكاة عندي موجودة أفيدوني أفادكم الله؟","title":"وجوب عمل الوكيل بأمر الموكل","answer":"الجواب: عليك أن تعتمد ما قال لك صاحب الزكاة فتعطيها الأشخاص الذين سماهم وسجلهم لديك ولا تعط غيرهم؛ لأنك وكيل والوكيل يلتزم بما قاله الموكل، لكن إذا علمت أن بعضهم غني وأنه لا يصلح للزكاة تنصحه وتقول له: فلان لا يصلح، فلانة لا تصلح، وإذا تأخر بعضهم تخبره، إذا تأخر بعضهم فماذا أفعل؟ هل أعطيها من أرى أنه فقير؟ أو يسمي لك أشخاصًا آخرين فتعطيهم، أما أنت لا تتصرف بدون إذنه، لابد من إذنه في ذلك لأنك وكيل والوكيل لابد يلتزم بأمر الموكل ولكن عليك النصيحة إذا علمت أن بعض الأشخاص المسميين عندك لا يصلحون لغناهم أو كفرهم أو أشياء أخرى تمنعهم من الزكاة بينها للشخص صاحب التجارة حتى تتفق معه على الأشخاص الذين ينبغي أن تدفع لهم الزكاة ومن تأخر منهم تحفظ حصته وتبقى عندك حتى تستشير صاحب الزكاة في ذلك فيعمدك بما يرى في هذا الأمر. نعم.","link":"https://binbaz.org.sa/fatwas/7851/وجوب-عمل-الوكيل-بامر-الموكل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_195/19503.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":9726,"question":"يقول يا سماحة الشيخ هذا السائل: ما معنى بلوغ النصاب في الزكاة؟ هل الزكاة غير الإنفاق؛ لأن الإنفاق تكرر كثيراً في الجزء الثالث من سورة البقرة؟","title":"معنى النصاب في الزكاة، والفرق بين الإنفاق والزكاة","answer":"الجواب: النصاب غير الإنفاق، الإنفاق: ينفق مما أعطاه الله من المال غير الزكاة، أما الزكاة فشيء فرضه الله لأصناف معينين ثمانية ذكرهم الله في سورة التوبة: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا... الآية [التوبة:60]، والزكاة تختلف في النقود ربع العشر يعني: سهم من أربعين هذا في النقود، الذهب والفضة وعروض التجارة سهم من أربعين ربع العشر.\nوفي الحبوب والثمار إن كانت بمئونة بالمكائن وأشباهها نصف العشر، يعني: سهم من عشرين، وإن كانت بالأمطار سقي الزروع بالأمطار والأنهار فهذا العشر كاملاً واحد من عشرة فيه كله، عشرة واحد يعني: عشرة أوسق فيها العشر وهكذا في الحبوب والثمار.\nأما الإبل والبقر والغنم لها زكاة خاصة بينها الرسول ﷺ إذا كانت راعية سائمة، فالإبل لها زكاة والغنم لها زكاة والبقر لها زكاة مبينة في كتب العلماء وفي الأحاديث الصحيحة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7881/معنى-النصاب-في-الزكاة-والفرق-بين-الانفاق-والزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_272/27217.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":9933,"question":"وهذه رسالة من السائل أحمد صالح زيد من اليمن الشمالي ومقيم في مدينة حفر الباطن في المملكة العربية السعودية يقول في رسالته: إذا كنت في الغربة مثلًا أنا في السعودية وأهلي في اليمن فهل أزكي عن نفسي وأهلي أم أزكي عن نفسي فقط وأهلي يزكون عن أنفسهم، أفيدونا بارك الله فيكم؟","title":"الموطن الذي يؤدي فيه المغترب الزكاة عنه وعن أهله","answer":"الجواب: أنت مخير إن زكيت عن نفسك وعنهم في محل الغربة فلا بأس؛ لأنهم تابعون لك وأنت المسئول عنهم، فإذا زكيت عنهم يعني زكاة الفطر مع زكاتك كفى ذلك؛ لأنك مسئول، وإن عمدتهم بإخراج الزكاة عن أنفسهم هناك أجزأ ذلك، إذا عمدتهم أن يخرجوا الزكاة عندهم وفي فقرائهم فلا بأس، والأصل وجوبها عليك أنت تزكي عنهم. نعم.","link":"https://binbaz.org.sa/fatwas/8093/الموطن-الذي-يودي-فيه-المغترب-الزكاة-عنه-وعن-اهله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_199/19907.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":10014,"question":"هل تجوز الزكاة في المال الدين الذي ليس عند صاحبه؟","title":"حكم زكاة مال القرض الذي ليس في اليد","answer":"الجواب: الدين أقسام: تارة يكون عند عاجز لا يستطيع الوفاء هذا لا زكاة فيه حتى يقبضه صاحبه، لأنها مواساة ولا تجب على المواساة في دين لا يستطيع قبضه.\nالحال الثاني: أن يكون عند مماطل هو يقدر ولكن ما يعطي ما يوفي يماطل فهذا كالفقير لا تلزمك الزكاة حتى تقبض من هذا المماطل.\nالثالث: أن يكون عند مليء باذل متى طلبته أعطاك فهذا تجب عليك الزكاة فيه وإن كان عنده، كالأمانة عليك أن تزكي كل سنة ما دام عند مليء باذل فعليك الزكاة، أما إذا كان عند فقير معسر أو غني لكن مماطل لا يوفي ويتعبك فليس عليك زكاة حتى تقبض ثم تستقبل حولًا. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8183/حكم-زكاة-مال-القرض-الذي-ليس-في-اليد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_332/33202.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":10475,"question":"يسأل سماحتكم سؤالًا آخر فيقول: ما الرأي في الدين الذي يمضي عليه الحول وهو عند المدين ولم أستلم، هل أخرج الزكاة أم كيف أتصرف جزاكم الله خيرًا؟","title":"حكم إخرج الدائن زكاة ماله الذي عند المدين","answer":"الجواب: إذا كان الدين على إنسان معسر، فلا زكاة فيه حتى تقبضه، وهكذا لو كان الدين على إنسان مماطل، تطلبه الحق ولا يعطيك، فإنه لا زكاة عليك حتى تقبضه وتستقبل به عامًا جديدًا، أما إذا كان الدين على إنسان مليء غير مماطل متى طلبته أعطاك فإن الواجب عليك الزكاة، متى تم الحول عليك أن تزكي ولو ما قبضته؛ لأنه كالذي عندك، ما دام عند إنسان مليء غير مماطل، فهو كالذي عندك فيه الزكاة متى تم عليه الحول.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8650/حكم-اخرج-الداىن-زكاة-ماله-الذي-عند-المدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_281/28102.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":10499,"question":"مستمع يقول سوداني مقيم في المملكة يقول: إن له نصيب في الزكاة فيما يرى لكنه يرفض أخذها فما الحكم؟","title":"حكم رفض الفقير أخذ الزكاة.","answer":"الجواب: هذا يخضع لما يقدر من المصالح، فإذا كان يرى أن ترك هذا خير من هذا المال من الزكاة، فيه مصلحة له فلا بأس، يعني ينظر لما هو الأصلح، ما هو بلازم أنه يأخذ من الزكاة، إذا كان عنده ما يسد حاله أو زكاة أخرى تيسرت له من جهات أخرى، وهذا الذي بيأخذ منه الزكاة قد يعني يضره، أو يمن عليه أو يؤذيه أو ما أشبه ذلك، إذا كان ترك ذلك لأسباب بينة واضحة فلا بأس، المقصود ينظر ما هو الأصلح، يأخذ من هذا ولا يأخذ من هذا، ينظر ما هو الأصلح في دينه وسمعته وعدم إيذاء المعطي له، أو منته عليه أو ما أشبه ذلك، ... أن يتحرى ما هو أصلح، يتحرى ما هو أصلح.\nالمقدم: جزاكم الله خيرًا، يقول: إنه يخشى أن تعوده الخمول والكسل؟\nالشيخ: إذا كان يخشى ذلك يترك ويعمل يجتهد، إذا كان يستطيع أن يعمل ويكتسب، يعمل ويكتسب لعله يدرك ما يكفيه ويستغني عن الصدقة عن الزكاة، إذا كان عنده قدرة فالواجب عليه أن يعمل ويجتهد ولا يلجأ للصدقات، بل يعمل حتى يدرك حاجته. نعم.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8674/حكم-رفض-الفقير-اخذ-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_282/28207.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":10513,"question":"تقول أختنا في سؤالها الثاني: إذا كان للإنسان محلات وشقق مؤجرة فكيف تكون زكاتها؟","title":"كيفية زكاة الشقق والبيوت المؤجرة","answer":"الجواب: الزكاة في الأجرة إذا كانت الشقق للقنية والاستفادة والتأجير ليس فيها زكاة، ولكن الزكاة تكون في الأجرة إذا حال عليها الحول زكاها، فإذا أجر الشقة مثلاً بألف ريال، إذا حال الحول على الألف وهو عنده ما خرجه ولا أنفقه يخرج زكاته ربع العشر، إذا حال الحول على الأجرة إذا بقيت عنده حتى حال عليها الحول، أما إذا أوفى بها دينًا، أو أنفقها في حاجاته قبل الحول فلا زكاة فيها.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8688/كيفية-زكاة-الشقق-والبيوت-الموجرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_283/28302.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":10623,"question":"أخونا يقول: إنه طيلة الثلاث السنوات جمع بعض المال ولم يزكه حتى الآن، بم تنصحونه؟","title":"حكم من جمع مالاً طيلة ثلاث سنوات ولم يزكه","answer":"الجواب: الواجب عليه الزكاة، الواجب عليك يا أخي! أن تزكي المال عن السنوات الثلاث، إذا كان قد بلغ النصاب فعليك الزكاة عن السنوات الثلاث، في كل مائة اثنان ونصف، في الألف خمسة وعشرون، يعني: ربع العشر. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8793/حكم-من-جمع-مالا-طيلة-ثلاث-سنوات-ولم-يزكه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_327/32705.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":10765,"question":"عندي مبلغ من المال وقد أقرضته بعض المحتاجين له، وقد صرفوا هذا المال ولم يبق معهم شيء، هل علي زكاة في هذا المال أم لا، أرجو الإفادة جزاكم الله خيراً؟","title":"حكم الزكاة في الدين الذي على معسر","answer":"الجواب: ما داموا معسرين فليس عليك زكاة إذا كان المقترض معسراً فليس عليك زكاة، أو كان موسراً لكنه يماطل ما أعطاك تطلبه ولا يعطيك، فلا زكاة عليك حتى تقبضه، ثم تستقبله حولاً جديداً، فتزكيه بعد ذلك، أما إذا كان الذي عليه القرض مليئاً باذلاً فعليك الزكاة، ولو مكث عنده سنوات عليك أن تزكي عن كل سنة ما دام مليئاً لو طلبته أعطاك ليس بمماطل، فإنك تزكيه كأنه أمانة، أما إذا كان معسراً فإن الدين الذي عليه ما تجب زكاته؛ لأنه ليس في يدك والزكاة مواساة، وأنت لا تملك الآن قبضه فلا زكاة عليك، وهكذا إذا كان يستطيع لكنه يماطل ولم يعطك ولم يقم بالواجب الذي عليه من دفع حقك، فإنه لا زكاة عليك؛ لأن المماطل كالمعسر فلا زكاة عليك حتى تقبضه ثم تستقبل به حولاً كاملاً وتزكيه بعد ذلك. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8946/حكم-الزكاة-في-الدين-الذي-على-معسر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_348/34806.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":10936,"question":"المستمعة (م. ن. ع) من الكويت بعثت برسالة تقول فيها: هل يجوز إخراج الزكاة قبل حلول موعد إخراجها بشهر أو شهرين؟ وهل يصح أن تكون راتبةً لبعض المحتاجين بصفة دائمة، خاصةً وأنهم لا يزالون بحاجة إليها؟","title":"حكم إخراج الزكاة قبل موعدها وبصورة دائمة لفقراء معينين","answer":"الجواب:  نعم لا حرج في إخراج الزكاة قبل موعدها للمصلحة الشرعية، فقد تعجل النبي ﷺ زكاة عمه العباس قبل موعدها، فإذا أخرج الإنسان الزكاة قبل موعدها؛ لوجود فقراء محتاجين عجل لهم الزكاة، أو لمجاهدين، أو لفقراء من أقاربه اشتدت حاجتهم، أو نحو ذلك، فكل هذا لا بأس، بل ذلك مشروع، وفيه خير كثير. ويجوز أن تكون الزكاة راتبًا لبعض المحتاجين يدفعها إليه كل سنة صاحب الزكاة، إذا عرف حاجته، وأن حاجته مستمرة، فيعطيه إياه كل سنة، عادة سنوية؛ لعلمه بحاجته وأنه من أهل الزكاة لا حرج في ذلك، بل هذا في محله وصاحبه مأجور إذا تحرى حاجة إخوانه المساكين وأعطاهم إياها كل سنة؛ لحاجتهم وفقرهم حتى تزول الحاجة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9115/حكم-اخراج-الزكاة-قبل-موعدها-وبصورة-داىمة-لفقراء-معينين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_362/36212.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":10959,"question":"المستمع جابر محمد محمود مصري بعث برسالة يقول فيها: إنني أعمل خارج بلدي، وبحمد الله استطعت أن أجمع مبلغًا لا بأس به من المال، وأحب أن أخرج الزكاة، لكني لا أعرف مقدار الزكاة الواجبة، ولا لمن تعطى، هل تعطى للمساكين المتجمعين أمام المساجد، أم للمحتاجين من الأقرباء؟ وهل يجوز لي أن أرسلها لمن أرى أنه يستحقها من أبناء بلدي خارج البلد الذي أعمل فيه؟ أرجو الإفادة عن هذه القضايا جزاكم الله خيرًا.","title":"حكم زكاة المال وصرفها لفقراء الأقارب من خارج البلد","answer":"الجواب:  أما الزكاة فهي ربع العشر بالنص عن الرسول ﷺ وبإجماع المسلمين، في مسألة النقود، وعروض التجارة، يعني: سهم من أربعين سهمًا، ربع العشر من الذهب والفضة، وما يقوم مقامها من العمل، وقيمة عروض التجارة كالسيارات والأراضي وأشباه ذلك تعرف القيمة، ثم بعد معرفة القيمة يكون فيها ربع العشر، في المائة اثنان ونصف، في الألف خمسة وعشرون، وهكذا ربع العشر يعني: سهم من أربعين، هذا هو الواجب في النقود، وما يقوم مقامها من العمل الورقية، وهو الواجب أيضًا في عروض التجارة، وعروض التجارة هي الأموال التي تعد للبيع من أراضٍ، أو سيارات، أو خام، أو حبوب، أو غير ذلك من الأمتعة، هذه يقال لها: عروض التجارة، إذا كانت معدة للبيع، يقال لها: عروض التجارة، فإذا حال الحول عليها وجبت الزكاة في قيمتها، ربع العشر . فإذا كان عنده سيارات للبيع، وعند تمام الحول بلغت قيمتها مليونًا، زكى المليون، ربع العشر، خمسة وعشرين ألفًا من المليون؛ لأن عشر المليون مائة ألف، والربع خمسة وعشرون، هذا ربع العشر.  وهكذا لو كان عنده أراضٍ تساوي مليونًا، أعدها للبيع إذا حال عليها الحول يزكي ربع العشر، يزكي ربع قيمتها، وإذا كانت تساوي مليونًا فيها خمسة وعشرون ألفًا، وإذا كانت تساوي مائة ألف فيها ألفان ونصف، ألفان وخمسمائة، وهكذا. المقصود ربع العشر وهو سهم من أربعين سهمًا، هذه الزكاة في النقود من الذهب والفضة، وفيما يقوم مقامهما من العمل الورقية، وفي عروض التجارة وهي الأموال المعدة للبيع. أما زكاة الحبوب والثمار فهذه نوع آخر. وهي نصف العشر فيما يسقى بالمؤونة كالمكائن والسواني، والعشر فيما يسقى بالمطر والأنهار الجارية، والبعل الذي على مطر، هذا يكون فيه العشر كاملًا.  فإذا كان ألف كيلو تكون مائة كيلو، وهكذا، عشرة آلاف كيلو تكون ألفًا، الزكاة العشر، فيما يسقى بلا مؤونة، بلا كلفة بالأنهار، بالمطر، بالبعل كونه يبذر في الأرض، ويصلح على بذارة الأرض التي فيها الماء، من غير حاجة إلى مكائن، ولا سواني، ولا تعب، هذا فيه العشر كاملًا، لقول النبي ﷺ لما سئل عن ذلك: فيما سقي بالنضح نصف العشر، وفيما سقي بالأنهار العشر. فالمقصود أن هذا هو الحكم فيما يسقى بالمؤونة، وبغير مؤونة، ما يسقى بالمؤونة من السواني والمكائن فيه نصف العشر، وما يسقى بلا مؤونة ولا كلفة فيه العشر كاملًا. وأما الحيوانات فلها زكاة أخرى نوع آخر أيضًا، إذا كانت سائمة راعية من الإبل والبقر والغنم مفصلة في الأحاديث، وفي كلام أهل العلم. والسائل إنما سأل عن النقود وهذا بيان النقود كما سمعت ربع العشر. أما إخراجها فإنها تصرف في الفقراء والمساكين وغيرهم ممن سمى الله في قوله -جل وعلا-: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِمِينَ وَفِي سَبِيلِ اللَّهِ وَاِبْنِ السَّبِيلِ فَرِيضَةً مِنَ اللَّهِ وَاللَّهُ عَلِيمٌ حَكِيمٌ [التوبة:60]. فإذا كان في بلده فقراء من أقاربه، أو غيرهم هم أولى من غيرهم، الفقراء في البلد أولى من غيرهم، وإذا كانوا من الأقارب فهم أولى، صدقة وصلة، تعتبر في حقهم صدقة وصلة، وإذا دعت الحاجة إلى نقلها إلى فقراء خارج البلد، أو أقارب فقراء خارج البلد؛ لأنهم أشد حاجة، وأشد ضرورة، فلا بأس بنقلها على الصحيح، وهكذا لو نقلها إلى المجاهدين في أفغانستان، وفي أرض في فلسطين فلا بأس بذلك؛ لأنهم في حاجة، ونقلها إليهم فيه مصلحة عظيمة. ومتى اجتهد صاحب الزكاة وفرقها في بلده، أو في فقراء خارج بلده من أقارب وغيرهم، فكل ذلك بحمد الله جائز والحمد لله، نعم. المقدم: جزاكم الله خيرًا، إنما سماحة الشيخ تفضلون إذا كان هناك أقارب فقراء تفضلون أن يكون الصرف عليهم؟ الشيخ: نعم إذا كان في البلد فقراء هم أفضل وأولى، وإذا كانوا أقارب فالصدقة فيهم أفضل أيضًا؛ لأنها صدقة وصلة رحم جميعًا، ولكن يجوز نقلها للمصلحة الراجحة، يجوز أن تنقل من بلد إلى بلد إذا كانت لمصلحة أرجح، لأقارب بعيدين أو لمجاهدين محتاجين، أو فقراء حاجتهم شديدة، فينقلها مثلاً من مكة إلى جدة، من الرياض إلى الخرج إلى الأحساء إلى أبها إلى غير هذا، نعم. المقدم: بارك الله فيكم سماحة الشيخ يذكر الفقراء الذين يتجمعون على أبواب المساجد، وهؤلاء يغلب على حالهم أنهم اتخذوا السؤال صنعة، توجيهكم شيخ عبدالعزيز ؟ الشيخ: من أظهر الفقر والحاجة ..... ممن يعرف أنه كاذب يعطى، سواء كان ممن يتجمع حول المساجد، أو في أي مكان، من ادعى الفقر والحاجة والعلامة الظاهرة عليه، ولا يوجد ما يكذبه فلا بأس أن يعطى، والنبي ﷺ لما اشتكى إليه رجلان وطلبا منه الزكاة، ورآهما جلدين يعني: نشيطين، قال: إن شئتما أعطيتكما، ولا حظ فيها لغني، ولا لقوي مكتسب. والإنسان قد يكون جلدًا، ولكن ما عنده مال، ما وجد... حرفة ولا وجد عملًا، فيعطى إذا أظهر الحاجة والفقر، ولا يوجد ما يدل على أنه كاذب يعطى؛ لأنه قد يكون صادقًا، ما وجد عملًا، ما حصل له شيئًا . فالحاصل أن من أظهر الفقر والحاجة، وسأل ولا يوجد ما يدل على كذبه يعطى، نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/9140/حكم-زكاة-المال-وصرفها-لفقراء-الاقارب-من-خارج-البلد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_364/36407.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11044,"question":"هذا السائل عيظة عبدالله من بلجرشي، يقول سماحة الشيخ: يوجد عمارة بها شقق يتم تأجيرها بالشهر، وتارة تبقى الشقق بدون إيجار لعدة شهور، ويخرج المستأجر، ويأتي آخر بعد شهر، أو أكثر فكيف نؤدي زكاة إيجار تلك الشقق، وما حكم المصاريف على تلك الشقق من ناحية إصلاحها بالنسبة للزكاة؟ مأجورين.","title":"كيفية زكاة العين المؤجرة","answer":"الجواب:  متى أجرت بأجرة حال عليها الحول تزكى الأجرة، أما إذا تعطلت ما فيها زكاة؛ لأنها للإيجار، ما هي للبيع، إذا تعطلت ليس فيها زكاة، لكن إذا أجرها مدة سنة، أو أكثر يزكي، يزكي الأجرة إذا حال عليها الحول، أما لو زكاها بأجرة مستعجلة، وأكلها، أنفقها في حاجاته، ما فيها زكاة، الزكاة في الأجرة إذا بقيت حتى يحول عليها الحول، يزكيها إذا كانت نصابًا، والنصاب ستة وخمسون ريالًا من الفضة فأكثر، أو ما يقوم مقامها من الأوراق، من العمل الورقية، نعم.","link":"https://binbaz.org.sa/fatwas/9222/كيفية-زكاة-العين-الموجرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_287/28726.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11233,"question":"السائل محمد إسماعيل يقول: سؤالي الأول: زوج وزوجة الزوج فقير جدًا والزوجة غنية، هل يجوز إعطاء زكاة أموالها لزوجها؟","title":"حكم إعطاء الزوجة الغنية زكاة مالها لزوجها الفقير","answer":"الجواب:  فيه خلاف بين أهل العلم، والصواب أنه يجوز لحديث ابن مسعود لا بأس أن تعطي زكاتها لزوجها. نعم.","link":"https://binbaz.org.sa/fatwas/9404/حكم-اعطاء-الزوجة-الغنية-زكاة-مالها-لزوجها-الفقير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_291/29114.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11273,"question":"هل يصح للابنة أن تخرج زكاة الحلي عن والدتها وتعطيه لشقيقتها؟","title":"حكم إخراج البنت زكاة حلي والدتها وإعطائه لشقيقتها","answer":"الجواب:  إذا سمحت والدتها وأذنت لها أن تزكي عنها فلا بأس، ولا بأس أن تعطيها شقيقتها الفقيرة، أما إذا كانت شقيقتها غير فقيرة أو لها أب ينفق عليها أو زوج ينفق عليها فلا تعطى، أما إن كانت أخت فقيرة ليس لها من يقوم عليها فلا بأس أن تعطيها الزكاة، وقد أخرج النبي صلى الله عليه وسلم الزكاة عن عمه العباس . نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9454/حكم-اخراج-البنت-زكاة-حلي-والدتها-واعطاىه-لشقيقتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_375/37505.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11307,"question":"يقول أحد الإخوة المستمعين: يوجد لدي مبلغ من المال، فهل عليه زكاة إذ أنه ليس بحوزتي الآن بل هو أسلاف لدى الناس.الشيخ: أعد.المقدم: يقول: يوجد لي مبلغ من المال، هل عليه زكاة إذ أنه ليس بحوزتي الآن بل هو أسلاف عند الناس؟ جزاكم الله خيرًا.","title":"حكم زكاة المال إذا كان دينًا في ذمة آخرين","answer":"الجواب:  هذا فيه تفصيل، إن كانوا أغنياء فإذا قبضت فزكِ، وإن كان ما عندك شيء كل ما قبضت تزكي، أما إن كانوا لا، ليسوا بأغنياء، معسرين أو مماطلين فليس عليك شيء حتى تقبض، فإذا قبضت تستقبل حولًا جديدًا، نسأل الله السلامة. المقدم: اللهم آمين جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9485/حكم-زكاة-المال-اذا-كان-دينا-في-ذمة-اخرين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_376/37617.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11371,"question":"هل يصح للابن أن يخرج زكاة الحلي عن والدته؟","title":"حكم إخراج الابن زكاة الحلي عن والدته","answer":"الجواب:  نعم إذا رضيت بذلك يصح أن يخرجها عنها زوجها وولدها وأخوها وبنتها وغيرهم إذا أخرجها عنها غيرها من الناس بإذنها فهو وكيل فلا بأس. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9578/حكم-اخراج-الابن-زكاة-الحلي-عن-والدته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_379/37921.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11378,"question":"هل يصح للابن أن يخرج زكاة الحلي عن والدته؟","title":"حكم إخراج الابن زكاة الحلي عن والدته","answer":"الجواب:  نعم إذا رضيت بذلك يصح أن يخرجها عنها زوجها وولدها وأخوها وبنتها وغيرهم إذا أخرجها عنها غيرها من الناس بإذنها فهو وكيل فلا بأس. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9578/حكم-اخراج-الابن-زكاة-الحلي-عن-والدته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_379/37921.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11418,"question":"يسأل سماحتكم عن الزكاة، وعن زكاة الراتب بالذات كيف يخرجها؟ جزاكم الله خيرًا.","title":"كيفية إخراج زكاة المرتبات الشهرية للموظف","answer":"الجواب: إذا كان الراتب يحفظ حتى تمر عليه السنة؛ يزكى إذا كان يبلغ النصاب، أكثر من ست وخمسين فضة ريالًا، أو ما يقوم مقامها من النقود، إذا حال عليه الحول؛ يزكي، أما إذا أنفقه قبل أن يتم الحول؛ فلا زكاة فيه. المقدم: بارك الله فيكم، يزكي زكاة محرم في محرم؟ أو كيف يكون الحال؟ الشيخ: إذا جاء الراتب في المحرم؛ زكاة في المحرم، في كل مائة اثنان ونصف، في المائة اثنان ونصف، وإذا كان في صفر صفر، ربيع ربيع وهكذا، إذا تمت السنة؛ يزكي ربع العشر، ولو أنها مائة ريال، ولو أنها مائتين ريال، نعم. المقدم: الله المستعان، بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9599/كيفية-اخراج-زكاة-المرتبات-الشهرية-للموظف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_380/38017.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11457,"question":"يسأل ويقول: إذا كان لدي مال، فهل يجوز أن أصرف زكاته في بناء مسجد، أو لابد من صرفها على الفقراء؟ جزاكم الله خيرًا.","title":"حكم صرف الزكوات في بناء المساجد","answer":"الجواب: الزكاة لا تصرف في عمارة المساجد والمدارس، ولكن تصرف في الأصناف الثمانية المذكورة في قوله تعالى: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِمِينَ وَفِي سَبِيلِ اللَّهِ وَاِبْنِ السَّبِيلِ فَرِيضَةً مِنَ اللَّهِ وَاللَّهُ عَلِيمٌ حَكِيمٌ [التوبة:60]، فأنت يا أخي، اصرفها في الفقراء والمساكين، والحمد لله، نعم. المقدم: الحمد لله، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9638/حكم-صرف-الزكوات-في-بناء-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_381/38112.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11683,"question":"يقول: معي مبلغ من الدنانير الأردنية مضى عليها نصف الحول، فهل أدفع الصدقة عنها أو الزكاة في البلد الذي أقيم فيه، أم في بلدي وبالقيمة التي يجب دفعها؟ وجهوني جزاكم الله خيرًا.","title":"شروط إخراج الزكاة وأين تخرج","answer":"الجواب:  إذا حال عليها الحول تؤدي الزكاة في محلك الذي أنت فيه، سواء كنت في بلدك، أو في غيرها، إذا حال عليها الحول السنة، فعليك أن تؤدي زكاتها ربع العشر، في المائة اثنان ونصف، وفي الألف خمسة وعشرون، في المحل الذي أنت فيه تعطيه الفقراء في بلدك، وإن نقلتها إلى بلد آخر أجزأت والحمد لله، نعم. المقدم: جزاكم الله خيرًا يقول: إنه لم يمض عليها إلا نصف الحول؟ الشيخ: ما عليها زكاة حتى تكمل الحول، ليس عليها زكاة الدنانير والدراهم، وجميع أموال الزكاة، ليس فيها زكاة حتى تكمل الحول، إلا الحبوب والثمار هذه فيها زكاتها إذا نضجت، إذا نضجت فعليه زكاتها، وإذا جعلها في البيدر، ويبست أخرج زكاتها.  المقصود: أن الثمار من الحبوب والتمور والعنب زكاتها تجب إذا استوت، ونضجت وجبت فيها الزكاة، وأما الأموال الأخرى الذهب والفضة والإبل والبقر والغنم الراعية وعروض التجارة هذه لا بد فيها من السنة، الزكاة لا تجب إلا في السنة مرة، كل سنة يزكيها. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9863/شروط-اخراج-الزكاة-واين-تخرج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_390/39012.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11776,"question":"شخص عليه دين كثير، والشخص يشتغل بالتجارة، وفي كل عام يخرج الزكاة، ويعطيها لصاحب الدين حتى يقضي عنه دينه، هل هذا العمل مشروع؟","title":"حكم إعطاء المدين زكاته لدائنه","answer":"الجواب: إذا تواطؤوا على ذلك لا، أما إذا أعطاه لفقره، أعطى إنسانًا لفقره، ثم هو رأى أن يوفي منها من غير تواطؤ، ولا اتفاق؛ فلا حرج، أما أن يقول له .... حتى تعطينيها ما يصلح، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9956/حكم-اعطاء-المدين-زكاته-لداىنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_394/39418.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11889,"question":"رسالة بعث بها مستمع رمز إلى اسمه بالحروف (ب. ج. ع) يقول: عندي مبلغ من المال، وهذا المبلغ هو زكاة أموالي، وأنا بعيد عن وطني، وأعرف أناسًا من أقربائي هم في أمس الحاجة، إلى الزكاة، هل أرسلها لهم نقودًا، أو ملابس؟ أو بماذا توجهونني؟ جزاكم الله خيرًا، وما الحكم فيما إذا أرسلتها قبل حلول الحول؟ جزاكم الله خيرًا.","title":"حكم إرسال الزكاة للأقارب الفقراء وتعجيلها قبل حلولها","answer":"الجواب:  الأفضل أن تفرقها في محلك إذا كان فيه فقراء محتاجين، وإن نقلتها إلى أقاربك الفقراء في بلدك؛ لشدة حاجتهم؛ فلا حرج في ذلك، بعد التأكد من حاجتهم إلى الزكاة. والأفضل أن ترسلها نقودًا إليهم، فإن كانت الحاجة ماسة إلى أن ترسلها ملابس، أو طعامًا بواسطة الثقات؛ لأنهم نساء، أو أيتامًا يخشى أن يتلاعبوا بالنقود؛ فلا بأس، ولكن الأفضل إرسال النقود بواسطة الثقة حتى يسلمها لهم نقودًا، إذا كانوا أهلًا لذلك. أما إذا كانوا أيتامًا؛ فتسلم لوكيل الأيتام، وإن كانوا نساءً مرشدات؛ فتسلم لأيديهن، فإن كن ليس مرشدات؛ فبيد الوكيل الذي لهن، وإذا رأيت أن الأصلح أن تدفع لهم الزكاة ملابس أو طعامًا خشية التلاعب بالنقود؛ فلا بأس بذلك، ولا حرج في ذلك. ولا مانع من تقديمها قبل الحول، لا مانع من تقديم الزكاة لهم قبل تمام الحول، لا حرج في التعجيل. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10073/حكم-ارسال-الزكاة-للاقارب-الفقراء-وتعجيلها-قبل-حلولها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_425/42510.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11901,"question":"إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (م) و (ز. ح) لها رسالة وضمنتها قضيتين: القضية الأولى تقول فيها: هل يجوز إعطاء الأخ جزءًا من الزكاة زكاة المال؟ علمًا بأنه موظف، لكن دخله لا يكفي لأسرته، جزاكم الله خيرًا.","title":"حكم إعطاء المرأة زكاة مالها لأخيها الفقير","answer":"الجواب:  لا حرج في ذلك إذا كان الأخ أو العم أو الخال فقيرًا ومرتبه ضعيف لا يقوم بحاله؛ لا بأس أن يعطي من الزكاة، وهكذا ابن العم، أما الأب والأم لا، والأولاد لا، يعطون من مالك؛ لأن مالك غير الزكاة، أما إذا كان الأخ ضعيفًا فقيرًا أو الخال أو العم أو ابن العم، أو ما أشبه ذلك من الأقارب فالصدقة لهم .... من الزكاة صدقة وصلة، يعطون من الزكاة، ويكون لك أجران: أجر الزكاة، وأجر صلة الرحم، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10085/حكم-اعطاء-المراة-زكاة-مالها-لاخيها-الفقير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_426/42602.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11909,"question":"هل يجوز أن أعطي أختي زكاة مالي التي لا دخل لها غير معاش والدي المتوفى؟","title":"حكم إعطاء الأخت من الزكاة","answer":"الجواب:  إذا كانت أختك مستقلة في بيت وحدها، عاجزة، ما عندها ما يقوم بحالها، لك أن تعطيها الزكاة، أما إن كانت عندك في البيت تنفق عليها؛ فلا، لا تعطيها زكاتك؛ هي غنية بنفقتك عليها، وإن أنفقت عليها من مالك، وأعطيت الزكاة لغيرها؛ فهذا أحسن، وأحوط إذا كنت قادرًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10093/حكم-اعطاء-الاخت-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_426/42610.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11943,"question":"ما هو حكم من يقوم بجمع أموال الزكاة، ويعطي منها لوالديه الفقيرين، علمًا بأنه لا يستطيع الإنفاق عليهما؟","title":"حكم إعطاء الابن والديه الفقيرين مما جمعه من الزكاة","answer":"الجواب:  إذا كان يطلب من الناس المساعدة لإخوانه الفقراء ومن جملتهم والداه، وهما فقيران؛ فهو مأجور، هو وكيل يكون وكيلًا لمن دفع إليه الزكاة، فإذا كان صادقًا متحريًا لأهل الحاجة؛ فلا بأس عليه، يعطي والديه، وغير والديه إذا كانا فقيرين، نعم.","link":"https://binbaz.org.sa/fatwas/10128/حكم-اعطاء-الابن-والديه-الفقيرين-مما-جمعه-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_428/42807.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11944,"question":"جمعنا أموال الزكاة، وأقمنا بها مسجدًا يتعلم فيه الناس الصلاة، علمًا بأنه ليس هناك من يستحق هذه الزكاة في المكان الذي جمعت منه، فهل في ذلك حرج؟","title":"حكم تعمير المساجد من أموال الزكاة","answer":"الجواب:  المساجد لا تبنى من الزكوات في أصح قولي العلماء عند جمهور أهل العلم، فالذي قدم الزكاة لبناء المسجد؛ يجب عليه أن يعيد ذلك، وأن يزكي زكاة أخرى، للفقراء والمساكين، أو للغارمين، أو غيرهم من أصناف الزكاة، وهذه النفقة التي صرفها للمسجد تكون صدقة مطلقة، له أجرها وفضلها عند الله  وعليه أن يخرج الزكاة في أصنافها بدلًا من المال الذي صرفه في تعمير المسجد، هذا هو الذي عليه جمهور أهل العلم، وهو أصح قولي العلماء؛ لأن تعمير المساجد ليس من أصناف الزكاة الثمانية، وأما قوله سبحانه: وَفِي سَبِيلِ اللَّهِ [التوبة:60] فالمراد به: الجهاد كما هو قول جمهور أهل العلم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10129/حكم-تعمير-المساجد-من-اموال-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_428/42808.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":11945,"question":"هل يجوز لفرد ما أن يأخذ من أموال الزكاة إذا كان عليه دين، ولا يستطيع أن يسدده؟","title":"حكم أخذ المديون العاجز عن القضاء من الزكاة","answer":"الجواب:  نعم، له أن يأخذ من مال الزكاة، له أن يأخذ من مال الزكاة ما يقضي به الدين إذا كان عاجزًا عن قضاء الدين، وليس له صرفه في غير ذلك، فإذا أخذ من إخوانه الطيبين مساعدة في قضاء دينه من الزكاة، فالواجب عليه صرف ذلك في قضاء الدين، لا في حاجاته الأخرى. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10130/حكم-اخذ-المديون-العاجز-عن-القضاء-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_428/42809.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12009,"question":"من أم علاء في البحرين رسالة وتقول فيها: والدتي متوفاة من سنوات طويلة، ولها تركة، قليل من المال والذهب، ولم تقسم تركتها إلا هذه السنة عن طريق المحكمة لخلاف الإخوة والمحكمة أيضًا، إنني لا أدري إذا كانت والدتي كانت تخرج زكاة هذا المال، مع العلم أنها جمعته مما تحصله من أولادها جميعًا، وكانت تريد بذلك أن تشتري بيتًا تسكنه بدل بيت الإيجار، ولكن قضاء الله وقدره فوق كل شيء، وسؤالي: هل يجب علينا بعد أن نستلم من المحكمة التركة، هل يجب علينا أن نزكي، أم كيف توجهوننا؟ جزاكم الله خيرًا.","title":"تركة المتوفى هل يجب إخراج الزكاة منها؟","answer":"الجواب:  ليس عليكم زكاة، إلا إذا كان أوصت بإخراج الزكاة عنها سنة، أو سنتين، أما ما دمتم لا تعلمون فليس عليكم شيء، نعم. الحمد لله، الأصل أنها زكت، والحمد لله. المقدم: الحمد لله، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10194/تركة-المتوفى-هل-يجب-اخراج-الزكاة-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_431/43123.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12091,"question":"يسألون أيضًا عن النساء المتزوجات، واللاتي لا دخل لهن سوى ما يتكرم به قريب أو زوج، هل يجوز صرف الزكاة لمثل هذا النوع من الزوجات، ولاسيما إذا كان الزوج لا يعطيها شيئًا سوى ما تأكل، أو تشرب، أو تكتسي؟ جزاكم الله خيرًا.","title":"حكم دفع الزكاة لامرأة فقيرة متزوجة","answer":"الجواب:  لا يجوز أن تعطى ذات الزوج من الزكاة، وإنما يعطى الزوج، إذا كان الزوج فقيرًا؛ يعطى ما ينفقه على زوجته، أما هي فلا تعطى؛ لأنها غنية بزوجها، وإذا كان زوجها لا يقوم باللازم؛ ففي إمكانها أن تطلب المحكمة إنصافها، أو من أوليائها حتى يناصحوه، أو من جيرانها حتى يناصحوه. المقصود: عليها أن تسعى في حل المشكلة من أي طريق، من طريق نصيحة الجيران، أو الأقارب والأصدقاء، أو فيما بينها وبينه تخوفه من الله، وتطلب منه أن يعطيها حقها، أما أن تعطى من الزكاة لا؛ لأنه كثير من النساء يتساهلن في هذا الأمر، قد تطلب من الزكاة وهي تلعب بالمال، وعندها ما يكفيها، أو تشتري بها أشياء، حاجات أخرى لا ضرورة إليها. المقصود: أن الزكاة لا تدفع للزوجة ما دام عندها زوج هو المسؤول عنها، لكن إذا كان فقيرًا يعطى هو وهو الذي ينفق على زوجته، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10276/حكم-دفع-الزكاة-لامراة-فقيرة-متزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_436/43605.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12092,"question":"كيف يكون صرف الزكاة للفقير، هل يعطى حتى يغتني، أو توزع على أكثر من فقير إذا كان المال المزكى يعطي مبلغًا كبيرًا هو الزكاة؟","title":"مقدار ما يعطاه الفقير من الزكاة","answer":"الجواب:  الواجب أن يعطى الفقير ما يسد حاجته سنته كلها، عامه كله، وإذا كان الفقير عنده ما يكفيه نصف السنة؛ أعطي ما يكفيه لبقية السنة، وإذا كان صاحب الزكاة لا يعرف حاله، ولكن يعلم أنه فقير؛ فيعطيه، ويكفي، يعطيه ما تيسر من الزكاة، ويكفي، أما إذا كان يعرف حاله، وعنده زكاة كبيرة يستطيع أن يعطيه ما يسده في العام؛ فإنه يعطيه ما يسده في العام، ويحرم على الفقير أن يسأل بعد ذلك، يكتفي بما أعطي، ويحرم عليه أن يسأل زكاة بعد ذلك، وهو عنده ما يكفيه من الزكاة التي وصلت إليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10277/مقدار-ما-يعطاه-الفقير-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_436/43606.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12093,"question":"إذا اجتمع أناس مثلًا وجمعوا مبلغًا معينًا من أموال الزكاة، ليشتروا بها بيتًا لأيتام فقراء، هل يجوز هذا، أو لا يجوز سماحة الشيخ؟","title":"حكم صرف أموال الزكاة في شراء بيت لأيتام","answer":"الجواب:  ما في مانع، يشترون به بيتًا، أو يستأجرون به بيتًا للأيتام؛ لا بأس، نعم؛ لأن الحاجة ماسة إلى السكن، نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10278/حكم-صرف-اموال-الزكاة-في-شراء-بيت-لايتام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_436/43607.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12119,"question":"من الإمارات العربية المتحدة رسالة بتوقيع إحدى المستمعات تقول: (هـ. أ. أ) مصرية، أختنا بعثت بثلاث رسائل دفعة واحدة،، ولكن لرداءة خطها لم أستطع إلا فهم هذا السؤال، تقول: إنها تعطي جزءًا من راتبها كزكاة لأقاربها، فهل يجزئ ذلك، أو لا؟ جزاكم الله خيرًا؟","title":"حكم صرف الزكاة في الأقربين","answer":"الجواب:  إذا كان أقاربها فقراء؛ فلا بأس، الزكاة تجزئ فيهم، إذا كانوا ليسوا من عمودي النسب، ليسوا من آبائها وأجدادها، ولا من أمهاتها وجداتها، وليسوا من أولادها، وأولاد أولادها؛ فلا بأس، الإخوة والأعمام والأخوال وبني العم، وبني الخال، ونحو ذلك، إذا كانوا فقراء، وأعطتهم الزكاة؛ فهذه صدقة وصلة طيب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10304/حكم-صرف-الزكاة-في-الاقربين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_438/43804.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12324,"question":"المستمع مصطفى شلبي إبراهيم من أبها بعث يسأل عن السيارة الخاصة، هل يؤدى عنها زكاة، وعن سيارة الأجرة أيضًا، جزاكم الله خيرًا.","title":"حكم زكاة السيارات المتخذة للاستعمال وللأجرة","answer":"الجواب:  السيارة الخاصة للاستعمال، وسيارات الأجرة ليس فيهما زكاة، لكن الأجرة إذا حال عليها الحول، وهي تبلغ النصاب يزكيها صاحبها، إذا صار عنده دراهم اكتسبها من السيارة، وحال عليها الحول، وهي تبلغ النصاب، ستة وخمسين ريالًا فضة، فأكثر، أو ما يعادلها يزكها، أما نفس السيارات .... السيارة ليس فيه زكاة؛ لأنه ما عد للبيع إنما أعد للاستعمال، والزكاة إنما تجب في العروض المعدة للتجارة للبيع، فإذا أعد السيارة للبيع؛ وجبت فيها الزكاة، وهكذا إذا أعد البيت، أو الأرض للبيع وجبت فيها الزكاة. أما إذا كان البيت معدًا للإيجار، أو السيارة للإيجار؛ فلا زكاة فيهما، لكن الأجرة إذا حال عليها الحول وهي تبلغ النصاب؛ زكيت. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10526/حكم-زكاة-السيارات-المتخذة-للاستعمال-وللاجرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_398/39813.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12341,"question":"بالنسبة للزكاة المالية أو العينية أو كل ما وجبت فيه الزكاة، مما لا شك فيه أنها تزكى كلما دار عليها الحول، ولكن هل يتوجب، أو يتعين على المزكي أن يخرج الزكاة في وقت، أو في يوم معين، يكون له الأفضيلة من أيام السنة، أو أشهر السنة، مثل شهر رمضان مثلًا؟","title":"وقت إخراج الزكاة","answer":"الجواب:  الواجب إخراج الزكاة حين يتم الحول في أي وقت، والبدار بها من حين يتم الحول، هذا هو الواجب، والتأخير اليسير يعفى عنه، وإذا تم الحول في آخر شعبان، وأخرجها في رمضان، الأمر في هذا واسع -إن شاء الله- الأيام اليسيرة، وإلا فالواجب البدار بإخراجها؛ لأنها وجبت عليه، فالتأخير قد يعرض الرجل إلى أخطار قد يموت ولا يخرجها الورثة، قد يذهب المال، إلى غير ذلك. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10545/وقت-اخراج-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_399/39904.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12369,"question":"بالنسبة لرجل لديه تجارة، وعليه ديون، هل يسدد الزكاة، أم يسدد الديون التي عليه من زكاته؟","title":"حكم الزكاة على من لديه تجارة وعليه دين","answer":"الجواب:  الواجب عليه أن يزكي، والدين يبقى في الذمة، ولا يمنع الزكاة، هذا الصواب، الذي عليه المحققون من أهل العلم الدين لا يمنع الزكاة، ولكن عليه أن يزكي الأموال التي في يده، والله يوفي عنه  لكن لو أراد أن يسدد الدين؛ فلا مانع أن يخرج الدين قبل وجوب الزكاة، قبل ميعاد الزكاة، يوفي الدين ثم يزكي الباقي. المقدم: لكن إخراج الدين من نفس الزكاة، أو من حر ماله؟ الشيخ: من نفس المال. المقدم: من نفس المال. الشيخ: يخرج الزكاة من نفس المال الذي إذا كان عنده مال آخر ... زكاة يوفيه من المال الذي عنده، إذا كان عنده ما يقابل؛ فليزكه من المال ... فالمقصود: أن هذا المال الذي للزكاة يزكي إذا حال عليه الحول، ولا يمنعه الدين، لكن لو أن هذا المال الذي أعد للزكاة مثل عروض، أو فيه زكاة قد حال عليها الحول، لو أراد أن يخرج منه قضاء الدين؛ فلا بأس، قبل أن يحول الحول مثلًا الحول يحول في رمضان، وأوفى الدين من هذا المال في شعبان، أو في رجب؛ فإنه تسقط زكاة الذي أخرج في وفاء الدين. المقدم: بارك الله فيكم، لكن كونه يسدد الدين من زكاة المال ما حكم هذا؟  الشيخ: لا يسدد من زكاة المال، .... يسدد من المال. المقدم: هو يسأل عن هذا حفظكم الله؟ الشيخ: لا. يسدد من المال الذي عنده، أما الزكاة يعطيها المستحقين، إنما التسديد من المال نفسه للغرماء إذا كان قبل حول الزكاة، زكى الباقي، أما إذا حال الحول؛ فيزكي الموجود، ولا يمنعه الدين. المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10564/حكم-الزكاة-على-من-لديه-تجارة-وعليه-دين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_400/40002.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12371,"question":"هل يجوز دفع الزكاة، أو الصدقة للإخوة الأشقاء الصغار الذين ليس لهم من يعولهم سوى أخوهم؟","title":"حكم دفع الزكاة أو الصدقة للإخوة الأشقاء","answer":"الجواب:  إن أنفق عليهم من ماله؛ فهو أحوط، إذا كان يستطيع وإلا جاز أن يعطيهم من الزكاة، جاز أن يعطيهم من الزكاة، وينفق عليهم من الزكاة، لكن إن أنفق عليهم من ماله غير الزكاة إذا كان يستطيع؛ فهو أحوط وأطيب. المقدم: بارك الله فيكم، يسأل عن النفقة هل تجب عليه جزاكم الله خيرًا؟  الشيخ: الوجوب فيه نظر، لكن إذا أنفق عليهم فهذا أطيب؛ لأنه إذا كان يرثهم، ليس لهم وارث سواه، فبعض أهل العلم يوجب عليه النفقة، لكن إذا أنفق عليهم، وتحرى حاجاتهم من غير إسراف، ولا تبذير من ماله؛ فهذا هو الأفضل له، والأحوط له، وإن أنفق عليهم من الزكاة؛ فلا حرج على الصحيح، إن شاء الله.  المقدم: الحمد لله، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10575/حكم-دفع-الزكاة-او-الصدقة-للاخوة-الاشقاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_400/40013.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12373,"question":"يقول: هل يمكن أن نقدم الزكاة بسنة أو سنتين؟","title":"حكم تقديم الزكاة","answer":"الجواب:  لا مانع إذا كان للمصلحة، تقدم الزكاة لا بأس، نعم. المقدم: بارك الله فيكم وجزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10565/حكم-تقديم-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_400/40003.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12420,"question":"مستمع بعث برسالة يقول: (ص. ع) من عرعر يقول: قمت بتجميع جزء من رواتبي، فحال عليها الحول، وصرفت جزءًا من هذا المال قبل مضي الحول، وبقي لدي جزء آخر، هل أخرج الزكاة عن المال المتبقي؟ جزاكم الله خيرًا.","title":"المجموع الذي حال عليه الحول","answer":"الجواب:  المال المتبقي الذي حال عليه الحول يجب عليك إخراج زكاته، إذا كان يبلغ النصاب أكثر من ستة وخمسين ريالًا، إذا كان يبلغ النصاب عليك أن تخرج الزكاة، وهي ربع العشر من كل ألف خمسة وعشرون، والذي أخرجته قبل أن يتم الحول ما عليه زكاة، الذي أنفقته في حاجات بيتك مثلًا، أو قضيت به دينًا قبل أن يتم الحول؛ ليس فيه زكاة، لكن الذي بقي حتى تم عليه الحول؛ عليك أن تخرج زكاته، تطلب مرضات الله، وأداء الحق الذي عليك لله سبحانه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10628/المجموع-الذي-حال-عليه-الحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_402/40216.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12421,"question":"يسأل: هل تعطى الزكاة للقريب، مثل الأخ، أو الجد، أو الخالة؟","title":"إعطاء الزكاة للأقارب","answer":"الجواب:  نعم يعطاها القريب الفقير صدقة وصلة، يقول النبي ﷺ: الصدقة على المسكين صدقة، وعلى ذي الرحم اثنتان صدقة وصلة الأخ الفقير، الخالة، العمة، ابن العم، ابن الخال، كل هؤلاء إذا كانوا فقراء يعطون. لكن لا تعطي أولادك، ولا تعطي أباك، ولا أمك، ولا جدك، ولا جدتك، هؤلاء لا، الأصول والفروع لا يعطون، تعطيهم من مالك ما هو من الزكاة، الذرية وإن كانوا فقراء تعطيهم من مالك، أو ذرية البنات تعطيهم من مالك، أو أمك، أو الأب، أو الجد، أو الجدة هؤلاء لا تعطيهم من الزكاة، تعطيهم من مالك، بارك الله فيك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10629/اعطاء-الزكاة-للاقارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_402/40217.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12453,"question":"مستمع بعث برسالة، ووقع في نهايتها بقوله: عبدالله، يقول في أحد أسئلته: ما هو رأي الإسلام في مهنة المحاماة؟ وهل كانت موجودة في عهد الصحابة والخلفاء الراشدين؟","title":"حكم العمل في مهنة المحاماة","answer":"الجواب:  المحاماة، هي: الوكالة في الخصومات، وهذه الوكالة موجودة من عهد النبي ﷺ إلى يومنا هذا، الوكيل لا بأس به، هذه تسميتها محاماة، هذا اسم جديد، فإذا كان المحامي يتقي الله، ولا يساعد صاحبه بالمنكر والكذب؛ فلا حرج عليه، الواجب عليه أن يتقي الله في محاماته، وأن يطالب بالحق، وألا يكذب، وألا يعين صاحبه على معصية الله، فإذا كان يطالب بالحق الذي يعلمه، أو يطلب من القاضي الحكم بالشرع الذي يعلمه القاضي، ولا يعلمه المحامي؛ فلا حرج عليه في ذلك.  أما أن يتعمد كذبًا، أو إعانة على كذب، أو على غش؛ فلا يجوز له، وهو آثم في ذلك وظالم، فعلى المحامي وهو الوكيل أن يتقي الله، المحامي هو الوكيل في الخصومة، فعليه أن يتقي الله، وألا يتعمد باطلًا، ولا يعين على باطل، بل يطلب لموكله الحق فقط، يقول: أنا وكيل لفلان، وأنا أطالب بالحق الذي شرعه الله، سواءً كانت الخصومة في أرض، أو في حيوانات، أو في سيارات، أو في غير ذلك، يطلب من القاضي الحكم بالحق الذي يعلمه من شرع الله، ويأتي بالبينة المطلوبة منه، ويبين ما عنده من الحقيقة؛ لا بالكذب، وإذا بين ما لديه، وصدق في ذلك، ولم يتعمد باطلًا ولا زورًا؛ فلا حرج عليه. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10658/حكم-العمل-في-مهنة-المحاماة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_456/45607.mp3","categories":["إخراج الزكاة وأهلها","الوكالة"]},{"id":12465,"question":"مستمع رمز إلى اسمه بالحروف (س. م. ع) يقول: أنا لدي عامل راعي غنم، هل يجوز أن أعطيه زكاة المال من هذه الماشية؟ أفيدوني بارك الله فيكم.","title":"حكم من أعطى زكاته لمن يعمل عنده لفقره","answer":"الجواب:  إذا كنت تعلم أنه فقير، وأن معاشه لا يكفيه، فلا مانع أن تعطيه من الزكاة، لكن إذا كنت تعطيه لأجل يبقى عندك، قد يكون معاشه قليلًا، تعطيه الزكاة حتى يرغب ويبقى؛ فلا يجوز، والأحوط أن تعطي الزكاة غيره، ويكفيه معاشه، يكفيه راتبه؛ لأني أخشى أن تكون هذه العطية من أجل بقائه لديك، فتكون نوعًا من زيادة الأجرة، فالزكاة أعطها الفقراء الذين ليس لك شبهة في إعطائهم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10662/حكم-من-اعطى-زكاته-لمن-يعمل-عنده-لفقره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_404/40403.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12526,"question":"زوجي يمر هذه السنة بظروف مادية صعبة، رغم أن راتبه جيد، ولكن عليه بعض الديون، هذا مع إيجار البيت، رغم أن الديانة لا يطالبونه بالدين، ولكني أراه مهمومًا أحيانًا، هل أعطيه زكاة ذهبي هذه السنة، أم لا يجوز ذلك، جزاكم الله خيرًا؟","title":"حكم إعطاء المرأة زكاة حليها لزوجها المديون","answer":"الجواب:  إذا كان غارمًا، وليس عنده وفاء؛ فلا بأس، إن كان عليه دين ثابت، وهو معسر بالقضاء؛ لأن الدخل حده البيت، نفقة البيت؛ فلا بأس أن تعطيه زكاتك، هذا هو الصواب، هذا هو الحق، لا بأس أن تعطي زوجك زكاتك إذا كان فقيرًا، أو غارمًا، عليه دين، ليس له قضاء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10730/حكم-اعطاء-المراة-زكاة-حليها-لزوجها-المديون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_408/40809.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12630,"question":"رسالة وصلت إلى البرنامج من جدة، وباعثها مستمع رمز إلى اسمه بالحروف: (ع. ع. ح. ش) يقول: يوجد طالب علم وداعية إلى الله، وهو يريد أن يتفرغ لطلب العلم والدعوة إلى الله، لكنه يشتغل عند أحد التجار بأجر شهري؛ لأنه ليس عنده ما يصرف منه على نفسه، وعلى عائلته، وقد اتفقت معه على أن أعطيه راتبًا شهريًا نصفه من الزكاة، ونصفه من رأس المال على أن يدع العمل، ويتفرغ لطلب العلم، والدعوة إلى الله، ويكون أجر الدعوة إلى الله بيننا مشتركًا، هل هذا العمل صحيح؟ وجهونا، جزاكم الله خيرًا.","title":"حكم إعطاء طلبة العلم من أموال الزكاة","answer":"الجواب:  نعم نعم، هذا العمل صحيح وطيب، وأنت مأجور، وهو مستحق للزكاة، وإذا تفرغ الإنسان لطلب العلم، وليس عنده ما يقوم بحاله؛ فإنه يعطى من الزكاة ما يقوم بحاله، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، بالنسبة لكون الأجر مشترك؟ الشيخ: كله على حسب نفقته، الحمد لله، إذا كان أنصاف النفقة أنصاف، الحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10840/حكم-اعطاء-طلبة-العلم-من-اموال-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_415/41504.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12631,"question":"أعمل في التجارة مستمع آخر هو: ناصر محمود حامد اندجاني يقول: أعمل في التجارة، فهل أقوم بإخراج الزكاة عن رأس مالي، أم أنني أخرج الزكاة عن رأس المال، والأرباح سويًا، علمًا بأن هذه الأرباح لم يمض عليها الحول؟","title":"حكم إخراج الزكاة من الأرباح التي لم يحل عليها الحول","answer":"الجواب:  الواجب على التاجر أن يزكي الأموال التي عنده، التي يقصد بها التجارة وأرباحها، يزكيها ويزكي أرباحها، وإن لم يحل الحول على الأرباح؛ لأن الربح تابع للأصل، فإذا كان الأصل -مثلاً- عشرة آلاف وربحت في آخر الحول قبل تمام الحول ألفًا، فصارت أحد عشر ألفًا؛ يزكي الجميع، الأصل والربح، كما أن نتاج الإبل والبقر والغنم يتبعها. فإذا كان عنده -مثلاً- تسعًا من الإبل، ونتجت منها واحدة؛ صارت عشرًا قبل تمام الحول؛ وجب عليه شاتان؛ لأنه تم النصاب قبل تمام الحول بهذا النتاج الجديد، فوجب عليه شاتان؛ لأنه في كل خمس شاة. فالمقصود: أن الربح يتبع الأصل، إذا كان فيه زكاة يتبعه الربح، وهكذا الإبل والبقر والغنم إذا كان الأصل فيه الزكاة يتبعها النتاج، ولا يحتاج إلى حول جديد. أما الأشياء التي ليست للتجارة، بل هي أدوات تستعمل في التجارة، كالميزان والأشياء التي لا تباع إنما هي موجودة للحاجة إليها، كالدكان نفسه الحانوت، والأدوات التي يفرشها، أو يجلس عليها، أو الميزان، أو ما أشبه ذلك من الأشياء التي ليست للربح، ولا للتجارة، هذه ليس فيها زكاة، إنما الزكاة في السلع المعدة للبيع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10841/حكم-اخراج-الزكاة-من-الارباح-التي-لم-يحل-عليها-الحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_415/41505.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12634,"question":"المستمع (أ. ع. ل) يقول: لي صديق اشترى بيتًا له، وكلفه مبلغًا من المال، وصل إلى ثلاثمائة ألف، أو يزيد، ولكنه لم يستطع تسديد المبلغ بالكامل، فقد بقي مدينًا قرابة الخمسين ألفًا، فهل يحق أن يأخذ من الزكاة التي تأتي من المسلمين، مع العلم أنه يملك أرضًا وبيته القديم؟","title":"حكم الزكاة على من يملك بيتاً وأرضاً وعليه دين","answer":"الجواب:  إذا كان اشترى البيت الجديد للتجارة، أو لمزيد الدنيا، وعنده بيت يكفيه؛ فلا يستحق الزكاة، بل يبيع بيته الجديد، ويوفي ما عليه من الدين، أو يلتمس ذلك من جهات أخرى؛ لأنه ليس فقيرًا ما دام عنده السكن، فإنه يبيع هذا البيت، ويسدد ما عليه من الدين، ويستعمل الباقي في حاجاته، ولا يسمى فقيرًا، وعنده أرض، وعنده هذا البيت الجديد، وعنده السكن. الزكاة لابد أن يكون صاحبها فقيرًا، ليس عنده ما يقوم بحاله ويغنيه عن الزكاة، أما إذا كان عنده ما يغنيه من كسب يسد حاجته، أو وظيفة تسد حاجته، أو أموال يستطيع أن يبيع منها ويسد حاجته؛ فلا يعطى، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10844/حكم-الزكاة-على-من-يملك-بيتا-وارضا-وعليه-دين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_415/41508.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12724,"question":"من البحرين الأخت المستمعة (ن. ج. ق) بعثت تسأل وتقول: هل يجوز إعطاء الزكاة للمسلمين خارج البلد الذي نعيش فيه، مثل مكة والمدينة أثناء الحج، أو العمرة، أو هل يجوز إرسالها إلى منكوبي الجفاف، أو إلى مجاهدي أفغانستان وفلسطين وغيرهم؟","title":"حكم إخراج الزكاة في غير بلد المزكي","answer":"الجواب:  فقراء البلد أولى؛ لأنهم في حاجة إليها، والرسول -عليه الصلاة والسلام- قال: تؤخذ من أغنيائهم، فترد لفقرائهم ولأنها مواساة، فالغني يواسي فقيره الذي عنده في بلده، فإذا كان الفقراء في البلد قليلين، وقد حصل لهم ما يكفي؛ فلا مانع من نقلها إلى بلاد أخرى، كالمجاهدين الأفغان، والمجاهدين في داخل فلسطين، وغير ذلك، أو كان له أقارب حاجتهم شديدة، فنقلها إليهم، أو فقراء يعرف عنهم أن حاجتهم شديدة، أشد من حاجة فقراء البلد؛ فلا حرج في ذلك، وإلا فالأصل أن فقراء البلد هم أولى. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10937/حكم-اخراج-الزكاة-في-غير-بلد-المزكي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_460/46012.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12830,"question":"من أعطى زكاته إلى أخيه، أو أبناء أخيه، وهم في حاجة، وعليهم دين، وهما لا يشاركون المزكي، هل يجوز، أم لا؟","title":"حكم إعطاء الزكاة للأخ أو أبناء الأخ الفقراء","answer":"الجواب:  نعم إذا أعطى أخاه أو أولاد أخيه وهم فقراء لا بأس إذا كانوا مستقلين ليسوا شركاء له، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11044/حكم-اعطاء-الزكاة-للاخ-او-ابناء-الاخ-الفقراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_463/46318.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12934,"question":"سماحة الشيخ هذا سائل من الرياض رمز لاسمه بـ (ع. أ. أ) يقول: رجل لديه أموال طائلة، ولا يزكي عليها لعدة سنوات وأكثر من عشر سنوات، لم يزك عليها، وعندما نصحناه قلنا: زك هذه الأموال، قال: سأزكي عليها بعد كل خمسة عشر سنة، ونرجو منكم التوجيه في هذا؟","title":"عقوبة من يتكاسل عن إخراج زكاة أمواله","answer":"الجواب:  هذا منكر لا يجوز، فالواجب على المسلم أن يزكي كل سنة، ولا يجوز التأخير لا سنتين ولا أكثر، يجب أن يزكي عند نهاية كل عام عن جميع الأموال التي عنده من الذهب والفضة وعروض التجارة، وهكذا إذا كان يزرع؛ يزكي زكاة الزرع .. زكاة التمور، زكاة العنب، كل سنة في سنتها إذا بلغت النصاب، هذا هو الواجب؛ لأن الله قال -جل وعلا-: وَآتُوا حَقَّهُ يَوْمَ حَصَادِهِ [الأنعام:141] قال: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ [البقرة:43] هذه للفورية، أقيموا الصلاة في وقتها، وآتوا الزكاة في وقتها. وأخبر -جل وعلا- أن الذين يكنزون الذهب والفضة، ولا ينفقونها في سبيل الله أنهم موعودون بالعذاب الأليم، قال -جل وعلا-: وَالَّذِينَ يَكْنِزُونَ الذَّهَبَ وَالْفِضَّةَ وَلا يُنفِقُونَهَا فِي سَبِيلِ اللَّهِ فَبَشِّرْهُمْ بِعَذَابٍ أَلِيمٍ  ۝  يَوْمَ يُحْمَى عَلَيْهَا فِي نَارِ جَهَنَّمَ فَتُكْوَى بِهَا جِبَاهُهُمْ وَجُنُوبُهُمْ وَظُهُورُهُمْ هَذَا مَا كَنَزْتُمْ لِأَنفُسِكُمْ فَذُوقُوا مَا كُنتُمْ تَكْنِزُونَ [التوبة:34-35] هذا جزاء من بخل بالزكاة، ولم يخرج حقها، كل مال لا تؤدى زكاته؛ فهو كنز، يعذب عليه صاحبه يوم القيامة. وفي الحديث الصحيح: «أن الذين لا يؤدى الزكاة يوم القيامة يعذبون، تحمى عليهم تلك الأموال من الذهب والفضة، وما يقوم مقامها، فيعذبون بها، في يوم كان مقداره خمسين ألف سنة، حتى يقضى بين الناس، ثم يرى سبيله إما إلى الجنة وإما إلى النار، وصاحب الإبل والبقر والغنم يبطح لها بقاع قرقر تمر عليه تطؤه بخفافها وأظلافها، الإبل بخفافها، والبقر والغنم بأظلافها، تنطحه البقر والغنم بقرونها، وتعظه الإبل بأفواهها، كلما مرت عليه أخراها؛ عادت عليه أولاها في يوم كان مقداره خمسين ألف سنة» هذا جزاؤه، نسأل الله العافية. فالواجب على من كان عنده مال زكوي أن يخرج الزكاة كل سنة، وعلى هذا الشخص أن يتوب إلى الله، وأن يخرج الزكاة عما مضى من السنين، عليه التوبة والندم والإقلاع والاستغفار والبدار بإخراج الزكاة عن السنوات الماضية، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11150/عقوبة-من-يتكاسل-عن-اخراج-زكاة-امواله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_501/50109.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":12989,"question":"يسأل سؤاله الأخير ويقول: هل يجوز دفع زكاة المال على الخدم لإرسالها لأهلهم وأقاربهم؟","title":"حكم إعطاء الزكاة للخادم","answer":"الجواب:  هذا فيه تفصيل: إذا كنت تعرف الخادم، وأنه فقير، وأن أهله فقراء، وعندك يقين في هذا لا بأس، إذا كان مسلمًا، وأهله مسلمون. أما الخدم الذين لا تعرف حالهم، ولا حال أهلهم فلا، الواجب أن تلتمس الفقراء المعروفين بالإسلام حتى تدفع إليهم على بصيرة في بلدك، والخادم تكفيه أجرته، والحمد لله. لكن لو تيقنت أنه فقير، وأن الأجرة ضعيفة، وأن لديه عائلة، أو والدان فقراء، وهم مسلمون... هذا شيء لا شك فيه؛ فلا مانع أن يعطى من الزكاة بشرط أن لا تكون وقاية لمالك؛ حتى لا تزيد في الأجرة؛ حتى لا يطالبك بأجرة زيادة، نعم. المقدم: جزاكم الله خيرًا، سماحة الشيخ! من المعروف أن الخدم إذا نالوا شيئًا من الزكاة تتحسن خدماتهم، فما هو توجيهكم لو سمحتم؟ الشيخ: إذا لم يكن شرطًا؛ فلا بأس، وإن خاف؛ فيعطيها غيرهم، يعطيها غيرهم؛ احتياطًا لدينه.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11207/حكم-اعطاء-الزكاة-للخادم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_470/47014.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":13012,"question":"تقول في سؤال آخر: لدي مبلغ مدخر، وقدره عشرة آلاف ريال، وتمام الحول يكون شوال أي: بعد رمضان، ولكن لدي الرغبة في أن أخرج زكاته في رمضان، فهل يجوز ذلك، وكم أخرج زكاة العشرة الآلاف؟ وهل أخرج قيمة الزكاة من راتبي، أم من نفس المبلغ؟ أرجو الإفادة، جزاكم الله عني وعن المسلمين خيرًا.","title":"حكم تعجيل الزكاة وما مقدارها؟","answer":"الجواب:  تعجيل الزكاة لا بأس به، تعجيل الزكاة للمصلحة لا بأس، فإذا كان الحول يتم في شوال، وأحب المسلم أن يخرج الزكاة في رمضان؛ فلا حرج في ذلك، لأجل فضل رمضان، أو صادف فقراء حاجتهم شديدة قبل تمام الحول، فعجل لهم الزكاة، أو عجلها للمجاهدين، كل هذا طيب، وما أشبهه، ولا بأس بذلك. والواجب في عشرة الآلاف ربع العشر مثل غيرها، الواجب ربع العشر، ففي العشرة الواجب مائتان وخمسون؛ لأن عشرها ألف وربع الألف مائتان وخمسون، هذه زكاة العشرة الآلاف، وفي الألف الواحد خمسة وعشرون، وفي المائة اثنان ونص، فالزكاة ربع العشر. ولا يجب إخراجها من نفس المال، فإذا أخرجت الزكاة من راتبك، أو من مال آخر؛ فلا حرج، ليس إخراج الزكاة من نفس المال المحفوظ في بنك، أو غيره لازمًا لا، إذا أخرج الزكاة من مال آخر، أو من راتبه؛ فلا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11229/حكم-تعجيل-الزكاة-وما-مقدارها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_471/47108.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":13037,"question":"الواقع تطرقتم إلى الزكاة سماحة الشيخ، وأخونا يسأل عنها يقول: هل يجوز إعطاء الزكاة للمساجد؟","title":"حكم دفع الزكاة في بناء المساجد","answer":"الجواب: لا، تصرف في غير المساجد، تبنى من غير الصدقات، لكن يصرف الزكاة في أهلها، في الفقراء، في المجاهدين في أبناء السبيل، في عتق الرقاب، في فك أسرى المسلمين، في الغارمين المدايين المحتاجين العاجزين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11254/حكم-دفع-الزكاة-في-بناء-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_472/47217.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":13041,"question":"المستمعة (زهرة . ح. ج) تقول: سماحة الشيخ! هل يجوز أن أخرج زكاة ذهبي لزوجي الذي عليه ديون كثيرة، أفتوني مأجورين؟","title":"حكم إخراج المرأة زكاتها لزوجها المدين","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فلا حرج في إعطاء الزوج الزكاة إذا كان فقيرًا، لا حرج في ذلك على الصحيح من أقوال العلماء، إذا كان فقيرًا؛ يعطى الزكاة من زوجته، نعم. المقدم: وإذا كان عليه ديون يا شيخ؟ الشيخ: إذا كان عليه ديون لا يقضيها فهو فقير، إذا كان عليه ديون عاجز عن قضائها؛ فهو غارم فقير، نعم يعطى الزكاة.","link":"https://binbaz.org.sa/fatwas/11258/حكم-اخراج-المراة-زكاتها-لزوجها-المدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_505/50501.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":13139,"question":"تقول هذه السائلة: هل يجوز إخراج الزكاة على مؤخر صداق المرأة، علمًا بأنها لا تستطيع أن تطالب الزوج بهذا الصداق؟ ومن الذي يجب عليه إخراج الزكاة في مثل هذه الحالة يا سماحة الشيخ؟","title":"حكم إخراج الزكاة عن مؤخر الصداق","answer":"الجواب:  ليس عليها زكاة؛ لأن هذا الدين غير مقدور عليه، ليس في قدرتها، فهو مثل الدين الذي على المعسر، ليس في قدرة صاحبه الحصول عليه، ومثله المال الضائع لا زكاة فيه، أما الدين المؤجل الذي يقدر عليه صاحبه عند الأجل؛ فهذا يزكى، إذا كان على مليء.  أما الصداق المؤجل الذي لا تستحقه إلا بالفراق؛ فليس عليها زكاة له؛ لأنها لا تقدر على قبضه الآن، ولا في وقته الحقيقي؛ لأنه أمر مؤجل، لا يدرى متى يحصل، نعم.","link":"https://binbaz.org.sa/fatwas/11393/حكم-اخراج-الزكاة-عن-موخر-الصداق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_510/51003.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":13203,"question":"يقول هذا السائل: أعطيت شخصًا خمسين ألف ريال للاستثمار، وكانت هذه أول مرة أتعامل معه، فلم أكن متأكدًا ما إذا كنت سآخذ هذه الأموال، أم لا، وظلت هذه النقود عنده لمدة عامين، ثم أخذتها منه دون زيادة، أو نقصان، فهل أخرج الزكاة عن العامين السابقين، أم أستقبل بهما عامًا جديدًا؟","title":"حكم الزكاة عن المال إن كان مقروضاً","answer":"الجواب:  عليك إخراج زكاتها عن العامين؛ لأنها في ملكك، وهي عندك كالأمانة؛ لأنه لم يعمل فيها شيئًا؛ فهي كالأمانة، بس عليك زكاتها، نعم، أما لو عمل فيها، وربحت؛ عليك زكاتها، وزكاة الربح، لكن مادامت بقيت عنده، ولم يعمل شيئًا؛ فهي مثل الوديعة تزكيها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11474/حكم-الزكاة-عن-المال-ان-كان-مقروضا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_512/51208.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":13265,"question":"هذا سائل للبرنامج يقول: أرجو التكرم بالإجابة على سؤالي: هل يجوز أن أعطي والدي وأخي من زكاة مالي، مع العلم بأنه يوجد عندهم أرض زراعية تنتج محصولًا كل ستة شهور، ولكن في وسط الستة شهور يكونون في احتياج لبعض المصاريف، فهل أعطيهم زكاة من مالي، أم أعطيهم جزءاً منه، وأوزع الباقي على بعض الأقارب، والمحتاجين؟","title":"حكم إخراج الزكاة للوالد والأخ","answer":"الجواب: أما أبوك لا، لا تعطيه، تعطيه من مالك، لا تعطيه الزكاة، عليك أن تعطيه من مالك، تنفق عليه من مالك إذا كان محتاجًا، لا من الزكاة، وأما أخوك فيه تفصيل: إن كان في بيتك، وتنفق عليه؛ فلا تعطه من الزكاة، أما إن كان مستقلًا، وهو محتاج فقير؛ تعطيه من الزكاة. أما الأب والجد والأم والجدة والأولاد فإنك لا تعطيهم من زكاتك؛ لأنهم أنت وإياهم شيء واحد، الزكاة لغيرهم، ولو غضبا، توضح لهما، تبين لهما أن هذا أمر الله، وهذه عبادة لله -عز وجل- فتستسمحهما حتى يسمحا، ويأذنا في إعطاء الزكاة لغيرهما. فالمقصود: أن والديك تنفق عليهما من مالك، والزكاة لغيرهما، أما الأخ ففيه تفصيل: إذا كان في بيتك، وفي نفقتك؛ لا بأس، تنفق عليه من مالك، ولا تعطيه زكاة؛ لأنك قد كفيته المؤنة، فالواجب أن تعطيه من مالك؛ لأنه من تبع عيالك، أما إذا كان مستقلًا، وفقيرًا؛ فلا بأس أن تعطيه من الزكاة. نعم.","link":"https://binbaz.org.sa/fatwas/11549/حكم-اخراج-الزكاة-للوالد-والاخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_514/51405.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":13401,"question":"هذا السائل أبو مازن من الإمارات العربية المتحدة له سؤالان: السؤال الأول يقول: بأنه شاب مقتدر، وله عقارات كثيرة وغيرها، هل يجوز أن يعطي من زكاة ماله لوالده ووالدته؟","title":"حكم إعطاء الزكاة للوالدين","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فليس للرجل ولا للمرأة دفع الزكاة إلى والديهم، وإلى أولادهم، وإنما تدفع للأقارب الآخرين إذا كانوا فقراء، وليسوا في حوزته، وليسوا في نفقته تكون صدقة وصلة، أما دفعها لوالديه، أو أولاده، أو أولاد بناته؛ فليس له ذلك، بل يجب عليه أن ينفق عليهم من ماله إذا احتاجوا له، وأما إعطاؤهم من الزكاة فلا، لكن إذا كان له أخ فقير، أو عم، أو خال فقير، وليس في بيته من ينفق عليهم؛ فلا بأس أن يعطيهم من زكاته. نعم.","link":"https://binbaz.org.sa/fatwas/11690/حكم-اعطاء-الزكاة-للوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_526/52601.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":13402,"question":"السائل أبو مازن يقول: كنت لا أخرج الزكاة لسنوات كثيرة، فتبت إلى الله  ولا أعرف عدد السنوات، ومالي وعقاري كثير، كيف السبيل لإخراج ما مضى؟ وكيف الطريق إلى التوبة؟ جزاكم الله خيرًا.","title":"كيفية التوبة لمن امتنع عن إخراج الزكاة لعدة سنوات","answer":"الجواب: الطريق للتوبة الندم على الماضي، والعزم ألا تعود فيه، والإقلاع من ذلك، والمبادرة بإخراج الزكاة عما مضى، تتحرى الماضي، وتخرج الزكاة عما مضى، تتحرى، وتجتهد إذا كنت تظن أنها خمسًا؛ تزكي خمسًا، تظنها ستًا؛ تزكي ستًا، وهكذا، تتحرى السنوات الماضية التي لم تزك؛ فتخرج زكاتها عن المال الذي عندك، مع التوبة، والندم، والإقلاع، والعزم ألا تعود في ذلك، والإكثار من العمل الصالح. والله سبحانه يقول: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82] ويقول سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] وإذا تاب الإنسان غفر الله له ما سلف، وحفظ له ما تقدم من الخير، الخير السابق يحفظ له، والسيئات تغفر بتوبته الصادقة، وأعماله الصالحة. نعم.","link":"https://binbaz.org.sa/fatwas/11692/كيفية-التوبة-لمن-امتنع-عن-اخراج-الزكاة-لعدة-سنوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_526/52602.mp3","categories":["إخراج الزكاة وأهلها"]},{"id":13423,"question":"هذا سائل للبرنامج (عبدالرحمن أ. أ) يقول: هل تعتبر كفالة الأيتام من مصارف الزكاة سماحة الشيخ؟","title":"هل اليتيم من مصارف الزكاة؟","answer":"الجواب: إذا كان اليتيم فقيرًا هو من مصارف الزكاة، داخلة في الفقراء والمساكين، إذا كان فقيرًا ما خلف له والده ما يقوم بحاله، ولا عنده من ينفق عليه من أقاربه يعطى، أما إذا كان له مال اليتيم ينفق عليه منه، ما يعطى من الزكاة.","link":"https://binbaz.org.sa/fatwas/11717/هل-اليتيم-من-مصارف-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_527/52703.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":13435,"question":"كيف يؤدي المرء زكاة ماله إذا كان راتبه مثلًا سبعمائة ريال شهريًا؟","title":"كيف تُخرج زكاة الراتب؟","answer":"الجواب: إذا كان هذا الراتب يصرف لحاجاته، ولا يبقى عنده شيء؛ ما عليه زكاة، أما إذا كان يحفظه؛ لأنه في بيت ينفق عليه كأبيه، أو غيره، ويحفظ هذه الرواتب؛ فإنه يزكيها كلما حال الحول، فإذا حال الحول على راتب رمضان؛ زكاه في رمضان المقابل، وإذا حال الحول على راتب شوال؛ زكاه في شوال، وإذا حال الحول على راتبه في ذي القعدة؛ زكاه في ذي القعدة، وهكذا، كل راتب يزكى في الحول الذي يقابل حوله، يعني: عند تمام السنة، فإن زكى المتأخر مع المتقدم، وعجل زكاة المتأخر مع المتقدم؛ كان له فضل في ذلك، ولا بأس. مثلًا أخرج زكاة شوال مع زكاة رمضان، أو أخرج زكاة ذي القعدة وشوال مع زكاة رمضان عجلها، هذا طيب، ومجزئ، ولا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11731/كيف-تخرج-زكاة-الراتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_477/47714.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":13670,"question":"هذه السائلة أم عبدالله من الرياض تقول في هذا السؤال بأنها تبيع البخور للنسوة، وهؤلاء النسوة اللاتي أبيع لهن البخور يخرجن متعطرات ومتبخرات، فهل علي إثم في بيعي لهن هذا البخور؟ أرجو الإفادة.","title":"حكم بيع البخور لمن يُعلم خروجهن متبخرات","answer":"الجواب: إذا كنت تعلمين أن هؤلاء يفعلن ذلك لا تبيعي عليهن، إذا كنت تعلمين أنهن يطيبن في خروجهن في الأسواق؛ فلا تفعلي؛ لأن الله يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ [المائدة:2].  فإذا كنت تعلمين أن هذه المرأة التي تشتري منك العود، أو غيره من الطيب، تتبرج به في الأسواق، أو عند الأجانب، هذا لا يجوز؛ لأنك في هذه الحالة تعينينها على المعصية، أما إذا كنت لا تعلمين؛ فلا حرج عليك أن تبيعي على النساء، وغير النساء، أما إذا علمت أن فلانة بنت فلان التي تشتريها منك أنها تفعل هذا الفعل؛ لا تبيعي عليها. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12014/حكم-بيع-البخور-لمن-يعلم-خروجهن-متبخرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_529/52913.mp3","categories":["إخراج الزكاة وأهلها","البيوع","قضايا المرأة"]},{"id":13757,"question":"من الرياض السائل: (أ. أ) يقول: هل يجوز إسقاط الدين، واحتسابه من الزكاة؟","title":"حكم إسقاط الدين واحتسابه من الزكاة","answer":"الجواب: لا، ليس له إسقاطه واحتسابه من الزكاة، ولكن ينظر المعسر، ينظره، وإذا أعطاه من الزكاة لأجل عسره، وفقره؛ لا بأس، أما إسقاطه الدين عن الزكاة، لا، الزكاة إعطاء، ليست إسقاطًا، فلا يقي ماله بإسقاط الدين عن المعسرين، ولكن يجب عليه أن يمهلهم، وإذا أسقطهم تبرعًا ومساعدة، لا زكاةً؛ فلا بأس. المقدم: إذا اشترط عليه -سماحة الشيخ- أن يعطيه من الزكاة بشرط أن يسدد الدين الذي عليه؟ الشيخ: ما يصلح.  المقدم: ما يصلح.  الشيخ: لا، يعطيه ولا يشترط، يعطيه من الزكاة لفقره، وإن أعطاه، ردها إليه من دون شرط، أوفاه مما أعطاه؛ فلا بأس، أما يقول: أعطيك تعطيني، لا، ما يصح، هذا كالإسقاط. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12133/حكم-اسقاط-الدين-واحتسابه-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53526.mp3","categories":["السلف والقرض","إخراج الزكاة وأهلها"]},{"id":13762,"question":"من الرياض السائل: (أ. أ) يقول: هل يجوز إسقاط الدين، واحتسابه من الزكاة؟","title":"حكم إسقاط الدين واحتسابه من الزكاة","answer":"الجواب: لا، ليس له إسقاطه واحتسابه من الزكاة، ولكن ينظر المعسر، ينظره، وإذا أعطاه من الزكاة لأجل عسره، وفقره؛ لا بأس، أما إسقاطه الدين عن الزكاة، لا، الزكاة إعطاء، ليست إسقاطًا، فلا يقي ماله بإسقاط الدين عن المعسرين، ولكن يجب عليه أن يمهلهم، وإذا أسقطهم تبرعًا ومساعدة، لا زكاةً؛ فلا بأس. المقدم: إذا اشترط عليه -سماحة الشيخ- أن يعطيه من الزكاة بشرط أن يسدد الدين الذي عليه؟ الشيخ: ما يصلح.  المقدم: ما يصلح.  الشيخ: لا، يعطيه ولا يشترط، يعطيه من الزكاة لفقره، وإن أعطاه، ردها إليه من دون شرط، أوفاه مما أعطاه؛ فلا بأس، أما يقول: أعطيك تعطيني، لا، ما يصح، هذا كالإسقاط. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12133/حكم-اسقاط-الدين-واحتسابه-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53526.mp3","categories":["السلف والقرض","إخراج الزكاة وأهلها"]},{"id":13778,"question":"نرجو الإفادة عن زكاة المال، وإذا أمكن إيراد ذلك بالجنيه المصري؟","title":"نصاب زكاة المال","answer":"الجواب: زكاة المال ربع العشر في الذهب والفضة وما يقوم مقامهما من العمل، الواجب في النقدين -الذهب والفضة- ربع العشر، والنصاب في الفضة مائة وأربعون مثقالًا، وفي الذهب عشرون مثقالًا وما يقوم مقام هذه المثاقيل، هذا أقل نصاب، والواجب على من عنده مال يبلغ النصاب إخراج ربع العشر سواء كان جنيه مصري أو إسترليني أو دولار أو عملة سعودية أو غير ذلك الواجب ربع العشر؛ في المائة اثنان ونص.. في المائتين خمسة.. في الألف خمسة وعشرون، هذه الزكاة الواجبة.. وهكذا كلما زاد زادت الزكاة وهي ربع العشر، يعني: سهم من أربعين. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12145/نصاب-زكاة-المال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_601/60105.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":13816,"question":"السائل حازم من الأردن يقول في هذا  هل يجب إخراج الزكاة عن السيارة التي تحت تصرفي، وكيف يكون ذلك؟","title":"حكم إخراج الزكاة عن السيارة","answer":"الجواب:  إذا كانت السيارة للبيع تخرج الزكاة، إذا كانت للبيع والتصرف والفائدة، أما إذا كانت لا، للاستعمال ما فيها زكاة، تستعملها في حاجاتك ما فيها زكاة، أما إذا تشتري السيارات تطلب الفائدة فهذه فيها الزكاة، اعتبارًا بأصل الدراهم التي عندك، إذا كانت الدراهم عندك مثلًا من محرم واشتريت السيارات في صفر أو في ربيع إذا جاء دور الدراهم محرم تزكي السيارات، بعد تعرف قيمتها.\nالمقصود: أن السيارات التي تشترى للبيع والشراء والفائدة تزكى، أما إذا كان شراؤها للاستعمال فليس فيها زكاة. نعم.\nالمقدم: شكر الله لكم سماحة الشيخ، وبارك الله فيكم وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/12181/حكم-اخراج-الزكاة-عن-السيارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_536/53625.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":13952,"question":"تقول أختنا: أنا فتاة مؤمنة ولله الحمد لي أخ متزوج ووالده هو الذي يصرف عليه؛ لأن أخي هذا لا يزال يدرس في الثانوية والمصروف الذي يعطيه والده قد لا يكفيه، فهل يجوز لي أن أدفع له الزكاة؟","title":"هل يجوز دفع الزكاة للأخ؟","answer":"الجواب: ليس لك أن تدفعي له الزكاة بل عليه أن يطالب أباه بحاجته أو يقتصد؛ لأن هذا قد يفضي إلى تساهل أو إسراف، فينبغي في مثل هذا إرشاده إلى الاقتصاد أو سؤال أبيه باللطف والكلام الطيب الزيادة التي يحتاجها، أما أنت فادفعي الزكاة إلى من تعرفي أنه محتاج وفقير ولا تتساهلي فيها، والولد في إمكانه أن يتصل بأبيه ويطلب منه الزيادة أو يقتصد في النفقة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12362/هل-يجوز-دفع-الزكاة-للاخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_604/60410.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":14066,"question":"المستمع محمد شريف محمد من الخبر الجنوبية بعث برسالة ضمنها جمعًا من الأسئلة، في أحد أسئلته يقول: هل يجوز أن نعطي للعمال القادمين إلى المملكة زكاة أموالنا وزكاة أبداننا أم لا يجوز؟","title":"حكم دفع الزكاة لمن يعمل لدى المزكي","answer":"الجواب: إذا عرفت أنهم فقراء ومحتاجون وأن الرواتب التي لهم قليلة لا تقوم بحالهم وحال عوائلهم وهم مسلمون لا بأس أن تعطيهم من الزكاة، زكاة المال وزكاة الفطر، أما إن كنت لا تعرف أحوالهم، أو تشك هل رواتهم تكفيهم أو لا تكفيهم فلا تعطهم، أعط غيرهم ممن تعرف أنهم فقراء ولا تخاطر بمالك لا تخاطر بزكاتك، أما إذا عرفت أنهم فقراء وأنهم من أهل الصدق، وأنهم محتاجون رواتبهم لا تكفيهم لكثرة عوائلهم، وظهر له منهم الصدق والاستقامة وصلاح الأحوال فلا بأس إذا اطمأننت إليهم أن تعطيهم، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12494/حكم-دفع-الزكاة-لمن-يعمل-لدى-المزكي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_484/48407.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":14074,"question":"المستمع عيسى أحمد عبد الكريم يذكر في رسالة بعث بها أن لديه مبلغ عشرة آلاف ريال سعودي، ويريد أن يخرج زكاتها، لكنه لا يعرف كيف يخرجها، وهل يجوز أن يبقيها حتى يرجع إلى بلده ويخرج زكاتها هناك؟ أم لا يجوز ذلك؟ وفقكم الله.","title":"مقدار الزكاة في المال وحكم تأخير إخراجها","answer":"الجواب: الواجب على المسلم البدار بإخراج الزكاة، إذا حال الحول يجب أن يبادر في أي محل كان، ويلتمس الفقراء والمحاويج، ويسأل عنهم أهل الثقة والأمانة في بلده الذي هو فيه، ثم يخرج الزكاة، سواء كان في اليمن أو في الشام أو في مصر أو في الجزيرة أو في أي مكان، الله أوجب عليه إخراج الزكاة. وإذا كان المال عشرة آلاف؛ فالزكاة مائتان وخمسون، ربع العشر؛ لأن الألف هو العشر وربعه مائتان وخمسون، فيلتمس بعض الفقراء، ويدفع إليه الزكاة، ويستعين في ذلك بأهل الثقة والأمانة من أصحابه وإخوانه؛ حتى يدلوه على الفقراء ويرشدوه إليهم، فإن لم يتيسر له الفقراء؛ أرسلها إلى من يعرفهم من الفقراء في بلاده، أو في بلاد أخرى، بواسطة الثقات الذين يؤدونها إلى الفقراء والمحاويج، ولا يتساهل ولا يؤجل، بل يبادر بإخراجها في وقتها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12512/مقدار-الزكاة-في-المال-وحكم-تاخير-اخراجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_609/60908.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":14209,"question":"في ثاني أسئلته يقول: من هم الذين لا تجب لهم الزكاة أو الصدقة حتى ولو كانوا محتاجين؟","title":"بيان الذين لا يعطون من الزكاة","answer":"الجواب: أهل البيت لا يعطون الصدقة بنو هاشم رهط النبي ﷺ لا يعطون من الزكاة، وهكذا والداك وأولادك وزوجتك تنفق عليهم من مالك لا من الزكاة، إذا كانوا محتاجين تنفق عليهم من مالك على أبيك وأمك وجدك وجدتك وأولادك لا من الزكاة، الزكاة لغيرهم، للفقراء من أقاربك الآخرين، إخوتك الفقراء، بني عمك جيرانك، الفقراء الآخرين الأجناب من المسلمين تعطيهم من الزكاة، أما والداك أبوك وأمك وجدك وجدتك وأولادك هؤلاء تنفق عليهم من مالك لا من الزكاة، وهكذا كل غني لا يعطى من الزكاة وإنما يعطاها الفقراء، نعم، والكافر لا يعطاها إلا إذا كان مؤلفًا على الإسلام، يؤلف على الإسلام يعطى الزكاة تأليفًا له للدخول في الإسلام، أو لقوة إيمانه ويقينه. نعم.","link":"https://binbaz.org.sa/fatwas/12658/بيان-الذين-لا-يعطون-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_548/54810.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":14517,"question":"هل يجوز صرف الزكاة على الابن والأخ الذي يرث من أمه، أو الأخت التي ليس لها زوج؟نرجو أن توجهونا، جزاكم الله خيرًا، وكذلك الابن إذا كان محتاجًا؟","title":"حكم دفع الزكاة للابن والأخ والأخت","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فلا حرج في صرف الزكاة للأخ الفقير، والأخت الفقيرة، وبقية الأقارب الفقراء كالأخوال والأعمام، وابن العم ونحوهم لعموم الأدلة، ومنها قوله -جل وعلا-: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ [التوبة:60] فهم يدخلون في هذه الآية الكريمة. أما الابن فلا، أما الأولاد لا؛ لأنهم بضعة من الرجل، فلا يصرف فيهم الزكاة وعليه نفقتهم، فأولاد الإنسان من ذكور وإناث وأولاد أولاده وإن نزلوا كلهم لا يعطون الزكاة إذا كانوا فقراء، يعطيهم من ماله ينفق عليهم من ماله ولا يعطيهم من الزكاة، هذا هو الذي عليه أهل العلم، وهكذا الآباء والأمهات والأجداد والجدات لا يعطون من الزكاة، ينفق عليهم ولدهم أيضًا من غير الزكاة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12995/حكم-دفع-الزكاة-للابن-والاخ-والاخت","audio":"https://files.zadapps.info/binbaz.org.sa/old/audio/noor/070801.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":14521,"question":"هل تجب الزكاة على المال الشبه ضائع، والذي في علم الغيب، ولا يعرف هل سيعود إلى صاحبه أو لا؟","title":"حكم زكاة المال الضائع والدين","answer":"الجواب: المال الضايع لا زكاة فيه، مثل الإبل الضايعة، أو غنمًا ضائعة، أو بقرًا ضائعة، أو نقودًا ضاعت، لا يدري أين ذهبت؟ ليس عليه زكاة حتى يجدها، ثم يستقبل حولًا جديدًا، إذا وجدها يبدأ الحول. وهكذا الديون التي على المعسرين كالضايع، الدين الذي على المعسر الذي لا يستطيع الأداء ليس عليه زكاة حتى يسلم له، حتى يقبضه منه فيستقبله حولاً كاملاً.\nوهكذا الديون التي على المماطلين الذين لا يعطون الحق، يماطلون وما يعطون الحق، ليس فيه زكاة حتى يقبض المال، فالمماطل من جنس المعسر، صاحبه تعبان معه ليس عنده مال في الحقيقة حتى يقبضه فإذا قبضه زكاه إذا حال عليه الحول بعد قبضه. والخلاصة: أنّ المال الضائع والمفقود الذي ما يدري أين ذهب؟ وسواء كان نقودًا أو إبلًا أو بقرًا أو غنمًا ما فيه زكاة حتى يجده ربه، ثم يستقبله حولاً كاملاً، ومن ذلك ما كان على المعسرين، ديون على المعسرين لا زكاة فيها حتى تقبض ويستقبلها حولاً كاملاً، أو على المماطلين الذين لا يؤدون الحق إلا بالتعب، هذا لا زكاة فيه حتى يعطوه حقه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13004/حكم-زكاة-المال-الضاىع-والدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_489/48903.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":14560,"question":"إذا دفعت الزكاة لشخص أعتقد أنه فقير، وتبين غير ذلك، هل أكون قد أديت الزكاة؟","title":"هل تجزء الزكاة لمن دفعها لغني ظنًا أنه فقير؟","answer":"الجواب: نعم الصحيح أنه يجزئ؛ لأن ضبط فقر الناس فيه تعب، فإذا ظن أنه فقير بالعلامات، أو بشهادة بعض الناس، ثم بان أنه غني يجزئه ما أخرج، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13057/هل-تجزء-الزكاة-لمن-دفعها-لغني-ظنا-انه-فقير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_489/48910.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":14805,"question":"إذا كان عندي مبلغ خمسة عشر ألف ريال سعودي، في شهر محرم، عام ألف وأربعمائة وثمانية، ودخل العام الذي بعده وهو عام ألف وأربعمائة وتسعة، يعني: هذا المبلغ أكمل عام من غير أن أمس منه شيئًا، كيف نخرج منه الزكاة؟ ومتى يجب إخراجها؟","title":"وقت إخراج الزكاة لمن ملك ما يبلغ النصاب","answer":"الجواب: ما دمت ملكته في المحرم، فعليك الزكاة في المحرم، إذا تم السنة، ولو أنه لم يتصرف فيه، ولو أنه في الصندوق، أو في البنك، محفوظًا أمانة، عليك أن تخرج زكاته ربع العشر، في كل ألف خمسة وعشرون، إذا تم الحول، إذا كان هذا المال جاءك هبة، أو ورث، فإنه إذا دار عليه الحول، تمت السنة، تخرج زكاته.  فأما إن كان هذا المال ثمن سلعة معدة للبيع، فالحول حول السلعة التي أعددتها للبيع، متى تمت السنة؛ زكيت المال. فالحاصل: أن الزكاة تجب في المال، في النقود، إذا تم الحول عليها، وفي السلع المعدة للبيع: سيارات، أو فرش، أو أواني، أو غير ذلك، فعليك الزكاة فيها إذا تم حولها، حسب قيمتها. المقدم: التي هي عروض التجارة. الشيخ: وهي عروض التجارة، تنظر في قيمتها عند الحول، فإذا كانت قيمتها مثلًا: عشرة آلاف، زكيت عشرة آلاف، وإذا كانت قيمتها مائة ألف، زكيت مائة ألف، عند الحول، وهذا هو الواجب عليك وعلى أمثالك، نعم.\nالمقدم: جزاكم الله خيرًا، وأيضًا عن الزكاة، عندما ذهبت في إجازتي السنوية في شهر فبراير من عام ثمانية وثمانين، فتحت حساب في أحد البنوك الإسلامية في السودان، ووضعت فيه مبلغ عشرين ألف وثمانمائة جنيه سوداني، وفي نفس العام أخذت منه تسعة آلاف جنيه، أصبح المتبقي إحدى عشر ألف وثمانمائة جنيه حتى بداية العام الجديد تسعة وثمانين، كيف تكون طريقة إخراج الزكاة في هذا المبلغ؟ ومتى يجب إخراجها؟\nالشيخ: عليك أن تخرج الزكاة من حين تم الحول، والمبلغ الذي أخذته قبل تمام الحول، ليس فيه زكاة، لكن الذي تم عليه الحول، بعدما ملكت هذا المال، عليك زكاته، وهي ربع العشر، في كل ألف خمسة وعشرون، فلا زكاة في مال حتى يحول عليه الحول، يعني: النقود وأشباهه كعروض التجارة، وكالإبل، والبقر، والغنم، السائمة، الراعية، كل هذه لا زكاة فيها إلا إذا تمت السنة، كلما تمت السنة؛ وجبت الزكاة. أما الحبوب والثمار فتجب فيها الزكاة إذا استوت ونضجت، الحبوب إذا استوت، واشتدت، ثم حصدها ويرعاها وطابت، ونظفت، تجب فيها الزكاة بعد دريها، وتخليصها مما هي فيه من قصب ونحوه، حتى تصفيها، ويخرج زكاتها. وهكذا الثمار، كالتمر والعنب، يزكيه إذا استوى، ونضج، ووضع في البيدر، يعني في الجرين ، في محل تيبيسه، ثم يخرج زكاته إذا بلغ النصاب، خمسة أوسق، وإذا كان يسقى بالمكائن ونحوها فيه نصف العشر، في الألف خمسون، في الألف وزنة، أو الكيلو خمسون، وفي الألفين مائة، نصف العشر، وإذا كان يسقى بالمطر والأنهار الجارية، يكون فيه العشر، في الألف مائة، وفي الألفين مائتان، وهكذا، هكذا جاءت السنة عن النبي -عليه الصلاة والسلام-، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13306/وقت-اخراج-الزكاة-لمن-ملك-ما-يبلغ-النصاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_642/nour_64207.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":14813,"question":"إذا كان عندي مبلغ خمسة عشر ألف ريال سعودي، في شهر محرم، عام ألف وأربعمائة وثمانية، ودخل العام الذي بعده وهو عام ألف وأربعمائة وتسعة، يعني: هذا المبلغ أكمل عام من غير أن أمس منه شيئًا، كيف نخرج منه الزكاة؟ ومتى يجب إخراجها؟","title":"وقت إخراج الزكاة لمن ملك ما يبلغ النصاب","answer":"الجواب: ما دمت ملكته في المحرم، فعليك الزكاة في المحرم، إذا تم السنة، ولو أنه لم يتصرف فيه، ولو أنه في الصندوق، أو في البنك، محفوظًا أمانة، عليك أن تخرج زكاته ربع العشر، في كل ألف خمسة وعشرون، إذا تم الحول، إذا كان هذا المال جاءك هبة، أو ورث، فإنه إذا دار عليه الحول، تمت السنة، تخرج زكاته.  فأما إن كان هذا المال ثمن سلعة معدة للبيع، فالحول حول السلعة التي أعددتها للبيع، متى تمت السنة؛ زكيت المال. فالحاصل: أن الزكاة تجب في المال، في النقود، إذا تم الحول عليها، وفي السلع المعدة للبيع: سيارات، أو فرش، أو أواني، أو غير ذلك، فعليك الزكاة فيها إذا تم حولها، حسب قيمتها. المقدم: التي هي عروض التجارة. الشيخ: وهي عروض التجارة، تنظر في قيمتها عند الحول، فإذا كانت قيمتها مثلًا: عشرة آلاف، زكيت عشرة آلاف، وإذا كانت قيمتها مائة ألف، زكيت مائة ألف، عند الحول، وهذا هو الواجب عليك وعلى أمثالك، نعم.\nالمقدم: جزاكم الله خيرًا، وأيضًا عن الزكاة، عندما ذهبت في إجازتي السنوية في شهر فبراير من عام ثمانية وثمانين، فتحت حساب في أحد البنوك الإسلامية في السودان، ووضعت فيه مبلغ عشرين ألف وثمانمائة جنيه سوداني، وفي نفس العام أخذت منه تسعة آلاف جنيه، أصبح المتبقي إحدى عشر ألف وثمانمائة جنيه حتى بداية العام الجديد تسعة وثمانين، كيف تكون طريقة إخراج الزكاة في هذا المبلغ؟ ومتى يجب إخراجها؟\nالشيخ: عليك أن تخرج الزكاة من حين تم الحول، والمبلغ الذي أخذته قبل تمام الحول، ليس فيه زكاة، لكن الذي تم عليه الحول، بعدما ملكت هذا المال، عليك زكاته، وهي ربع العشر، في كل ألف خمسة وعشرون، فلا زكاة في مال حتى يحول عليه الحول، يعني: النقود وأشباهه كعروض التجارة، وكالإبل، والبقر، والغنم، السائمة، الراعية، كل هذه لا زكاة فيها إلا إذا تمت السنة، كلما تمت السنة؛ وجبت الزكاة. أما الحبوب والثمار فتجب فيها الزكاة إذا استوت ونضجت، الحبوب إذا استوت، واشتدت، ثم حصدها ويرعاها وطابت، ونظفت، تجب فيها الزكاة بعد دريها، وتخليصها مما هي فيه من قصب ونحوه، حتى تصفيها، ويخرج زكاتها. وهكذا الثمار، كالتمر والعنب، يزكيه إذا استوى، ونضج، ووضع في البيدر، يعني في الجرين ، في محل تيبيسه، ثم يخرج زكاته إذا بلغ النصاب، خمسة أوسق، وإذا كان يسقى بالمكائن ونحوها فيه نصف العشر، في الألف خمسون، في الألف وزنة، أو الكيلو خمسون، وفي الألفين مائة، نصف العشر، وإذا كان يسقى بالمطر والأنهار الجارية، يكون فيه العشر، في الألف مائة، وفي الألفين مائتان، وهكذا، هكذا جاءت السنة عن النبي -عليه الصلاة والسلام-، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13306/وقت-اخراج-الزكاة-لمن-ملك-ما-يبلغ-النصاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_642/nour_64207.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":14840,"question":"أجرت رجلًا أرضًا حرثها شعيرًا، ولكنه لما نضج الزرع باعه لشخص آخر، والزرع ما زال في زرعه، ولم يحصد بعد، فعلى من تجب الزكاة على الأول أم على الثاني؟جزاكم الله خيرًا.","title":"على من تجب الزكاة إذا بيع الزرع قبل الحصاد؟","answer":"الجواب: على الأول؛ إذا اشتد الحب وهو في ملكه، عليه الزكاة، نعم. المقدم: جزاكم الله خيرًا.  يسأل ويقول: رجلان اشتركا في حرث قطعة أرض، ولكن الذي قام بالعمل...\nالشيخ: لكن إذا شرطه على المشتري، باعه الزرع وشرط عليه أن الزكاة عليه هذا صارت الزكاة عليه، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/13339/على-من-تجب-الزكاة-اذا-بيع-الزرع-قبل-الحصاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_644/nour_64402.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":14845,"question":"في سؤاله الثاني يقول: رجلان اشتركا في حرث قطعة أرض، ولكن الذي قام بالعمل -حتى أصبح المحصول جاهزًا لكي يقتسماه- هو شخص واحد فقط، فعلى من تجب الزكاة على الاثنين أم على الذي لم يقم بجمع المحصول والذي هو الشعير؟الشيخ: أعد أعد.المقدم: يقول: رجلان اشتركا في حرث قطعة أرض، ولكن الذي قام بالعمل -حتى أصبح المحصول جاهزًا- شخص واحد فقط، فعلى من تجب الزكاة على الاثنين أم على الذي لم يقم بجمع المحصول؟","title":"على من تجب الزكاة في المال المشترك؟","answer":"الجواب: ما داما مشتركين، والبذر منهما، والعمل بينهما، ولكن سمح أحدهما بالقيام بالعمل عن صاحبه، فالزكاة عليهما؛ لأن المال مالهما، نعم.","link":"https://binbaz.org.sa/fatwas/13341/على-من-تجب-الزكاة-في-المال-المشترك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_644/nour_64403.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":14850,"question":"نعود مع مطلع هذه الحلقة إلى رسالة المستمع فتحي محمد مؤمن، أخونا فتحي من جمهورية مصر العربية مدينة السلوم، محافظة مطروح، بعث بعدد من الأسئلة من بينها سؤال يقول: ما هو نصاب الأموال التي يزكى عليها؟","title":"ما هو نصاب الأموال التي يزكى عليها؟","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فهذا سؤال عام، والأموال أنواع، كل نوع له نصابه، فنصاب الذهب عشرون مثقالًا، ومقداره اثنان وتسعون غرام، ومقداره بالجنيه السعودي والفرنجي إحدى عشر جنيهًا، وثلاثة أسباع جنيه، فإذا بلغ الذهب هذا المقدار وجبت فيه الزكاة، وهي ربع العشر، من كل أربعين جنيه جنيه واحد، وإذا بلغت العملة قيمة ذلك، سواءً كانت بالدولار، أو الجنيه المصري، أو كانت غير ذلك إذا بلغت هذا المقدار، وجبت فيها الزكاة ربع العشر. أما الفضة فنصابها مائة وأربعون مثقالًا، ومقداره بالدرهم السعودي الفضي ستة وخمسون ريالًا، فإذا بلغت العمل هذا المقدار، أو قيمة هذا المقدار، وجبت فيها الزكاة، وهي ربع العشر، من الألف خمسة وعشرون، من الألفين خمسون، وهكذا. أما الحبوب والثمار فنصابها خمسة أوسق، والوسق ستون صاعًا بصاع النبي -عليه الصلاة والسلام-، فإذا بلغ حاصل التمر أو الحبوب من الذرة، أو الحنطة، أو الشعير، أو الأرز ثلاثمائة صاع بصاع النبي ﷺ، يعني: خمسة أوسق، وجبت فيها الزكاة، وصاع النبي ﷺ أربع حفنات باليدين المعتدلتين المملوءتين. والواجب نصف العشر، إذا كان الزرع أو النخل يسقى بمئونة كالمكائن والسواني ففيه نصف العشر، من كل ألف خمسون، من كل ألف وزنة مثلًا، أو كيلو خمسون، وهكذا العنب إذا بلغ منه خمسة أوسق مثل التمر، فيه نصف العشر إذا كان بمئونة بالسواني أو المكائن.  أما إذا كانت الحبوب والثمار تسقى بالمطر أو بالأنهار أو بالعيون الجارية ففيها العشر كاملًا، من كل ألف مائة، من كل ألف صاع، أو ألف كيلو مائة كيلو ومائة صاع، ومن عشرات الآلاف ألف كامل، وهكذا. وعروض التجارة هي السلع التي تعد للبيع من السيارات والأقمشة والأواني ونحوها هذه نصابها نصاب الذهب والفضة، إذا بلغت قيمتها نصاب الذهب والفضة وجبت فيها الزكاة ربع العشر. وأما الإبل والبقر والغنم فلها نصب خاصة، إذا كانت سائمة ترعى غالب الحول، أو كل الحول، فإن فيها زكاة، مقدرة، قدرها النبي ﷺ، في الغنم في أربعين شاة، شاة واحدة، وإذا كانت الغنم أقل من أربعين ما فيها شيء، إلى مائة وعشرين، فإذا زادت عن مائة وعشرين صار فيها شاتان، في المائة وإحدى وعشرين شاتان، إلى مائتين، فإذا زادت عن مائتين ففيها ثلاث شياه، وهكذا في كل مائة شاة بعد ذلك، في أربعمائة أربع شياه، وفي خمسمائة خمس شياه، وهكذا. أما البقر فأقل نصابها ثلاثون تبيع أو تبيعة، قد بلغ كل واحد سنة كاملة، ذكر أو أنثى، سنة كاملة، في التبيع، أو التبيعة، إذا كانت البقرة ثلاثين سائمة ترعى سنة كاملة، ففي الثلاثين تبيع أو تبيعة، قد بلغا سنة واحدة، فإذا بلغت أربعين ففيها مسنة، تم لها سنتان، ثم ليس فيها شيء إلى أن تبلغ ستين، فإذا بلغت ستين ففيها تبيعان، إلى سبعين، فإذا بلغت سبعين ففيها تبيع ومسنة، وهكذا، في كل أربعين مسنة، وفي كل ثلاثين تبيع، فإذا بلغت مائة وعشرين استوى الفرضان، إن شاء أخرج ثلاث مسنات؛ لأن فيها أربعين ثلاث مرات، وإن شاء أخرج أربعة أتبعة؛ لأن فيها ثلاثين أربع مرات. أما الإبل فأنصباؤها متعددة، ففي الخمس شاة واحدة، وفي العشر شاتان، وفي خمسة عشر ثلاث شياه، وفي عشرين أربع شياه، فإذا بلغت خمسًا وعشرين، وهي ترعى غالب السنة، أو كل السنة وجب فيها بنت مخاض، بكرة تم لها سنة، ودخلت في الثانية، إلى ست وثلاثين، فإذا بلغت ستًا وثلاثين، ففيها بنت لبون، أنثى تم لها سنتان، إلى ست وأربعين، فإذا بلغت ستًا وأربعين، ففيها حقة طروقة الجمل، تم لها ثلاث سنين، إلى إحدى وستين، فإذا بلغت إحدى وستين ففيها جذعة، قد تم لها أربع سنين ودخلت في الخامسة، فإذا بلغت ستًا وسبعين ففيها بنتا لبون، كل واحدة قد تم لها سنتان، إلى إحدى وتسعين، فإذا بلغت إحدى وتسعين ففيها حقتان طروقتا الجمل، إلى مائة وعشرين، فإذا بلغت مائة وعشرين ففيها ثلاث بنات لبون، إلى مائة وثلاثين، فإذا بلغت مائة وثلاثين ففيها بنتا لبون وحقة واحدة، بنتا لبون في ثمانين، وحقة عن الخمسين، الجميع حقة وبنتا لبون، في مائة وثلاثين، فإذا بلغت مائة وأربعين ففيها حقتان عن المائة وبنت لبون عن الأربعين، فإذا بلغت مائة وخمسين ففيها ثلاث حقاق، وهكذا، في كل أربعين بنت لبون، وفي كل خمسين حقة، لكن بشرط أن تكون ترعى سائمة غالب السنة، أو كل السنة، في البقر والغنم والإبل جميعًا، فإذا كانت معلفة فليس فيها شيء، إذا كانت تعلف غالب السنة ليس فيها شيء، إلا أن تكون للبيع، للتجارة فإنه يزكيها زكاة التجارة، سواءً كانت إبلًا أو بقرًا أو غنمًا يزكيها زكاة التجارة، إذا كانت للبيع، وإن كان يعلفها، والله ولي التوفيق. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13338/ما-هو-نصاب-الاموال-التي-يزكى-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_644/nour_64401.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":14919,"question":"المستمع أحمد سالم حماد من البحرين، بعث يسأل ويقول: هل تجوز زكاة الفلوس على الأخ والأخت إذا كانت ساكنة بحوزة المزكي، الأخت مطلقة، وتسكن مع أولادها بحوزة المزكي؟","title":"حكم دفع الزكاة للإخوة والأخوات","answer":"الجواب: إذا كانت محتاجة، وكان الأخ محتاجًا جاز صرف الزكاة فيهما؛ لأنهما من أهلها بسبب فقرهم، لكن إذا تيسر للأخ أن يقوم بحالهم، وأن ينفق عليهم من ماله كان هذا أفضل وأحسن، تبعًا لذريته ولعائلته.  وأما إذا خصها بشيء لحاجتها، وحاجة أطفالها في كسوة ونحوها، فإن هذا لا بأس به، أما الأكل فتأكل معهم في طعامهم وشرابهم في البيت؛ لأن الأكل موضوع للجميع، أما إذا كان على حدة، تصنع طعامها على حدة، لها عهدة من البيت على حدة، فإنها تعطى ما يكفيها من الزكاة لها ولأولادها في الكسوة والطعام وغير ذلك بسبب الحاجة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13412/حكم-دفع-الزكاة-للاخوة-والاخوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_492/49204.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":14931,"question":"هذه رسالة وردتنا من العراق، ويرجو فيها أن يسمع الإجابة، يقول: الاسم (ع. ك) من العراق، يقول: متى تستحق الزكاة؟ وكم زكاة الفلوس العراقية إذا كان المبلغ ألفين ومائتين دينار عراقي؟","title":"مقدار الزكاة ومصارفها","answer":"الجواب: الزكاة مثل غيره، العراق مثل غيره، كلما جمع مال فيه ربع العشر، سواءً دينار عراقي، أو غيره، فالألفان فيهما خمسون، والألف فيه خمسة وعشرون، ربع العشر زكاة، وإذا كان عنده مائة ألف من الدنانير، فيها ربع العشر، ألفين ونصف في المائة الألف ألفين ونصف ربع العشر، وفي المليون خمسة وعشرون ألفًا، وهكذا.  فالمقصود: ربع العشر مما يملكه الإنسان من النقود، سواء كان عراقية أو أردنية أو إنجليزية أو أمريكية أو غير ذلك، ربع العشر من الذهب والفضة، نعم، والأوراق النقدية هذه، نعم. السؤال: سؤاله الثاني يقول: إنني كنت أشتغل في شركة...\nالشيخ: ويعطاها المستحق، الذي يستحق الزكاة يعطاها الفقراء، الفقراء والمحاويج من المسلمين، والإنسان الذي عليه دين يعجز عن أدائه، غارم، يُعطى ما يسدد به دينه، والمؤلف رئيس العشيرة كبار القوم، إذا كانوا فقراء، أو ضعيف إسلامهم، أو يخشى عليهم الردة، يعطون ما يؤلفون به، حتى يقوى إيمانهم، ويقوى إسلامهم، رؤساء العشائر، كبار القوم الذي يرجى في عطيتهم قوة إيمانهم، وقوة إسلامهم، وتعاونهم مع المسلمين، نعم.","link":"https://binbaz.org.sa/fatwas/13445/مقدار-الزكاة-ومصارفها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_647/nour_64709.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":15086,"question":"عبدالرحمن محمد الدخيل، بعث لنا بهذه الرسالة، يسأل عن النيابة في صرف الزكاة، يقول: إن أحد المدرسين من الإخوة المصريين أعطاني خمسين ريالًا، وقال لي: خذ هذه الخمسين، وأعطها أي شخصٍ ترى أنه مستحق لها، فإنها من زكاة مالي، فأخذت الخمسين ريالًا، وأعطيتها شخصًا، تبين بعد ذلك أنه غير مستحق لها. علمًا أن هذه الحادثة وقعت منذ وقتٍ بعيد، وكلما تذكرتها أضيق، ويؤنبني ضميري، فأرجو منكم معالجة هذه المشكلة، وفقكم الله.","title":"حكم إعطاء الزكاة لمن لا يستحقها بدون قصد","answer":"الجواب: إذا كان الشخص الذي دفعت إليه الخمسين ظاهره الفقر والحاجة، ودفعتها إليه بسبب ما ظهر لك من حاجته وفقره؛ فلا حرج في ذلك، وقد وقعت موقعها وأجزأت، والحمد لله. أما إن كنت أعطيته إياها من غير نظر، ولا تأمل، ولم يظهر لك أنه محتاج، وإنما تساهلت في ذلك؛ فإنك تغرمها، وتعطيها شخصًا تعرف حاجته وفقره، نعم.","link":"https://binbaz.org.sa/fatwas/13589/حكم-اعطاء-الزكاة-لمن-لا-يستحقها-بدون-قصد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_655/nour_65507.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":15194,"question":"السؤال التالي بعث به المستمع (س. ع. ن) من الدمام، يقول: لي في ذمة أحد الناس مبلغ من المال، ويرجى سداده، ولكن في الوقت الحاضر لا يتمكن المدين من السداد، وفي نفس الوقت ذلك الشخص المدين يستحق الزكاة، فهل أضع عنه مما لي في ذمته مقابل زكاته له، أم أدفع له من غير ما عنده من الدين؟","title":"حكم إسقاط الدين وجعله من الزكاة","answer":"الجواب: الواجب أنك تعطيه إذا كان مستحقًا، المشروع لك أن تعطيه مما لديك إذا كان من أهل الزكاة.  وأما إسقاط جزء مما عليه عن الزكاة فلا يجزي؛ لأن الزكاة إعطاء ودفع، وليست إبراء، فالدين الذي عليه يمهل إذا كان معسرًا حتى يتيسر له الوفاء؛ لأن الله قال: وَإِنْ كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَى مَيْسَرَةٍ [البقرة:280]. وأما الزكاة فلا بأس أن يعطى من الزكاة إذا كان من أهلها، إذا كان فقيرًا، يعطى من الزكاة التي عندك من المال الذي عندك.\nوأما إسقاط شيء مما عليه عن الزكاة فلا يجزئ، نعم.","link":"https://binbaz.org.sa/fatwas/13696/حكم-اسقاط-الدين-وجعله-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_671/nour_67103.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":15336,"question":"(ع. أ. م) السائل من حفر الباطن، أرسل بسؤال كتبه بأسلوبه الخاص، يقول -يا سماحة الشيخ-: بأنه شاب متزوج، ولديه أولاد، ويحمد الله على ذلك، دخله الشهري محدود، ويعيش في بيت والده، وإخوانه جميعًا، والسؤال يبقى يقول: هو أن أحد الإخوة يعلم بدخلي الشهري المحدود، وقام بمساعدتي بمبلغ من المال، ورفضت أن آخذ في البداية هذا المبلغ، لكنه ألح علي، فقبلته كمساعدة.علمًا بأنه أخبرني بأن ذلك من الزكاة، فهل يحل لي هذا المال؟ علمًا بأنني مطالب بدفع مبلغ من المال وقدره ثمانية عشر ألفًا ريال لدى إحدى الجهات بعد سنتين من هذا اليوم، ولا أملك هذا المبلغ، فأفيدوني، مأجورين.","title":"حكم إعطاء الزكاة لمن راتبه محدودًا","answer":"الجواب: أنت أعلم بنفسك، إذا كنت محتاجًا إليه، فقيرًا إليه، فلا بأس، إذا كان الدخل الذي يدخل عليك لا يكفي مئونة أهلك، مئونتك فلا بأس أن تأخذ، وإذا كان عليك دين فأنت غارم تأخذ لأجل الغرم؛ لأن الله جعل للغارمين حقًا في الزكاة، ولو كان الدين مؤجلًا إلا إذا كان له وفاء، إذا كان له وفاء لا تأخذ الزكاة، أما إذا كان ما له وفاء تأخذ وتؤديه لصاحب الدين، ولو عجلته قبل الحل، فعليك الحذر من أخذ الزكاة بغير حق، فإن كنت محتاجًا إليه؛ لأن الراتب لا يكفي لحاجاتك فلا بأس، أو أخذته لغرم لأنك ما عندك مال تؤدي منه الدين، فلك أن تأخذه، وتسدد منه الدين، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13831/حكم-اعطاء-الزكاة-لمن-راتبه-محدودا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_566/56613.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":15366,"question":"هذه السائلة أم البراء الرياض، تقول: رجل يسكن منزلًا مؤجرًا بعشرين ألف ريال، له أطفال راتبه الشهري حوالي خمسة آلاف ريال، هل يجوز له أن يأخذ الزكاة؟مع العلم بأنه ليس عليه ديون، ولكنه يريد أن يجمع كي يشتري منزلًا، وما حكم الفلوس التي أخذها من أعمامه وأقاربه هل يقوم بإرجاعها أم ماذا يفعل؟وجهونا، مأجورين.","title":"حكم إعطاء الزكاة للموظف","answer":"الجواب: لا يجوز له الحق في أخذ الزكاة، ما دام هذا المبلغ الذي يصل إليه يكفيه في السكن، وفي الحاجة، في النفقة إذا كان راتبه يكفيه لحاجة النفقة وحاجة الأجرة، فلا يجوز له أن يدفع له شيء من الزكاة لشراء المنزل أو الاستئجار.  أما إذا كان لا راتبه ما يكفيه لكثرة العائلة والنفقة، فله أن يأخذ من الزكاة من أجل أن يشتري به سكنًا أو يستأجر. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/13869/حكم-اعطاء-الزكاة-للموظف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_499/49909.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":15483,"question":"أم نواف من الرياض تقول: هل ينفع أن تدفع كفالة اليتيم كاملة، أو جزءًا منها من زكاة المال، حيث إنه يوافق دفع قسط كفالة اليتيم وقت دفع الزكاة؟","title":"حكم كفالة اليتيم من الزكاة","answer":"الجواب: إذا كان اليتيم فقيرًا فلا بأس، من الزكاة وغيرها، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14010/حكم-كفالة-اليتيم-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56904.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":15629,"question":"هذه سائلة للبرنامج تقول -سماحة الشيخ-: تذكر بأنها امرأة توفي عنها الزوج، وتعمل بمدرسة أهلية، وتحمد الله، وتستلم من ذلك راتب يكفيها، ويكفي أبناءها، والحمد لله. تقول السائلة: وقد ترك لي زوجي مبلغًا من المال، وفي بلدي ما يكفيني ويكفي أبنائي، ولدي طفل صغير عمره ما يقارب من سنتين، ويأتي بعض الإخوان جزاهم الله خيرًا ببعض الأغراض والمال ويعطونه لهذا الصغير، فأرفض ذلك أنا؛ لأنني لست بحاجة إليه، والحمد لله، وهناك من يستحق هذا، وهذا مما يضايقني ويجرح مشاعري، وعندما أجلس مع نفسي أخشى أن أكون قد عصيت الله في قوله: يَسْأَلُونَكَ مَاذَا يُنفِقُونَ قُلْ مَا أَنفَقْتُمْ مِنْ خَيْرٍ فَلِلْوَالِدَيْنِ وَالأَقْرَبِينَ وَالْيَتَامَى وَالْمَسَاكِينِ وَابْنِ السَّبِيلِ [البقرة:215] فهل أكون منعت مال هذا اليتيم وعصيت الله؟","title":"حكم الامتناع عن أخذ ما يهدى لليتيم، وكيفية زكاة أمواله","answer":"الجواب: المشروع لك ألا ترديه، النبي ﷺ قال لـعمر: ما جاءك من هذا المال وأنت غير مشرف ولا سائل فاقبله، وما لا فلا تتبعه نفسك فأنت إذا جاء للطفل احفظيه للطفل، هذه العادة بين المسلمين إعطاء الأطفال، وتقديم الهدايا المناسبة للأطفال، فهذه عادة معروفة، فإذا جاء للطفل شيء فاقبليه واحفظيه واجعليه من ماله، نعم. المقدم: أحسن الله إليكم، تقول السائلة: ترك لي زوجي مبلغًا من المال وقسمته على أبنائي حسب الشريعة الإسلامية، ولكن مال هذا الصغير أود أن أحتفظ به حتى يبلغ، هل أدفع عنه زكاة أم لا؟ وإن كان هناك زكاة فقد ترك زوجي المال في ذي الحجة فهل أدفع ذلك في رمضان أم في ذي الحجة؟\nالشيخ: إذا حفظت المال عندك، وحال عليه الحول ادفعي المال في تمام الحول على رأس الحول، فإذا كان المال حصل بأن مات الزوج في رمضان فالزكاة تكون في رمضان على المال الذي بقي، والنقود التي بقيت إلى رمضان، وإذا مات في ذي الحجة فالزكاة في ذي الحجة، وهكذا على رأس السنة. وإن قدمت الزكاة قبل تمام نصف الحول فلا حرج، إذا قدمت فلا بأس ليعطاها الفقراء، والزكاة عنك وعن أموال أولادك إذا كان لهم أموال تزكين أموالهم إذا كان لهم أموال من النقود -ذهب أو فضة- زكيها، وهكذا إذا كان لهم أراضٍ للبيع معدة للبيع تزكى إذا حال عليها الحول، سواء كانوا بالغين أو غير بالغين الزكاة على الجميع، إذا حال الحول على المال بعد موت الميت يزكيه صاحبه، إن كان ذهب أو فضة يزكى إذا حال الحول، وإن كان عقارًا للبيع يزكى على رأس الحول، ومن قدم الزكاة قبل تمام الحول قدمها للمصلحة رأى فقراء وقدم لهم الزكاة فلا بأس لا حرج. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14170/حكم-الامتناع-عن-اخذ-ما-يهدى-لليتيم-وكيفية-زكاة-امواله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_571/57112.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":15663,"question":"سؤاله الآخر يقول: منذ خمس سنوات تقريبًا بدأت أقترض من أحد الأشخاص إلى أن بلغ ما له في ذمتي ما يقارب خمسين ألف ليرة، فهل يجب علي دفع زكاتها أنا أم صاحبها يزكيها؟","title":"من يدفع زكاة الدين؟","answer":"الجواب: الديون التي على الإنسان زكاتها على صاحبها، وليس على الغريم زكاة، إنما الزكاة على من له الدين، إذا كانت الأموال التي اقترضها قد صرفها في حاجاته غير موجودة لديه يكون قد صرفها في حاجاته، اشترى بها مثلًا سيارة يستعملها لحاجته، يستعملها تكسي مثلًا، اشترى بها أرضًا للسكن، اشترى بها فرشًا لبيته، أو ما أشبه ذلك هذه ليس فيها زكاة، أما إذا كانت الديون عنده بأعيانها أخذها قرضًا، ولكنها باقية الفلوس عنده، الدراهم عنده موجودة، ما أنفقها، فعليها الزكاة إذا حال عليها الحول، يزكيها هو إذا حال عليها الحول. أما صاحبها الذي أقرضه إياها فهذا ينظر فيه، فإن كان من عليه الدين مليئًا زكاها صاحبها أيضًا، وإن كان معسرًا أو مماطلًا فلا زكاة عليها بالنسبة إلى صاحبها. أما بالنسبة إلى الذي أخذها واقترضها، فالأمر كما تقدم......، وإنما الزكاة على المقرض إذا كان المقرض مليئًا غير مماطل، فإن على المقرض أن يزكيها إذا حال عليها الحول، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/14206/من-يدفع-زكاة-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_700/nour_70002.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":15768,"question":"يقول: إلى أي وقت يمكن تأخير أداء الزكاة بعذر، وهل يمكن التعجل فيها ومتى؟","title":"حكم تأخير الزكاة وتعجيلها","answer":"الجواب: المعذور يؤدي الزكاة متى كان العذر، فإذا مثلًا حلت الزكاة في رمضان، وليس عنده مال، ثم يسر الله المال في شوال، أو في ذي القعدة أخرج الزكاة، أو في إبله أو غنمه، وليس عنده النصاب ليس عنده الزكاة الواجبة يطلبها يلتمسها من هاهنا وهاهنا، فإذا وجدها أخرجها، سلمها للعمال، إن كان العمال يأتونه، وإلا تصدق بها. المقصود: أنه متى وجد الزكاة بادر بها، وعليه السعي إلى تحصيلها من حين الرجوع؛ لكي تجب من حين يتم الحول، يسعى ويجتهد حتى يحصل الواجب ويخرجه، ولا يتساهل، وإن عجلها فلا بأس، إن عجل الزكاة قبل وقتها، والنصاب موجود، وعجل الزكاة، فلا بأس، لا حرج في ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14361/حكم-تاخير-الزكاة-وتعجيلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_741/nour_74114.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":15771,"question":"يقول: إلى أي وقت يمكن تأخير أداء الزكاة بعذر، وهل يمكن التعجل فيها ومتى؟","title":"حكم تأخير الزكاة وتعجيلها","answer":"الجواب: المعذور يؤدي الزكاة متى كان العذر، فإذا مثلًا حلت الزكاة في رمضان، وليس عنده مال، ثم يسر الله المال في شوال، أو في ذي القعدة أخرج الزكاة، أو في إبله أو غنمه، وليس عنده النصاب ليس عنده الزكاة الواجبة يطلبها يلتمسها من هاهنا وهاهنا، فإذا وجدها أخرجها، سلمها للعمال، إن كان العمال يأتونه، وإلا تصدق بها. المقصود: أنه متى وجد الزكاة بادر بها، وعليه السعي إلى تحصيلها من حين الرجوع؛ لكي تجب من حين يتم الحول، يسعى ويجتهد حتى يحصل الواجب ويخرجه، ولا يتساهل، وإن عجلها فلا بأس، إن عجل الزكاة قبل وقتها، والنصاب موجود، وعجل الزكاة، فلا بأس، لا حرج في ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14361/حكم-تاخير-الزكاة-وتعجيلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_741/nour_74114.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":15789,"question":"مستمع من السودان هو محمد الحوري -فيما يبدو- بعث برسالة وضمنها سؤالًا واحدًا يقول فيه: أملك ستة آلاف ريال، ولها عندي ستة أشهر، وبعثتها إلى السودان، هل عليها زكاة؟","title":"وجوب الزكاة بتمام الحول وبلوغ النصاب","answer":"الجواب: إذا تم عليها الحول، إذا مكثت في السودان وتم عليها سنة زكيها، أما إذا أرسلتها للسودان لتصرف في حاجات أهلك، أو لقضاء دين، أو في تعمير مسكنك، أو ما أشبه ذلك، فلا زكاة فيها؛ لأنه ما تم عليها الحول، ستة أشهر ليس بحول، الحول اثنا عشر شهرًا، فإذا تم عليها الحول وهي عندك أو عند وكيلك فعليك الزكاة، فإن صرفت في حاجاتك قبل تمام الحول، أو في قضاء دين، أو نحو ذلك مما تصرف فيه هذه الدراهم، فإنه لا زكاة فيها، كما لو بنى بها وكيلك شيء في بيتك حاجة، أو أصلح أخراب في بيتك، أو أنفقها على عيالك قبل تمام الحول، أو أنفقتها أنت قبل تمام الحول فلا شيء فيها، إنما الزكاة تجب فيها إذا بقيت حتى تم عليها الحول، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14374/وجوب-الزكاة-بتمام-الحول-وبلوغ-النصاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_742/nour_74211.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":15812,"question":"يقول: يا سماحة الشيخ، أنا أعمل في المملكة، وكل شهر أستلم مرتبي، فعندما يحول الحول كيف أخرج الزكاة؟ هل عن الشهر الأول الذي حال عليه الحول، أم عن مرتب السنة كلها التي عملتها من أول شهر إلى آخر الشهر الذي أخرج فيه الزكاة؟","title":"كيفية إخراج الزكاة من الراتب","answer":"الجواب: كلما حال الحول على الراتب فزكه، الشهر الأول يزكى أولًا، والشهر الثاني هكذا، والثالث هكذا، كلما تم الحول على الراتب وجبت فيه الزكاة، إلا إذا أردت تقديم الزكاة عن الأحوال المتأخرة قدمتها مع الأول، فلا حرج عليك، لا بأس، يجوز تقديم الزكاة، لكن لا يلزمك إلا إذا تم الحول على كل راتب، نعم. المقدم: جزاكم الله خيرًا، بمعنى: يزكي راتب محرم في محرم، وصفر في صفر، وهكذا.\nالشيخ: وهكذا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14400/كيفية-اخراج-الزكاة-من-الراتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_743/nour_74314.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":15827,"question":"السائل يقول في هذا  حفظكم الله بأنه موظف، ويحتفظ بمبلغ من المال في كل شهر من راتبه لوقت الحاجة أو للزواج، فهل يجب على ما ادخره زكاة؟","title":"حكم إخراج الزكاة من المال المدخر","answer":"الجواب: نعم عليه زكاة، كل جزء حال عليه الحول يزكيه، كل جزء ادخره وحال عليه الحول يزكيه، وإن زكى الجميع تبعًا للجزء الأول فلا بأس، طيب جزاه الله خيرًا، وإلا كل جزء عليه زكاته إذا حال حوله في رمضان، ادخر ألفًا عليه زكاته إذا جاء رمضان، في شوال ادخر ألفًا ثانيًا عليه زكاته إذا جاء شوال، في ذي القعدة ادخر ألفًا ثالثًا إذا جاء ذي القعدة يزكيه، وهكذا، ولو زكاهم جميعًا في الحول الأول في رمضان، كفى، والحمد لله، جزاه الله خيرًا، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14416/حكم-اخراج-الزكاة-من-المال-المدخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_575/57519.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":15946,"question":"هذه السائلة الأخت أم ياسر من الرياض تقول -سماحة الشيخ-: هل يجوز أن أعطي زكاة المال لامرأة لا تصلي؟","title":"حكم إعطاء الزكاة لتارك الصلاة","answer":"الجواب: لا يعطى، لا تعطيها الزكاة، أعطيها امرأة تصلي، ابحثي عن الفقراء الطيبين، الذي ما يصلي كافر، نعوذ بالله، يقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر ولا يعطى الكفرة إلا المؤلفة قلوبهم، يعطوا من الزكاة، المؤلفة قلوبهم من رؤساء العشائر، وكبار الناس الذين إذا هداهم الله هدى الله بهداهم غيرهم، وحصل بهداهم نفع كبير للناس، أما أفراد الناس الكفرة لا، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14552/حكم-اعطاء-الزكاة-لتارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_578/57809.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":15951,"question":"تقول أم عبد العزيز في سؤالها الثاني -يا سماحة الشيخ-: هل يجوز أن أعطي زكاة المال لشخص متزوج، وله بنت صغيرة عنده سيارة أجرة، يكتسب منها في الشهر حوالي سبعمائة جنيه، ويمر شهر آخر تكون معطلة السيارة؟ علمًا بأنه موظف حكومي مرتبه مائة وخمسين جنيه.","title":"حكم إعطاء الزكاة لمن له مصدر دخل","answer":"الجواب: إذا كنت تعلمين أنه فقير، وأنه عرض له حاجة وفقر فلا بأس، وإلا فالذي عنده أسباب تقوم بحاله لا يعطى الزكاة، ولكن إذا عرض عارض، وعرفت أنه فقير، فلا بأس أن تعطيه من الزكاة، وإلا فالأصل أن من كان له أسباب تقوم بحاله لا يعطى من الزكاة. المقدم: لعلكم -يا سماحة الشيخ- حفظك الله، تبينون من هم أهل الزكاة الذين تجوز إعطاؤهم.\nالشيخ: مثلما قال الله -جل وعلا-: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِمِينَ وَفِي سَبِيلِ اللَّهِ وَاِبْنِ السَّبِيلِ [التوبة:60].\nهؤلاء هم أهل الزكاة: (الفقراء) معروفون.\nوالمساكين هم الذين لا يجدون ما يكفيهم في السنة، أسبابهم ضعيفة، أو ليس لهم أسباب؛ هؤلاء هم الفقراء والمساكين.\nوالعاملين عليها هم العمال الذين يبعثهم ولي الأمر يخرصون النخيل والثمار والغنم والإبل، ويأخذون زكاة الإبل والغنم، هذه يقال لهم: عمال يبعثهم ولي الأمر يعطيهم من الزكاة، أو من بيت المال.\nوالمؤلفة قلوبهم: هم الرؤساء والسادة من الناس الذين إذا أسلموا هداهم الله، ولو كانوا كفرة يعطون، أو كانوا مسلمين يعطون يرجى بعطيتهم إسلام نظرائهم أو قوة إيمانهم، هؤلاء هم المؤلفة قلوبهم، السادة الكبار المطاعون في عشائرهم الذين يرجى بعطائهم قوة إيمانهم أو إسلام نظرائهم.\nوفي الرقاب: عتق الرقاب، ويشترى من الزكاة رقاب تعتق، وهكذا المكاتبون الذين اشتروا أنفسهم من السادة بدين في الذمة يعطى المكاتب ما يسد به الدين الذي عليه الذي اشترى به نفسه من سيده.\nوالغارمين: أهل الدين الذين عليهم ديون، وهم عاجزون سواء كانت الديون لإصلاح ذات البين أو لحاجاتهم، فإذا كانوا عاجزين عن قضاء الديون هؤلاء هم الغارمون يعطوا من الزكاة للدين لقضاء الدين.\nوفي سبيل الله: الجهاد، يعطى الغزاة ما يعينهم على الغزو.\nوابن السبيل الذي يمر بالبلد وينقطع، ما عنده شيء، يعطى ولو كان غنيًا في بلاده، إذا مر بالبلد وأنت تعلم أنه منقطع، أو قال: إنه منقطع، وأنت لا تعرف حاله، وقال: إنه منقطع؛ تعطيه من الزكاة، نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/14561/حكم-اعطاء-الزكاة-لمن-له-مصدر-دخل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_578/57810.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":16399,"question":"من ليبيا إحدى الأخوات بعثت برسالة وقعت في نهايتها بقولها: ابنتكم عزة بون خيلة، تسأل وتقول: هل تجوز الزكاة في الأقارب، مثل البنت، والأخت والعم والعمة، والدي يعطي كل سنة من الزكاة بناته، وإخوته، وأخواته، وسمعت من قال: لا تجوز الزكاة في البنات؛ لأنهن سيرثن والدهن بعد موته، علمًا بأن أخواتي متزوجات، وبعضهن حالة زوجها المادية ضعيفة، أفيدونا في هذا الموضوع إفادة كافية؟ جزاكم الله خيرًا.","title":"ما حكم دفع الزكاة للأقارب؟","answer":"الجواب: الأقارب فيهم تفصيل، فإذا كان القريب من الفروع كالأولاد، وأولاد البنين، وأولاد البنات، والبنات أنفسهن لا يعطون من الزكاة، هذا الذي عليه أهل العلم، ولكن ينفق عليهم والدهم إذا كانوا فقراء، ينفق عليهم من ماله، وهكذا الآباء، والأجداد، والأمهات لا يعطوا من الزكاة.  أما بقية الأقارب كالإخوة، والأعمام، وبني العم، وبني الخال، وبني الخالة، وأشباههم، فيعطون الزكاة إذا كانوا فقراء، أو غارمين، عليهم ديون، ما يستطيعون أداءها، لقوله سبحانه: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِمِينَ وَفِي سَبِيلِ اللَّهِ وَاِبْنِ السَّبِيلِ [التوبة:60] وتكون صدقة، وصلة كما قال النبي ﷺ: الصدقة على ذي الرحم صدقة وصلة. وأما الآباء، والأجداد، والأمهات، والذرية؛ فليسوا من أهل الزكاة، لا يعطون من الزكاة؛ لأنهم شيء واحد، فالأولاد بضعة منه، وهو بضعة من أبيه وأمه، فالواجب عليه أن ينفق عليهم من صلب ماله، لا من الزكاة نعم، إذا كانوا فقراء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15115/ما-حكم-دفع-الزكاة-للاقارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_811/nour_81112.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":16427,"question":"من المستمع سفيان أحمد من القاهرة العريش رسالة، وضمنها سؤالين، في سؤاله الأول يقول: نحن نقوم ببناء مسجد بالجهود الذاتية، ونجمع زكاة المال، وننفقها في هذا المسجد، فهل هذا يجوز؟","title":"حكم صرف الزكاة في بناء المساجد ونحوها","answer":"الجواب: الصواب أنه لا تنفق الزكاة للمساجد، الصواب عند جمهور أهل العلم أن الزكاة لا تصرف في المساجد، تصرف في الأصناف الثمانية التي بينها الله، في قوله : إِنَّمَا الصَّدَقَاتُ أي: الزكوات إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِمِينَ وَفِي سَبِيلِ اللَّهِ وَاِبْنِ السَّبِيلِ [التوبة:60] هذه مصارف الزكاة، ليس منها المساجد، والمدارس، لا، في سبيل الله الجهاد. فالواجب على المؤمن والمؤمنة أن يتقوا الله في صرف الزكاة، وألا تصرف إلا في أهلها، لا في المساجد، ولا في الأغنياء، ولا في أولادك، ولا في آبائك، ولكن تعطيها الفقراء من إخوتك الفقراء، أو أخوالك، أو أعمامك، أو بني عمك الفقراء، أو غيرهم من الناس الفقراء المسلمين، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15125/حكم-صرف-الزكاة-في-بناء-المساجد-ونحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_715/nour_71506.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":16741,"question":"رسالة مطولة بعث بها المستمع صالح بن محمد بن ظافر الشهري من السرح، أخونا كما قلت: رسالته مطولة، ومن صفحتين، ملخص ما في هذه الرسالة يقول: إذا كنت وكيلًا لبعض الورثة، فهل لي أن أقطع جزءًا من أملاكهم طريقًا للسيارة لتصل إلى أملاك جيرانهم؟","title":"حكم اقتطاع الوكيل جزءًا من أرض الورثة طريقًا","answer":"الجواب: ليس لك ذلك إلا بمراجعة المحكمة إذا كانوا قاصرين، أما إذا كانوا مكلفين مرشدين؛ فشاورهم، فإذا سمحوا؛ فلا بأس، أما إذا كانوا قاصرين فهذا تراجع فيه المحكمة، محكمة البلاد؛ حتى ترشدك المحكمة إلى ما تراه في هذا المقام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15491/حكم-اقتطاع-الوكيل-جزءا-من-ارض-الورثة-طريقا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_821/nour_82104.mp3","categories":["إخراج الزكاة وأهلها","الوكالة"]},{"id":17134,"question":"يسأل سماحتكم فيقول: ماذا أصنع في أخ، أو قريب، أو جار، وهو في حاجة إلى الزكاة، والصدقة، لكنه لا يصوم، ولا يصلي، هل يستحق مني أن أعطيه مما ذكرت؟ وجهوني، جزاكم الله خيرًا.","title":"حكم الزكاة والصدقة لقريب تارك للصلاة والصيام","answer":"الجواب: نعم، تنصحه لله، وتعطيه من مالك ما ترى أنه من أسباب دعوته للإسلام، وتركه ما هو عليه من الباطل، والزكاة لا تعطيه الزكاة، أعط الزكاة من هو معروف بالاستقامة، والإسلام من الفقراء، لكن تعطيه من مالك غير الزكاة، تؤلف قلبه؛ لعل الله يهديه، تعطيه إذا كان فقيرًا لعله يتوب إلى الله، ويصلي، ويصوم؛ لأن ترك الصلاة كفر أكبر -نعوذ بالله- في أصح قولي العلماء، حتى ولو كان ما يجحد وجوبها. أما إذا جحد وجوبها؛ كفر عند جميع العلماء، لكن إذا كان يقر بوجوبها، ولكن يتكاسل بعض الأحيان، فلا يصلي فإنه يكفر بذلك عند جمع من أهل العلم، وهو الأصح من أقوال العلماء، وقال آخرون: بل يكون عاصيًا، أتى كبيرة عظيمة، وقد أتى كفرًا دون كفر، ولا يكفر كفرًا أكبر، ولكن الصحيح من حيث الدليل أنه يكفر كفرًا أكبر. لكن إذا أعطيته من الصدقة غير الزكاة، ونصحته لله، ووجهته إلى الخير، فأنت على خير، وإذا كان كبيرًا، أو رئيسًا، أو مطاعًا في قومه، وأعطيته من الزكاة من باب التأليف؛ جاز أيضًا؛ لأن المؤلفة قلوبهم لهم حق في الزكاة. فالكافر يعطى من الزكاة إذا كان يرجى بهذا تأليف قلبه، ودخوله في الإسلام، أو إسلام نظيره، أو كف شره عن الناس، لكن لا حرج لك أن تعطيه من غير الزكاة لقول الله : لا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ وَلَمْ يُخْرِجُوكُمْ مِنْ دِيَارِكُمْ أَنْ تَبَرُّوهُمْ وَتُقْسِطُوا إِلَيْهِمْ [الممتحنة:8] فالكافر الذي لا يقاتلنا لا مانع أن نعطيه من الصدقة حتى نؤلف قلبه بذلك، ونحسن إليه لعله يتوب لعله يهتدي.  وقد ثبت في الصحيح أن أم أسماء بنت أبي بكر -رضي الله عنهما- قدمت المدينة في وقت الصلح بين النبي ﷺ وبين أهل مكة، وقت الهدنة، جاءت إلى بنتها أسماء تطلب الرفد، والمساعدة، وهي كافرة على دين قومها من أهل مكة، فسألت أسماء النبي ﷺ عن ذلك، فقال النبي ﷺ: صليها فأمرها أن تصليها وهي كافرة؛ لأن في هذا برًا لها، ولأنه وسيلة إلى إسلامها. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15961/حكم-الزكاة-والصدقة-لقريب-تارك-للصلاة-والصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_722/nour_72210.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":17356,"question":"من المنامة في دولة البحرين رسالة بعث بها المستمع محمد فؤاد يقول: أرجو من سماحتكم الرأي والمشورة، أنا والحمد لله ميسور الحال ماديًا، ولدي أموال أريد إخراج الزكاة عليها، ولي أخ يعمل موظفًا في إحدى الشركات، ومتزوج، وله أولاد، ولكن مشكلته أنه موظف في إحدى الشركات، وراتبه ضعيف، وليس لديه سكن، هل لي أن أعطيه زكاة مالي ليبحث بها عن مسكن له؟ جزاكم الله خيرًا.","title":"حكم إعطاء الأخ من الزكاة لشراء مسكن له","answer":"الجواب: لا حرج في أن تعينه في السكن، تأمره أن يشتري، وإذا اشترى، وثبت الدين تسدد عنه كما تعطيه ما يساعده في حاجاته، وقضاء دينه الآخر، ما دام لا يستطيع؛ لأن راتبه ضعيف، ولا يستطيع به الأجرة، أو الشراء، لا حرج في ذلك أن تعطيه الأجرة، أو يشتري، ثم تعطيه الثمن.. لا تعطيه حتى يشتري لئلا تضيع الدراهم.. الزكاة، إذا اشترى، ولزم الدين سلم له الدين؛ لأنه فقير. نعم. المقدم: جزاكم الله خيرًا، يقول في نهاية رسالته: إن زوجته ربما تشاركه في هذا الأمر، فتدفع ثمن المنزل أيضًا لأخيهم الفقير هذا؟ الشيخ: لا بأس إذا شاركته -جزاها الله خيرًا- ما دام فقيرًا يستحق العون لفقره، أو لأنه غريم اشترى البيت ولزمه الثمن وصار غريمًا يعطى منك ومنها ما يسدد به الثمن من الزكاة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16228/حكم-اعطاء-الاخ-من-الزكاة-لشراء-مسكن-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_834/nour_83410.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":17369,"question":"المستمع خالد بن علي ...... من الرياض يقول: سماحة الشيخ حفظكم الله ورعاكم، هل على الزكاة التي دار عليها الحول زكاة؟","title":"حكم المال المعزول للزكاة إذا حال عليه الحول","answer":"الجواب: المال يزكى، المال إذا دار عليه الحول يزكى، وعليه أن يخرجه من حين يتم الحول، ولا تكون زكاة إلا إذا أخرجها، المال كله يزكى إذا حال عليه الحول يحسبه، ويخرج زكاته ربع العشر، أما لو عزلها يعطها الفقراء، ولا أعطها الفقراء، وحال عليها الحول يزكيها؛ لأنها ما خرجت عن ماله، لو كان عنده مثلًا أربعون ألفًا، وعزل ألفًا يعطيه للفقراء، وحال الحول وهو ما أخرجه يزكيه؛ لأنه ماله، ما راح، ما ذهب للفقراء، يزكي للألف خمسة وعشرين ريالًا زكاة الألف، ربع العشر. نعم.  المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16211/حكم-المال-المعزول-للزكاة-اذا-حال-عليه-الحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_593/59329.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":17409,"question":"هل يجوز دفع الزكاة للأقارب إذا كانوا فقراء، وهم: الأب، والأم ،والأخ، والأخت؟","title":"حكم دفع الزكاة للأقارب","answer":"الجواب: يجوز دفع الزكاة للفقراء من الأقارب صدقة، وصلة؛ لأن النبي ﷺ لما سئل قال: الصدقة على الفقير صدقة، وعلى ذي الرحم اثنتان، صدقة وصلة فلا بأس أن يعطي أخاه، وعمه، وخاله إذا كان فقيرًا من زكاته، أو صدقة تطوع، صدقة وصلة، لكن إذا كان الفقير من آبائه، أو أجداده، أو أمهاته لا؛ لأنه عليه أن ينفق عليهم، أو كانوا من ذريته لا يعطيهم من الزكاة، ينفق عليهم؛ لأن الولد أحق على أبيه أن ينفق عليه، والأم كذلك إذا كان عاجزًا وهي قادرة. المقصود: الأولاد -الذرية- لا يعطوا من الزكاة، بل ينفق عليهم أبوهم، وأمهم من ماله إذا كانوا فقراء، وهكذا الآباء، والأمهات، والأجداد، والجدات لا يعطون من الزكاة، يعطون من غير الزكاة، نعم.  المقدم: يقول يا شيخ: هل صحيح أن الزكاة لا تدفع للذي يرثك؟ الشيخ: لا ما هو بلازم، إذا كان ..... إذا كان أخًا له يعطيه من الزكاة إذا كان فقيرًا على الصحيحن لا بأس، إنما المنع في الأصول والفروع، الأصول الآباء والأمهات، والأجداد والجدات، أو الفروع كالأولاد وأولاد الأولاد، وأولاد البنات، نعم.","link":"https://binbaz.org.sa/fatwas/16269/حكم-دفع-الزكاة-للاقارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77109.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":17426,"question":"مستمع من العراق هو حسن إسماعيل حسين العبيدي بعث برسالة، وضمنها قضية يقول فيها: يقع كثيرًا في هذا الزمان أن يتزوج الرجل المرأة على مهر مقدم ألف دينار مثلًا، والمؤخر عشرة آلاف دينار، ثم يترك المؤخر زمانًا طويلًا لا يؤديه إلى الزوجة، أو إلى أن يموت، فكيف الحال بالنسبة للزكاة؟","title":"حكم زكاة المؤجل من المهر","answer":"الجواب: ليس عليها زكاة إذا كان معسرًا به، إذا كان معسرًا ليس عليها زكاة، أما إذا كان مؤسرًا؛ فإن عليها أن تزكي المهر المؤجل؛ لأنها متى طلبته؛ فلها أخذه، وتأجيله برضاها، فعليها الزكاة إذا كان مؤسرًا، أما إن كان معسرًا فلا زكاة عليها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16290/حكم-زكاة-الموجل-من-المهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_835/nour_83518.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":17516,"question":"ما قولكم يحفظكم الله في تمويل المدارس بالزكاة لتعميرها، وإذا كانت الزكاة تصرف إلى طلبة العلم فمن باب أولى فيما أرى أن تصرف على المدارس؟","title":"حكم بناء المدارس من الزكاة","answer":"الجواب: المدارس لا تعمر بالزكاة، وهكذا المساجد وهكذا الربط لا تعمر بالزكاة، الزكاة لها مصارف بينها الله جل وعلا في قوله سبحانه: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِمِينَ وَفِي سَبِيلِ اللَّهِ وَاِبْنِ السَّبِيلِ فَرِيضَةً مِنَ اللَّهِ [التوبة:60]، هؤلاء أهل الزكاة. والمقصود في سبيل الله، يعني: الجهاد، هكذا قال جمهور أهل العلم: المراد به الجهاد، فلا تصرف أموال الزكاة في تعمير المساجد ولا تعمير المدارس والربط ولا غيرها من المشاريع الخيرية كإصلاح الطرقات أو إصلاح السفن لنقل الفقراء أو ما أشبه ذلك. لكن إذا دفعها للفقراء المحاويج من الطلبة في المدرسة، إذا كان فيها فقراء.. طلبة فقراء وأعطاهم من الزكاة أو مدرسين فقراء ليس لهم رواتب يقوم بحالهم وأعطاهم من الزكاة يعينهم على تدريس أبناء المسلمين، هذا كله طيب لا حرج، فيه مصلحتان: مصلحة أنهم فقراء ومصلحة أنهم يطلبون العلم أو يعلمون الناس. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16454/حكم-بناء-المدارس-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_837/nour_83710.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":17608,"question":"ما حكم دفع الزكاة إلى والدتي ووالدي وأخي وأختي؟","title":"حكم دفع الزكاة إلى الوالدين والإخوة","answer":"الجواب: دفع الزكاة للوالدين والأولاد لا يجزي عند جمهور أهل العلم بل حكاه بعضهم إجماع أهل العلم، أما دفعها للأخ أو الأخت أو العم أو العمة أو الأخوال أو بقية الأقارب فلا بأس إذا كانوا فقراء إذا كانوا من أهل الزكاة، أما الوالدان تنفق عليهما من مالك غير الزكاة، وهكذا أولادك وزوجتك تنفق عليهما من مالك.. عليهم من مالك لا من الزكاة، الزكاة لا تدفع للوالدين ولا للزوجة ولا للأولاد ولكن لبقية الأقارب إذا كانوا فقراء من إخوة أو أعمام أو أخوال أو بني عم أو غيرهم لا بأس إذا كانوا فقراء. نعم. صدقة وصلة.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16544/حكم-دفع-الزكاة-الى-الوالدين-والاخوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_842/nour_84207.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":17616,"question":"ما حكم دفع الزكاة إلى والدتي ووالدي وأخي وأختي؟","title":"حكم دفع الزكاة إلى الوالدين والإخوة","answer":"الجواب: دفع الزكاة للوالدين والأولاد لا يجزي عند جمهور أهل العلم بل حكاه بعضهم إجماع أهل العلم، أما دفعها للأخ أو الأخت أو العم أو العمة أو الأخوال أو بقية الأقارب فلا بأس إذا كانوا فقراء إذا كانوا من أهل الزكاة، أما الوالدان تنفق عليهما من مالك غير الزكاة، وهكذا أولادك وزوجتك تنفق عليهما من مالك.. عليهم من مالك لا من الزكاة، الزكاة لا تدفع للوالدين ولا للزوجة ولا للأولاد ولكن لبقية الأقارب إذا كانوا فقراء من إخوة أو أعمام أو أخوال أو بني عم أو غيرهم لا بأس إذا كانوا فقراء. نعم. صدقة وصلة.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16544/حكم-دفع-الزكاة-الى-الوالدين-والاخوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_842/nour_84207.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":17836,"question":"يقول السائل: هل يزكي الإنسان على ما أنفقه على نفسه علمًا بأنه أنفقه قبل حلول الحول عليه؟","title":"حكم زكاة ما أُنفق قبل تمام الحول","answer":"الجواب: المال الذي ينفق قبل تمام الحول ما فيه زكاة سواء كان نقودًا أو غيره، فلا بد في الزكاة من تمام الحول، فإذا كان عنده نقود وأنفقها في حاجاته قبل تمام الحول لا زكاة فيها، أو عنده غنم أو إبل أو بقر فلم يتم عليها الحول ماتت مثلاً أو باعها فلا زكاة فيها ولكن يزكي ثمنها إذا حال الحول يزكي ثمنها، نعم. ثمنها إذا حال الحول. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16829/حكم-زكاة-ما-انفق-قبل-تمام-الحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_779/nour_77909.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":17933,"question":"المستمع (م. ناجي عيسى) من جيزان بعث يسأل ويقول: إذا كان لي عند أحد الأشخاص مبلغًا من المال، ولم يستطع تسديده فهل لي أن أتركه له وأنا أنوي أنه زكاة عن جزء آخر من أموالي؟","title":"حكم احتساب دين المعسر من الزكاة","answer":"الجواب: ليس لك ذلك ولكن تمهله وتنظره حتى يوفيك إن شاء الله وتسامحه وتعفو عنه جزاك الله خيرًا، أما أن تجعل الدين الذي على المعسرين زكاة لك فلا، لا يصلح ذلك. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16955/حكم-احتساب-دين-المعسر-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_847/nour_84705.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":17965,"question":"يقول في سؤال آخر: أنا صاحب دكان، وقد سبق لي أن أقرضت أحد الأشخاص مالًا وكلما طلبت المبلغ يقول: لا أملك شيئًا، فهل يجوز لي أن أخصم ما عليه من مال الزكاة؟","title":"ما حكم جعل القرض زكاة؟","answer":"الجواب: لا. ليس لك أن تخصم ما عليه من مال الزكاة؛ لأن الزكاة دفع إيتاء للفقراء، ولكن تمهله حتى يوفي الله عنه؛ لأن الله يقول سبحانه: وَإِنْ كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَى مَيْسَرَةٍ [البقرة:280]، فعليك أن تنظر أخاك، يقول النبي ﷺ: من أنظر معسرًا أو وضع له أظله الله في ظله يوم لا ظل إلا ظله. فأنت بين أمرين: إما أن تنظره، وإما أن تبرئه من المال وتسامحه، وأما أن تسقطه من الزكاة فلا، لكن إذا أعطيته من الزكاة لفقره وأعاد ذلك إليك عن الدين من دون شرط بينك وبينه ولا تواطؤ فلا حرج، يعني: لو أعطيته من الزكاة ولكن هو رد إليك ذلك المال من الدين أو بعضه من الدين من دون تواطؤ بينكم ولا حيلة ولا شرط فلا بأس بهذا. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16996/ما-حكم-جعل-القرض-زكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_848/nour_84805.mp3","categories":["السلف والقرض","إخراج الزكاة وأهلها"]},{"id":18016,"question":"المستمع محمد سعد مصري يسأل ويقول: لدي مبلغ من المال ومضى عليه عام، ولي أقارب هل يجوز أن أبعث إليهم بزكاة مالي؟ جزاكم الله خيرًا.","title":"حكم دفع الزكاة للأقارب","answer":"الجواب: إذا كانوا فقراء فلا مانع أن تبعث إليهم؛ لأن لك في ذلك صلة وصدقة، يجتمع لك اثنان، يجتمع لك في ذلك اثنتان: صدقة وصلة كما قاله النبي ﷺ، يقول النبي ﷺ: الصدقة على المسكين صدقة وعلى ذي الرحم اثنتان؛ صدقة وصلة فإذا بعثت إليهم زكاتك لشدة حاجتهم فلا حرج، وإن أنفقتها في الفقراء الذين لديك في البلد فلا حرج. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17054/حكم-دفع-الزكاة-للاقارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_850/nour_85007.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18021,"question":"سماحة الشيخ! كثير من إخواننا يسألون هل يجوز أن تصرف الزكاة إلى ذوي المعاصي من المسلمين؟","title":"حكم إعطاء أهل المعاصي من الزكاة","answer":"الجواب: نعم، يجوز صرفها في ذوي المعاصي من المسلمين لكن لا تصرف في الكفرة غير المؤلفة، أما المؤلفة قلوبهم من الكفرة فيعطون أيضًا من الزكاة كما قال الله جل وعلا: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ [التوبة:60] الآية، أما العاصي فهو خير من الكافر فإن أعطاه لعل الله يهديه بسبب العطية.. الصدقة، لعل الله يهديه ويرده إلى الصواب بسبب إحسان قريبه إليه بالزكاة إذا كان فقيرًا، ولكن كونه يعتني بالطيبين المعروفين بالخير من الفقراء أولى من العصاة، هم أحق بالزكاة من العصاة، وإن صرفها لهم للعصاة يرجو بذلك أن يهديهم الله ويؤلفهم بهذا على الخير فهو مشكور مأجور. ولكن مهما كانت الحال فإنه يلتمس الأفضل فالأفضل من الفقراء من أقاربه حتى يعطيهم الزكاة ليعينهم على طاعة الله وليسد حاجتهم عن الحاجة إلى الناس، وإذا صرفها للفقير من العصاة بقصد صالح لعل الله يهديه، لعل الله يمن عليهم بالرجوع إلى الحق فهذا أمر حسن. نعم. المقدم: جزاكم الله خيرًا إذا كانوا من القبوريين أو كانوا من تاركي الصلاة؟ الشيخ: لا يعطون من الزكاة إلا إذا كان من السادة من الرؤساء الذين إذا أعطوا يرجى إسلامهم أو يرجى إسلام نظرائهم معهم، أو يرجى قوة إيمانهم إذا كانوا مسلمين فهم من المؤلفة، إذا كان يرجى في عطيته دخوله في الإسلام إن كان كافرًا أو قوة إيمانه إن كان ضعيف الإيمان، أو إسلام نظرائه إذا أعطوا، إذا أعطي قال نظراؤه سوف يعطونا إذا أسلمنا فيسلمون. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17056/حكم-اعطاء-اهل-المعاصي-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_850/nour_85008.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18066,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من جمهورية جيبوتي، وباعثها أحد الإخوة المستمعين من هناك يقول: محمد علي يوسف، أخونا له مقدمة في رسالته ننطلق منها إلى السؤال فيقول: هناك من المسلمين من يعمل في المحاماة، الشخص الذي يعمل محاميًا أحيانًا يدافع عن الظالم، ويعرف أنه ظالم، وإذا سألته: لماذا تدافع عن الظالم؟ يقول: هذه مهنتي.والسؤال المطروح هو: هل في الإسلام محاماة؟ وما هو حكم الإسلام في المحاماة والمحامين؟ أفيدونا جزاكم الله خيرًا.","title":"حكم احتراف المحاماة والدفاع عن الظالم؟","answer":"الجواب: بسم الله الرحمن الرحيم. الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فالمحاماة لها خطر عظيم، وهي وكالة في المخاصمة عن الشخص الموكل، فإن كان الوكيل وهو المحامي يتحرى الحق، ويطلب الحق ويحرص على إيصال الحق إلى مستحقه، ولا يحمله كونه محاميًا على نصر الظالم، وعلى التلبيس على الحكام والقضاة ونحوهم؛ فإنه لا حرج عليه؛ لأنه وكيل. أما إذا كانت المحاماة تجره إلى نصر الظالم وإعانته على المظلوم، أو على تدليس الدعوى، أو على طلب شهود الزور أو ما أشبه ذلك من الباطل، فهي محرمة وصاحبها داخل في عداد المعينين على الإثم والعدوان. وقد صح عن رسول الله عليه الصلاة والسلام أنه قال: انصر أخاك ظالمًا أو مظلومًا. قالوا: يا رسول الله! نصرته مظلومًا فكيف أنصره ظالمًا؟ قال: تحجزه عن الظلم يعني: تمنعه من الظلم فذلك نصرك إياه فهذا هو نصر الظالم أن يمنع من الظلم وأن لا يعان على الظلم. فإذا كان المحامي يعينه على الظلم فهو شريك له في الإثم وعمله منكر وهو متعرض لغضب الله وعقابه نسأل الله العافية، وهكذا كل وكيل وإن لم يسم محاميًا ولو سمي وكيلًا، إذا كان يعين موكله على الظلم والعدوان وعلى أخذ حق الناس بالباطل فهو شريك له في الإثم وهو ظالم مثل صاحبه، نسأل الله للجميع العافية والهداية والسلامة. المقدم: جزاكم الله خيرًا، كأني بسماحة الشيخ ينصح بعدم الاشتغال بهذه المهنة؟ الشيخ: نعم. أنصح بعدم الاشتغال بها إلا لمن وثق من نفسه بأنه يتحرى الشرع، ويعين على تحقيق الشرع، وينصر المظلوم، ولا يعين الظالم، أما إذا كانت نفسه تميل إلى أخذ المال بغير حق، وإلى مناصرة من وكله ومن جعله محاميًا عنه؛ فهذا لا يجوز له بل يجب الحذر. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17101/حكم-احتراف-المحاماة-والدفاع-عن-الظالم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_902/nour_90201.mp3","categories":["إخراج الزكاة وأهلها","الوكالة"]},{"id":18128,"question":"أخونا له سؤال آخر يقول: هل الزكاة تجوز في بناء وتعمير المساجد أم لا؟","title":"حكم صرف الزكاة في تعمير المساجد","answer":"الجواب: لا يجوز تعمير المساجد من الزكاة عند جمهور أهل العلم، بل هو كالإجماع من أهل العلم، وإنما أجاز هذا بعض المتأخرين، وليس عليه دليل، بل الصواب: أن الزكاة تصرف في مصارفها الثمانية، وليس من ذلك تعمير المساجد ولا المدارس ولا غيرها، بل الزكاة تصرف في الجهات الثمانية المذكورة في قوله جل وعلا: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِمِينَ وَفِي سَبِيلِ اللَّهِ وَاِبْنِ السَّبِيلِ فَرِيضَةً مِنَ اللَّهِ وَاللَّهُ عَلِيمٌ حَكِيمٌ [التوبة:60]. قال جمهور أهل العلم: معنى قوله: في سبيل الله: يعني: الجهاد، وبعض المتأخرين قال: في سبيل الله يعم الجهاد والمساجد والمدارس والربط.. وأشباه ذلك من المشاريع الخيرية كالقناطر وإصلاح الطرق أو نحو ذلك، ولكن الذي عليه أكثر أهل العلم وهو الأرجح: أن في سبيل الله يخص الجهاد والدعوة إلى الله سبحانه؛ لأنها من الجهاد، أما المساجد والمدارس والقناطر والربط.. ونحو ذلك، هذه تعمر من بيت المال، ومن مساعدة المسلمين ومساهمة المسلمين؛ لأنها مصالح عامة. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/17180/حكم-صرف-الزكاة-في-تعمير-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_852/nour_85205.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18248,"question":"هذا سائل لم يذكر الاسم في هذه الرسالة يقول سماحة الشيخ: لي أولاد أخ من أبي غير شقيق هل يجوز أن أصرف لهم الزكاة من باب: أَوْلَى لَكَ فَأَوْلَى[القيامة:34] وهل يجوز أن أعمل لهم راتبًا شهريًا من هذه الزكاة وليس دفعة واحدة، أي: على مدار العام، أفيدونا سماحة الشيخ؟الشيخ: أعد أعد.المقدم: يقول: لي أولاد أخ من أبي غير شقيق، هل يجوز أن أصرف لهم الزكاة؟ وهل يجوز أن أعمل لهم راتبًا شهريًا من هذه الزكاة وليس دفعة واحدة أي: على مدار العام مأجورين؟","title":"حكم دفع الزكاة إلى أولاد الأخ غير الشقيق","answer":"الجواب: إذا كانوا فقراء فلا بأس، وليسوا في حضانتك، ليسوا في عيالك، بل هم مستقلون، وهم فقراء لا مانع أن يعطوا من الزكاة. أما ترتيبها لهم فلا بأس إذا كان معجلة، أما تأخيرها لا، الواجب البدار بصرف الزكاة، لكن إذا كانت معجلة تعجلها لهم قبل وقتها فلا بأس، أما التأخير لا، بل متى حال الحول وجب صرف الزكاة فيهم وفي غيرهم، من المستحقين للزكاة، وعدم تأجيلها. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17297/حكم-دفع-الزكاة-الى-اولاد-الاخ-غير-الشقيق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_783/nour_78304.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18281,"question":"الاسم: بشير الطاهر جبريل، من السودان، يسأل الأخ بشير ويقول: لي صديق طلب مني مبلغًا قدره ثلاثة آلاف وثمانمائة جنيه، وقال لي: أسلمك هذا المبلغ في خلال شهر أو شهرين، وأنا سلمته ذلكم المبلغ في عام ستة وثمانين، والآن نحن في عام ثمانية وثمانين، ولم أستلم المبلغ؛ هل تجب علي زكاته؟ أو كيف أتصرف؟","title":"هل يجب إخراج الزكاة على الدين؟","answer":"الجواب: هذا فيه تفصيل: إذا كان الذي عنده المبلغ موسرًا، ولو طلبته المال لأعطاك فإنك تزكيه، أما إذا كان يماطلك، أو معسرًا فلا زكاة عليك، إذا كنت طلبته فأبى وماطل حتى مضت المدة، فإنه لا زكاة عليك، أما إذا كان التأخير منك وإلا هو مليء فعليك الزكاة لكل الأعوام، أما إذا كان مماطلًا أو معسرًا فلا زكاة عليك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17330/هل-يجب-اخراج-الزكاة-على-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_910/nour_91017.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18351,"question":"السائل الذي رمز لاسمه بـ (أ. أ)، يقول: هل يجوز الصرف على المساجد، وذلك لترميمها وفرشها الفرش الطيب ونحو ذلك وذلك من الزكاة؟","title":"حكم الصرف على المساجد من الزكاة","answer":"الجواب: المساجد ليست من مصارف الزكاة لا بناؤها، ولا فرشها، مصارف الزكاة وضحها الرب جل وعلا في قوله سبحانه: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِمِينَ وَفِي سَبِيلِ اللَّهِ وَاِبْنِ السَّبِيلِ[التوبة:60]. فليست المساجد من مصارف الزكاة لا بناء ولا فرشًا ولا غير ذلك، وفي سبيل الله يعني: الجهاد، فالزكاة لا تصرف في المساجد لا في تعميرها، ولا في فرشها. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17409/حكم-الصرف-على-المساجد-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_783/nour_78319.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18373,"question":"سماحة الشيخ! السائل: (أ. ش) من حلب يقول: هل تجوز الزكاة على زوج البنت، أو على زوجة الولد إذا كانوا بحاجة؟","title":"حكم دفع الزكاة لزوج البنت","answer":"الجواب: إذا كانوا فقراء لا بأس، إذا كانوا فقراء زوج البنت، وزوج الخالة، وزوج الأخت. نعم.","link":"https://binbaz.org.sa/fatwas/17433/حكم-دفع-الزكاة-لزوج-البنت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91328.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18480,"question":"في آخر أسئلة هذا السائل سمير يقول في السؤال الأخير: هل يصح أن أخرج عن زوجتي زكاة حليها التي تلبسه للزينة؟ وما القول الراجح في ذلك سماحة الشيخ؟","title":"حكم إخراج الزوج الزكاة عن زوجته","answer":"الجواب: لا بأس أن تخرج عنها الزكاة إذا رضيت، إذا سمحت لك بإخراج زكاة حليها لا بأس، والراجح أن الحلي فيها زكاة هذا الراجح، إذا بلغت النصاب وحال عليها الحول من الذهب والفضة فالراجح أن فيها الزكاة، هذا هو الأرجح من أقوال العلماء، وإذا سمحت لزوجها، أو لأبيها، أو لأخيها؛ أن يخرج الزكاة من ماله عنها فلا بأس.\nالمقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17567/حكم-اخراج-الزوج-الزكاة-عن-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_785/nour_78516.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18553,"question":"يسأل أخونا ويقول: ما هي الكيفية التي يجب أن أزكي بها راتبي الشهري، مع العلم بأني موظف، وليس لدي من الأموال غير هذا الراتب الذي أتقاضاه، هل أزكي كل راتب ساعة استلامه شهرًا بشهر كزكاة الزروع والثمار، أم أنتظر حتى يحول الحول على كل شهر، ثم أزكي رصيده في نفس الشهر من العام المقبل أم ماذا أفعل؟جزاكم الله خيرًا.","title":"كيفية زكاة الراتب الشهري","answer":"الجواب: الواجب أن يزكى الراتب وغير الراتب إذا حال حوله، فإذا حصل لك في رمضان عشرة آلاف ريال، وبقيت إلى الحول زكيتها، أو بقي نصفها زكيت الباقي، وهكذا في شوال، وهكذا في ذي القعدة، وهكذا في ذي الحجة، كل شهر بشهره، إذا حال حوله تزكي ما بقي منه، وتضبط الأمور بالكتابة حتى تحفظ ما يجب عليك، هذا الواجب عليك، ولا يجب إخراج الزكاة من حين وصول مرتبك إليك، لا، الواجب إذا حال الحول كما قال ابن عمر وغيره: «من استفاد مالًا فلا زكاة عليه حتى يحول عليه الحول»، وجاء مرفوعًا عن النبي ﷺ من حديث علي : لا زكاة في مال حتى يحول عليه الحول هذا هو الصواب. أما قول من قال: إنه يزكي ما حصل له من هبة، أو مرتب من حين استلامه بدون حول؛ فهذا قول ضعيف مرجوح، والصواب: أنه لا يجب في الإرث ولا فيما يهدى إليك، ولا في مرتبك زكاة حتى يحول الحول على ذلك، على نصيبك من المال في الإرث إذا كان نقود من الذهب والفضة، حتى يحول الحول. وهكذا لا يجب عليك الزكاة فيما وهبك أحد إخوانك، أو أهدى إليك أحد إخوانك ليس عليك زكاتها حتى يحول عليها الحول، فإذا أنفقته قبل ذلك فلا شيء عليك، وهكذا المرتب إنما تجب زكاته إذا حال عليه الحول، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/17661/كيفية-زكاة-الراتب-الشهري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_916/nour_91604.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18573,"question":"في آخر أسئلة هذا السائل -أبو محمد- يقول: سمعت في شهر رمضان من يقول: بأن الواجب في الزكاة هو اثنين ونص، وأن من يدفع ثلاثة بالمائة، فإنه يكون محادًا لله أو محادًا لله ولرسوله، وأنا في بعض الأحيان أدفع أكثر من اثنين ونص، وليس قصدي المحادة لله ولا للرسول، وإنما قصدي الرغبة في الخير -إن شاء الله- فما رأي سماحتكم في ذلك؟","title":"حكم من دفع زيادة عن الواجب في الزكاة","answer":"الجواب: الواجب اثنان ونصف في المائة، يعني: ربع العشر في الزكاة، خمسة وعشرون في الألف، واحد ألف في أربعين ألفًا، ربع العشر، هذا الواجب، وإذا أحب يخرج الزيادة تطوعًا منه مأجور، ولا حرج في ذلك. أما إذا كان يعتقد أن هذا الربع لا يجزئ، وأن الشرع ناقص؛ هذا غلط، الشرع كامل والحمد لله، فإذا اعتقد أن الشرع ناقص، وأنه يريد أزيد مما شرع الله، يظن أن الشرع ناقص هذا غلط كبير. أما إذا أراد التطوع والزيادة في الفضل فهذا مأجور، ولا بأس، فإذا كانت عليه زكاة ألف وأخرج ألفين، ألف تطوع وألف زكاة؛ فهذا مأجور، وله فضل عظيم، وأجر عظيم، وهكذا إذا كان عليه خمسة آلاف أو أكثر، وأخرج عشرة كله طيب. المقصود: إذا كانت الزيادة عن رغبة في الخير، وعن مرحمة للفقراء، وأنه يعلم أن ما شرعه الله كافٍ؛ فلا حرج، مأجور، ومثاب، ومخلوف عليه. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17689/حكم-من-دفع-زيادة-عن-الواجب-في-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_786/nour_78617.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18574,"question":"في آخر أسئلة هذا السائل -أبو محمد- يقول: سمعت في شهر رمضان من يقول: بأن الواجب في الزكاة هو اثنين ونص، وأن من يدفع ثلاثة بالمائة، فإنه يكون محادًا لله أو محادًا لله ولرسوله، وأنا في بعض الأحيان أدفع أكثر من اثنين ونص، وليس قصدي المحادة لله ولا للرسول، وإنما قصدي الرغبة في الخير -إن شاء الله- فما رأي سماحتكم في ذلك؟","title":"حكم من دفع زيادة عن الواجب في الزكاة","answer":"الجواب: الواجب اثنان ونصف في المائة، يعني: ربع العشر في الزكاة، خمسة وعشرون في الألف، واحد ألف في أربعين ألفًا، ربع العشر، هذا الواجب، وإذا أحب يخرج الزيادة تطوعًا منه مأجور، ولا حرج في ذلك. أما إذا كان يعتقد أن هذا الربع لا يجزئ، وأن الشرع ناقص؛ هذا غلط، الشرع كامل والحمد لله، فإذا اعتقد أن الشرع ناقص، وأنه يريد أزيد مما شرع الله، يظن أن الشرع ناقص هذا غلط كبير. أما إذا أراد التطوع والزيادة في الفضل فهذا مأجور، ولا بأس، فإذا كانت عليه زكاة ألف وأخرج ألفين، ألف تطوع وألف زكاة؛ فهذا مأجور، وله فضل عظيم، وأجر عظيم، وهكذا إذا كان عليه خمسة آلاف أو أكثر، وأخرج عشرة كله طيب. المقصود: إذا كانت الزيادة عن رغبة في الخير، وعن مرحمة للفقراء، وأنه يعلم أن ما شرعه الله كافٍ؛ فلا حرج، مأجور، ومثاب، ومخلوف عليه. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17689/حكم-من-دفع-زيادة-عن-الواجب-في-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_786/nour_78617.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18691,"question":"هذه رسالة بعث بها المستمع عبده محمد موسى حكمي، أخونا يسأل سؤال، ويقول فيه:ما معنى الوكالة لغة وشرعًا؟ وما أنواعها وحكمها؟ وهل يجوز إلغاؤها ومتى؟ وهل تجوز من الأعمى الوكالة، كأن يكون وكيلًا أو موكلًا؟ وهل تجوز الوكالة في عقد القران -الزواج-؟وما حكم إذا وكل شخص شخصًا آخر في البيع والشراء هل يجوز ذلك أو لا؟ وهل له أن يشتري لنفسه؟أرجو التكرم بالإجابة عن هذه الأسئلة، جزاكم الله خيرًا","title":"تعريف الوكالة والأمور التي تجري فيها","answer":"الجواب: الوكالة لغة: التفويض، التفويض إلى الشخص، وإسناد الأمور إليه فيما يراه الموكل له، في إصلاح مزرعته، في تربية أولاده، في أي شيء من الأمور التي يحتاج إليها الإنسان. أما هي شرعًا: فهي الاستنابة من جائز التصرف لشخص آخر يجوز تصرفه فيما تدخله النيابة، في الشيء الذي تدخله النيابة.  أما ما لا تدخله النيابة كأن يستنيبه أن يصلي عنه، أو يصوم عنه رمضان، أو ما أشبه ذلك هذا لا يجوز، لكن أن يستنيبه، وهو جائز التصرف كالرجل المكلف والمرأة المكلفة الرشيد والرشيدة، يستنيبان من يقوم عنهما ببيع السلعة والآنية، ببيع بيتهما، ببيع سيارتهما، وما أشبهه مما يجوز التصرف فيه، أو يستنيبانه في شراء كذا وكذا، مما يجوز شراؤه، أو يستنيبانه في إحضار كذا وكذا من محل كذا وكذا، أو ما أشبه ذلك مما تجوز فيه النيابة، هذه يقال لها: وكالة. وهي جائزة من جائز التصرف، لمن يصلح أن يقوم بذلك العمل، وهكذا التوكيل في عقد النكاح لمن يصلح لذلك كالرجل دون المرأة، فالمرأة لا توكل في إجراء عقد النكاح؛ لأنها لا يصح أن تكون ولية فيه، لا يصلح أن تزوج نفسها ولا غيرها، فإذا وكل من ينوب عنه في إجراء عقد النكاح؛ كالولي يوكل، أو في قبول النكاح؛ كالزوج يوكل، لا بأس بذلك، أو المرأة يوكل أخاها، أو يوكل أجنبيًا يزوج بنته لا بأس به إذا كان الوكيل صالحًا لذلك، وهكذا الزوج يوكل من يقبل عنه النكاح، لا بأس بذلك، وهكذا في جميع المسائل التي تدخلها النيابة يجوز أن يوكل الإنسان من جائز التصرف الرشيد لمن يصلح تصرفه في مثل هذا الأمر كما تقدم، نعم. المقدم: سواء كان أعمى أو بصيرًا؟ الشيخ: لا فرق بين الأعمى والبصير، والحر والعبد، يعني: إذا كان مثله يصلح لهذا الأمر، نعم. المقدم: أيضًا في عقد القران كذلك؟ الشيخ: نعم، يجوز إذا كان من أهل ذلك، أما المرأة لا، والكافر لا في زواج المسلمة، نعم. المقدم: يشتري لنفسه أو لا؟ الشيخ: يشتري أو يبيع، نعم. المقدم: أيضًا كذلك؟ الشيخ: نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17791/تعريف-الوكالة-والامور-التي-تجري-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_873/nour_87301.mp3","categories":["إخراج الزكاة وأهلها","الوكالة"]},{"id":18736,"question":"يقول السائل في رسالته أو في سؤاله: هل يجوز إخراج زكاة المال في كل شهر، فقد أفتى لنا بعض الإخوة في ذلك؟ مأجورين.","title":"حكم إخراج زكاة المال في كل شهر","answer":"الجواب: نعم، إذا رأى المصلحة في ذلك عجلها، إذا رأى المصلحة في ذلك، لا بأس، قد كان النبي ﷺ يتعجل من العباس بعض زكاته . فالمقصود: أنه إذا رأى التعجيل فيه مصلحة فهو مسارعة إلى الخيرات، مثل زكاته التي في رمضان، ولكن رأى فقراء محتاجين وعجلها لهم في رجب أو في جمادى فهو مأجور لا بأس، نعم. المقدم: أليس شرطًا يا سماحة الشيخ أن يحول عليه الحول؟ الشيخ: ما هو بشرط، لا. المقدم: ليس شرطًا. الشيخ: شرط للوجوب، لا تجب عليه حتى يحول عليه الحول، لكن لو عجلها قبل أن يحول طلبًا للفضل فهو مأجور. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17861/حكم-اخراج-زكاة-المال-في-كل-شهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_789/nour_78912.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18797,"question":"يقول هذا السائل (أ. أ) الرياض أقرضت رجلًا مبلغًا من المال، وقد تأخر عنده هذا المبلغ، وهو كامل النصاب، فهل أقوم بتزكيته؟","title":"حكم إخراج الدائن زكاة ماله الذي في ذمة المدين","answer":"الجواب: إذا كان الذي عليه المال مليء متى طلبته أعطاك عليك الزكاة، أما إن كان معسرًا، أو مماطلًا طلبته، ولم يعطك مماطلًا فليس عليك الزكاة؛ لأنك غير قادر عليه، أما إذا كان مليًا وليس بمماطل، ولكن أنت تساهلت فإنك تزكي. أما الديون على المعسرين فلا زكاة فيها حتى تقبضها، وهكذا المماطل الذي تطلبه حقك ولا يعطيك فليس عليك زكاته حتى تقبض وتبتدي حولًا، نعم. المقدم: يزكي عنه كم سنة -يا شيخ- إذا كان مر عليه أكثر من سنة؟ الشيخ: إذا كان على معسر ما فيه زكاة، أو على مماطل لم يعطه حقه لا زكاة فيه، أما إذا كان مليء، ولكن هو يتساهل يزكيه جميع السنين. المقدم: جميع السنين؟ الشيخ: نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17930/حكم-اخراج-الداىن-زكاة-ماله-الذي-في-ذمة-المدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79115.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18818,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، سوداني مقيم بالطائف واسمه (ع. س. أبو موسى) أخونا كتب رسالته بلهجته العامية، فهمت منها ما يلي: يسأل عن صرف الزكاة إلى الأخت من الأب وأبنائها، وإلى الأب وإخواني من أبي، ويسأل أيضًا عن بعث الزكاة إلى بلده لكثرة الفقراء هناك.","title":"صرف الزكاة للأقربين","answer":"الجواب: لا مانع من صرف الزكاة لإخوتك الذكور والإناث إذا كانوا محاويج فقراء، هذا فيه الصلة والزكاة جميعًا صلة وصدقة، يقول النبي ﷺ: الصدقة على الفقير صدقة، وعلى ذي الرحم اثنتان صدقة وصلة فإذا كان أخو الإنسان فقيرًا أو أخته فقيرة أو عمه أو خاله أو نحو ذلك فالصدقة فيهم أولى من غيرهم؛ لأنها تجمع أمرين: الصلة والصدقة جميعًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17941/صرف-الزكاة-للاقربين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_921/nour_92104.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18828,"question":"أعطيت زكاة مالي لإخوتي الذين ليس لهم القدرة على تكاليف الزواج هذه الأيام من سكن وغيره؛ وذلك حتى يستطيعوا التزوج، فهل يجزئ ذلك؟","title":"حكم إعطاء الزكاة للإخوة لإعانتهم على الزواج","answer":"الجواب: نعم، صدقة الإخوان والمساعدة في الزواج إذا كانوا فقراء من أفضل القرب، ولا بأس أن يكون من الزكاة، إذا كانوا فقراء مثل ما قلت، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17961/حكم-اعطاء-الزكاة-للاخوة-لاعانتهم-على-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73606.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":18889,"question":"هل يمكن أن نعطي الزكاة أو الصدقة للخادمة؟","title":"حكم إعطاء الخادمة الزكاة أو الصدقة","answer":"الجواب: إذا كانت فقيرة تعلم حالها، وأعطيتها من الزكاة لا بأس، لكن الاحتياط أن يكفيها راتبها، وتعطي ناسًا تعرف حالهم وفقرهم، تواسيهم تحسن إليهم. أما الخادمة فقد يختلف في أمرها، قد لا تعلم حالها كما ينبغي، ولعل في راتبها ما يكفي، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18031/حكم-اعطاء-الخادمة-الزكاة-او-الصدقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73619.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":19324,"question":"المستمع (ف. ع. أ) بعث برسالة يقول فيها: إنني أعمل بمزرعة، وأقتضي راتبًا شهريًا، فهل هذا المال الذي أجمعه تجب فيه الزكاة، مع العلم بأنني شاب في سن الزواج، وفي احتياج هذا المال؛ لأنني أقوم حاليًا ببناء منزل تمهيدًا للزواج، ولا أحد يساعدني من أسرتي؟ جزاكم الله خيرًا.","title":"حكم إخراج الزكاة عن الراتب","answer":"الجواب: عليك أن تزكي ما جمعت إذا حال عليه الحول، كلما حال الحول على شيء تزكيه، ولو أنك أعددته للزواج أو لبناء مسكن أو غير ذلك، إذا حال الحول على الراتب الأول زكه، وهكذا الراتب الثاني، وهكذا، كلما حال الحول على راتب زكه بربع العشر في المائة ريالان ونصف في الألف خمسة وعشرون، وأبشر بالخير؛ فالزكاة طهرة لك ولمالك، ومن أسباب النماء والبركة والحفظ.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18521/حكم-اخراج-الزكاة-عن-الراتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_739/nour_73917.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":19325,"question":"من المدينة المنورة رسالة باعثها مستمع من هناك يقول: (ح. س. ن) أخونا يقول: هل تجوز الزكاة لأسرة فقيرة أحد أفرادها لا يصلي؟ وهو يأكل معهم؟ فإذا لم تجب فهل يجب إعادة الزكاة كلها؟ أم جزء منها بنسبة هذا الفرد إلى عدد أسرته؟","title":"حكم إخراج الزكاة لأسرة فقيرة أحد أفرادها لا يصلي","answer":"الجواب: الزكاة يعطاها من يستحقها من المسلمين، ولو أكل معهم شخص آخر غير مسلم، المقصود يعطاها المسلمون والفقراء المحتاجون إليها، ولا يضرهم كونه يوجد بينهم من قد يحكم بكفره، إذا كانت معطاة ومسلمة للمسلم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18522/حكم-اخراج-الزكاة-لاسرة-فقيرة-احد-افرادها-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_739/nour_73918.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":19431,"question":"إذا تصدق رجل بمبلغ معين للأيتام شهريًا، ولم يخرج زكاة ماله، مع العلم أن الصدقة التي يتصدق بها أكبر من الزكاة المستحقة بكثير، فهل يجزيه ذلك عن الزكاة حتى إذا لم ينو أن تكون هذه الصدقة هي زكاة ماله؟","title":"وجوب استحضار النية عند إخراج الزكاة","answer":"الجواب: إذا كان الأيتام فقراء، ونوى ما صرفه فيهم زكاة؛ فلا بأس، أما إذا كان ما نوى، وإنما تصدق عليهم، وأنفق عليهم احتسابًا؛ ولم ينوه زكاة، فإنها لا تجزئ لا تكون زكاة إلا بالنية لقول المصطفى عليه الصلاة والسلام: إنما الأعمال بالنيات وإنما لكل امرئ ما نوى. فإذا أعطى فقيرًا أو يتيمًا فقيرًا مالًا ولم ينوه زكاة، وإنما نواه صدقة، ومساعدة؛ فإنه لا يكون من الزكاة، ولا يحسب من الزكاة إلا إذا نوى ما صرفه لليتيم الفقير أو للسائل الفقير إذا نواه زكاة صار زكاة، الأعمال بالنيات، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18680/وجوب-استحضار-النية-عند-اخراج-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_944/nour_94403.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":19440,"question":"يسأل أخونا ويقول: وهل يصح أن أرسل الزكاة إلى إخوتي في مصر؛ لأنهم في الحاجة؟","title":"حكم إرسال المزكي زكاته إلى إخوته المحاويج","answer":"الجواب: لا حرج إن شاء الله لا بأس ، نعم، ترسلها إلى إخوتك المحاويج لا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18681/حكم-ارسال-المزكي-زكاته-الى-اخوته-المحاويج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_938/nour_93806.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":19479,"question":"هذا سائل يقول: سماحة الشيخ! رجل يرغب في الزواج وهو غير مستطيع، هل تجوز له الزكاة ليتمكن من الزواج؟","title":"حكم صرف الزكاة لمن عجز عن الزواج","answer":"الجواب: نعم، العاجزون عن الزواج يعطون من الزكاة ما يعينهم على الزواج، إذا كانوا عاجزين يشرع أن يعطوا من الزكاة ما يعينهم على الزواج. نعم.","link":"https://binbaz.org.sa/fatwas/18726/حكم-صرف-الزكاة-لمن-عجز-عن-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93914.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":19481,"question":"هل تجوز الزكاة للأخ والعم والخال والأخت والعمة، إذا كانوا في حاجة للزكاة؟","title":"حكم دفع الزكاة للإخوة والأعمام والأخوال","answer":"الجواب: نعم إذا كان أخوه مستقلًا ليس في نفقته، وهكذا الخالة والعمة مستقلين يعطون من الزكاة إذا كانوا فقراء، صدقة وصلة، الزكاة فيهم صدقة وصلة في العم والخال والأخ وابن الأخ وابن الخال إذا كانوا فقراء مستقلين. نعم.","link":"https://binbaz.org.sa/fatwas/18727/حكم-دفع-الزكاة-للاخوة-والاعمام-والاخوال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93915.mp3","categories":["زكاة النقدين","إخراج الزكاة وأهلها"]},{"id":19692,"question":"الوكيل على الوقف أضحية أو غيرها أحب أن يجعل عنه وكيلًا، فمن الأولى: الأولاد أم الإخوة؟ وإذا لم ينص على تفويضه بالتوكيل، فماذا يعمل؟","title":"التوكيل في الوقف","answer":"الجواب:\n\nإذا لم ينص الموصي بحق الوكيل للتوكيل، فإن التوكيل للحاكم، وللوكيل الحق أن يرشح من فيه الكفاءة أخًا أو ابنًا[1].\n\n\n\n\tمن ضمن أسئلة شخصية مقدمة لسماحته من السائل/م. م، وأجاب عنه سماحته بتاريخ 4/9/1418هـ. (مجموع فتاوى ومقالات الشيخ ابن باز 20/22).","link":"https://binbaz.org.sa/fatwas/19030/التوكيل-في-الوقف","audio":"","categories":["إخراج الزكاة وأهلها","الوكالة"]}]
